import time
import signal
import sys
import logging
import threading

import smbus
import RPi.GPIO as GPIO

try:
    from lsm303 import LSM303
except ImportError:
    LSM303 = None

try:
    from Adafruit_ADS1x15 import ADS1015
except ImportError:
    ADS1015 = None

try:
    from StepperMotor import StepperMotor
except ImportError:
    StepperMotor = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

I2C_BUS = 1
LSM303_ADDRESS = 0x1D
ADS1015_ADDRESS = 0x48

DIR_PIN = 20
STEP_PIN = 21
MS0_PIN = 14
MS1_PIN = 15

PWM_FREQUENCY = 500
ADC_GAIN = 1
ADC_CHANNEL = 0

running = True
motor = None
i2c_bus = None


def signal_handler(signum, frame):
    global running
    logger.info(f"Signal {signum} received, shutting down...")
    running = False


def initialize_hardware():
    global motor, i2c_bus
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        motor = StepperMotor(DIR_PIN, STEP_PIN, MS0_PIN, MS1_PIN)
        motor.set_resolution(StepperMotor.FULL)
        motor.set_direction(StepperMotor.CW)
        motor.set_pwm_frequency(PWM_FREQUENCY)
        motor.start_pwm()
    except Exception as e:
        logger.error(f"Failed to initialize stepper motor: {e}")
        return False

    try:
        i2c_bus = smbus.SMBus(I2C_BUS)
    except Exception as e:
        logger.error(f"Failed to initialize I2C bus {I2C_BUS}: {e}")
        return False

    if LSM303 is not None:
        try:
            lsm = LSM303(i2c_bus, address=LSM303_ADDRESS)
        except Exception as e:
            logger.error(f"Failed to initialize LSM303 at 0x{LSM303_ADDRESS:02X}: {e}")
            lsm = None
    else:
        lsm = None

    if ADS1015 is not None:
        try:
            adc = ADS1015(i2c_bus, address=ADS1015_ADDRESS)
        except Exception as e:
            logger.error(f"Failed to initialize ADS1015 at 0x{ADS1015_ADDRESS:02X}: {e}")
            adc = None
    else:
        adc = None

    return lsm, adc


def read_adc_voltage(adc, channel):
    if adc is None:
        return None
    try:
        value = adc.read_adc(channel, gain=ADC_GAIN)
        voltage = value * (3.3 / 1023.0)
        return voltage
    except Exception as e:
        logger.error(f"Error reading ADC channel {channel}: {e}")
        return None


def read_acceleration(lsm):
    if lsm is None:
        return None, None, None
    try:
        return lsm.read_acceleration()
    except Exception as e:
        logger.error(f"Error reading acceleration: {e}")
        return None, None, None


def read_magnetic_field(lsm):
    if lsm is None:
        return None, None, None
    try:
        return lsm.read_magnetic_field()
    except Exception as e:
        logger.error(f"Error reading magnetic field: {e}")
        return None, None, None


def calculate_heading(x, y, z):
    try:
        angle = 90.0 + (180.0 / 3.141592653589793) * (float(y) / float(x))
        return (360.0 + angle) % 360.0
    except ZeroDivisionError:
        return 0.0


def calculate_inclination(x, y, z):
    try:
        xz_angle = (180.0 / 3.141592653589793) * (float(x) / float(z))
        yz_angle = (180.0 / 3.141592653589793) * (float(y) / float(z))
        return xz_angle, yz_angle
    except ZeroDivisionError:
        return 0.0, 0.0


def map_value(value, from_min, from_max, to_min, to_max):
    if from_max == from_min:
        return to_min
    return (value - from_min) * (to_max - to_min) / (from_max - from_min) + to_min


def control_motor(voltage):
    if motor is None:
        return
    try:
        pwm_duty_cycle = int(map_value(voltage, 0, 3.3, 0, 255))
        pwm_duty_cycle = max(0, min(255, pwm_duty_cycle))
        motor.set_pwm_duty_cycle(pwm_duty_cycle)
    except Exception as e:
        logger.error(f"Error controlling motor: {e}")


def cleanup():
    global motor, i2c_bus
    logger.info("Cleaning up resources...")
    if motor is not None:
        try:
            motor.stop_pwm()
        except Exception as e:
            logger.error(f"Error stopping motor PWM: {e}")
    if i2c_bus is not None:
        try:
            i2c_bus.close()
        except Exception as e:
            logger.error(f"Error closing I2C bus: {e}")
    GPIO.cleanup()
    logger.info("Cleanup complete.")


def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    lsm, adc = initialize_hardware()
    if lsm is None and adc is None:
        logger.error("No hardware initialized. Exiting.")
        cleanup()
        sys.exit(1)

    try:
        while running:
            voltage = read_adc_voltage(adc, ADC_CHANNEL)
            if voltage is not None:
                control_motor(voltage)

            accel_x, accel_y, accel_z = read_acceleration(lsm)
            mag_x, mag_y, mag_z = read_magnetic_field(lsm)

            if accel_x is not None and accel_y is not None and accel_z is not None:
                xz_angle, yz_angle = calculate_inclination(accel_x, accel_y, accel_z)
                logger.info(f"Inclination (XZ): {xz_angle:.2f} deg, Inclination (YZ): {yz_angle:.2f} deg")

            if mag_x is not None and mag_y is not None and mag_z is not None:
                heading = calculate_heading(mag_x, mag_y, mag_z)
                logger.info(f"Heading: {heading:.2f} deg")

            time.sleep(1)
    except Exception as e:
        logger.error(f"Unexpected error in main loop: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

