#!/usr/bin/env python3
"""
SoundSensor: digital (KY-038) and analog (MCP3008) sound sensor reader for Raspberry Pi.

Digital sensors produce a digital HIGH/LOW signal on a GPIO pin.
Analog sensors are read via an MCP3008 10-bit ADC on SPI bus 0, device 0.

Usage:
    python sound_sensor.py --sensor_type digital --gpio_pins 17 --threshold 1 --sample_rate 1 --log_file sound.log
    python sound_sensor.py --sensor_type analog --channels 0 --threshold 500 --sample_rate 1 --log_file sound.log
"""

import argparse
import time
import threading
import queue
import logging
import signal
import sys

try:
    import spidev
    from gpiozero import DigitalInputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError as e:
    print(f"Missing required library: {e}", file=sys.stderr)
    sys.exit(1)


class SoundSensor:
    """Reads sound level from a digital or analog sound sensor."""

    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.logger = logging.getLogger(f"SoundSensor.{sensor_id}")
        self.logger.setLevel(logging.INFO)
        self._stop_event = threading.Event()
        self.spi = None
        self.digital_input = None

        if self.log_queue:
            handler = logging.StreamHandler()
            formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')
            handler.setFormatter(formatter)
            self.logger.addHandler(handler)

        if self.sensor_type == "digital":
            self._init_digital()
        elif self.sensor_type == "analog":
            self._init_analog()
        else:
            raise ValueError(f"Invalid sensor type: {self.sensor_type}. Must be 'digital' or 'analog'.")

    def _init_digital(self):
        """Initialize digital GPIO input using gpiozero."""
        try:
            self.digital_input = DigitalInputDevice(self.gpio_pins, pull_up=None, bounce_time=0.1)
            self.logger.info(f"Digital sensor initialized on GPIO {self.gpio_pins}.")
        except GPIOZeroError as e:
            self.logger.error(f"Failed to initialize digital GPIO {self.gpio_pins}: {e}")
            raise

    def _init_analog(self):
        """Initialize SPI interface for MCP3008 ADC."""
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
            self.spi.mode = 0
            self.logger.info(f"SPI initialized for MCP3008 on bus 0, device 0 at {self.spi_speed} Hz.")
        except Exception as e:
            self.logger.error(f"Failed to initialize SPI: {e}")
            raise

    def _read_digital(self):
        """Read digital value from gpiozero device."""
        if self.digital_input is None:
            return None
        try:
            return int(self.digital_input.value)
        except GPIOZeroError as e:
            self.logger.error(f"Error reading digital GPIO: {e}")
            return None

    def _read_analog(self):
        """Read analog value from MCP3008 via SPI."""
        if self.spi is None:
            return None
        try:
            # MCP3008 single-ended mode: start bit (1), single/diff (1), channel bits (3), then dummy byte
            adc = self.spi.xfer2([1, (8 + self.channels) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            self.logger.error(f"Error reading MCP3008 channel {self.channels}: {e}")
            return None

    def _detect_event(self, value):
        """Detect event based on sensor type and threshold."""
        if self.sensor_type == "digital":
            return value == 1
        elif self.sensor_type == "analog":
            return value is not None and value >= self.threshold
        return False

    def _log_event(self, value):
        """Log event to queue or console."""
        if self.log_queue:
            try:
                self.log_queue.put(f"Sensor {self.sensor_id}: Event detected, value={value}")
            except Exception as e:
                self.logger.error(f"Error putting log message in queue: {e}")
        else:
            self.logger.info(f"Event detected, value={value}")

    def run(self):
        """Main loop: sample sensor and detect events."""
        self.logger.info(f"Starting sensor {self.sensor_id}...")
        while not self._stop_event.is_set():
            try:
                if self.sensor_type == "digital":
                    value = self._read_digital()
                else:
                    value = self._read_analog()

                if self._detect_event(value):
                    self._log_event(value)

                self._stop_event.wait(1.0 / self.sample_rate)

            except Exception as e:
                self.logger.error(f"Error in sensor {self.sensor_id} loop: {e}")
                self._stop_event.wait(1.0 / self.sample_rate)

        self.logger.info(f"Sensor {self.sensor_id} stopped.")

    def stop(self):
        """Signal the sensor to stop."""
        self._stop_event.set()

    def cleanup(self):
        """Release resources."""
        if self.digital_input is not None:
            try:
                self.digital_input.close()
            except Exception as e:
                self.logger.error(f"Error closing digital GPIO: {e}")
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                self.logger.error(f"Error closing SPI: {e}")


def main():
    parser = argparse.ArgumentParser(description="Sound sensor monitoring system.")
    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"], help="Sensor type: digital or analog")
    parser.add_argument("--threshold", type=int, required=True, help="Threshold for analog sensor (0-1023)")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate in Hz")
    parser.add_argument("--log_file", help="Path to log file")
    parser.add_argument("--gpio_pins", type=int, help="GPIO pin number for digital sensor")
    parser.add_argument("--channels", type=int, help="MCP3008 channel number for analog sensor")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", nargs="+", required=True, help="Unique sensor IDs")

    args = parser.parse_args()

    log_queue = None
    if args.log_file:
        log_queue = queue.Queue()
        logging.basicConfig(filename=args.log_file, level=logging.INFO,
                            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')

    sensors = []
    try:
        for sensor_id in args.sensor_ids:
            try:
                sensor = SoundSensor(
                    sensor_id=sensor_id,
                    sensor_type=args.sensor_type,
                    threshold=args.threshold,
                    sample_rate=args.sample_rate,
                    gpio_pins=args.gpio_pins,
                    channels=args.channels,
                    spi_speed=args.spi_speed,
                    log_queue=log_queue
                )
                sensors.append(sensor)
            except Exception as e:
                logging.error(f"Failed to initialize sensor {sensor_id}: {e}")

        threads = []
        for sensor in sensors:
            t = threading.Thread(target=sensor.run, daemon=True)
            t.start()
            threads.append(t)

        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        for sensor in sensors:
            sensor.stop()
        for t in threads:
            t.join(timeout=2.0)
        for sensor in sensors:
            sensor.cleanup()
        logging.info("Program finished.")


if __name__ == "__main__":
    main()

