        """Signal the sensor to stop."""
        self._stop_event.set()

    def cleanup(self):
        """Release resources."""
        if self.digital_input is not None:
            try:
                self.digital_input.close()
            except Exception as e:
                self.logger.error(f"Error closing digital GPIO: {e}")
        if self.spi is not None:
            try:
                self.spi.close()
            except Exception as e:
                self.logger.error(f"Error closing SPI: {e}")


