    parser.add_argument("--sensor_type", required=True, choices=["digital", "analog"], help="Sensor type: digital or analog")
    parser.add_argument("--threshold", type=int, required=True, help="Threshold for analog sensor (0-1023)")
    parser.add_argument("--sample_rate", type=int, required=True, help="Sampling rate in Hz")
    parser.add_argument("--log_file", help="Path to log file")
    parser.add_argument("--gpio_pins", type=int, help="GPIO pin number for digital sensor")
    parser.add_argument("--channels", type=int, help="MCP3008 channel number for analog sensor")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz")
    parser.add_argument("--sensor_ids", nargs="+", required=True, help="Unique sensor IDs")

    args = parser.parse_args()

    log_queue = None
    if args.log_file:
        log_queue = queue.Queue()
        logging.basicConfig(filename=args.log_file, level=logging.INFO,
                            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')

    sensors = []
    try:
        for sensor_id in args.sensor_ids:
            try:
                sensor = SoundSensor(
                    sensor_id=sensor_id,
                    sensor_type=args.sensor_type,
                    threshold=args.threshold,
                    sample_rate=args.sample_rate,
                    gpio_pins=args.gpio_pins,
                    channels=args.channels,
                    spi_speed=args.spi_speed,
                    log_queue=log_queue
                )
                sensors.append(sensor)
            except Exception as e:
                logging.error(f"Failed to initialize sensor {sensor_id}: {e}")

        threads = []
        for sensor in sensors:
            t = threading.Thread(target=sensor.run, daemon=True)
            t.start()
            threads.append(t)

        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        for sensor in sensors:
            sensor.stop()
        for t in threads:
            t.join(timeout=2.0)
        for sensor in sensors:
            sensor.cleanup()
        logging.info("Program finished.")


