import time
import board
import busio
import adafruit_ads1x15.ads1115 as ADS
from adafruit_ads1x15.analog_in import AnalogIn

# Constants
I2C_BUS = 1
ADS1115_ADDRESS = 0x48
GAIN = 1
READ_DELAY = 0.5


def initialize_i2c():
    """Initialize the I2C bus on board.SCL / board.SDA."""
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        # Probe the bus to confirm the ADS1115 is present.
        while not i2c.try_lock():
            pass
        try:
            devices = i2c.scan()
        finally:
            i2c.unlock()
        if ADS1115_ADDRESS not in devices:
            print(f"Error: ADS1115 not found at I2C address 0x{ADS1115_ADDRESS:02X}.")
            print(f"Detected devices: {[hex(d) for d in devices]}")
            return None
        return i2c
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None


def initialize_adc(i2c_bus):
    """Initialize the ADS1115 ADC with gain=1 (±4.096 V)."""
    try:
        ads = ADS.ADS1115(i2c_bus, address=ADS1115_ADDRESS)
        ads.gain = GAIN
        return ads
    except Exception as e:
        print(f"Error initializing ADS1115: {e}")
        return None


def read_adc_channels(adc):
    """Read all four channels; return list of raw signed 16-bit values or None on error."""
    try:
        return [
            AnalogIn(adc, ADS.P0).value,
            AnalogIn(adc, ADS.P1).value,
            AnalogIn(adc, ADS.P2).value,
            AnalogIn(adc, ADS.P3).value,
        ]
    except Exception as e:
        print(f"Error reading ADC channels: {e}")
        return None


def print_adc_readings(adc_values):
    """Print the ADC readings in a formatted table."""
    print("-" * 37)
    print("|  Ch0   |  Ch1   |  Ch2   |  Ch3   |")
    print("-" * 37)
    print(f"| {adc_values[0]:6d} | {adc_values[1]:6d} | {adc_values[2]:6d} | {adc_values[3]:6d} |")
    print("-" * 37)


def main():
    """Main loop: initialize, read, and print ADC values every 0.5 s."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    adc = initialize_adc(i2c_bus)
    if adc is None:
        return

    try:
        while True:
            adc_values = read_adc_channels(adc)
            if adc_values is not None:
                print_adc_readings(adc_values)
            time.sleep(READ_DELAY)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # busio.I2C does not require explicit close, but we release the lock.
        try:
            while not i2c_bus.try_lock():
                pass
            i2c_bus.unlock()
        except Exception:
            pass


if __name__ == "__main__":
    main()

