import smbus2
from bmp280 import BMP280

I2C_BUS = 1
I2C_ADDR = 0x76
CSV_FILE = '/home/pi/weather_data/weather_data.csv'
ERROR_LOG = '/home/pi/weather_data/error_log.txt'
CALIBRATION_READINGS = 100
SAMPLE_COUNT = 5
SAMPLE_DELAY = 0.2
LOG_INTERVAL = 5

running = True
bus = None

def log_error(msg):
    ts = time.strftime('%Y-%m-%d %H:%M:%S')
    line = f'{ts} - {msg}\n'
    try:
        with open(ERROR_LOG, 'a') as f:
            f.write(line)
    except OSError as e:
        print(f'Failed to write error log: {e}', file=sys.stderr)

def signal_handler(signum, frame):
    global running
    running = False

def init_sensor():
    global bus
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        log_error(f'Failed to open I2C bus {I2C_BUS}: {e}')
        return False
    try:
        sensor = BMP280(i2c_dev=bus, i2c_addr=I2C_ADDR)
    except OSError as e:
        log_error(f'BMP280 not found at 0x{I2C_ADDR:02X} on bus {I2C_BUS}: {e}')
        try:
            bus.close()
        except Exception:
            pass
        bus = None
        return False
    except Exception as e:
        log_error(f'BMP280 init failed: {e}')
        try:
            bus.close()
        except Exception:
            pass
        bus = None
        return False
    return True

def calibrate_sensor(sensor):
    readings = []
    print(f'Calibrating with {CALIBRATION_READINGS} readings...')
    for i in range(CALIBRATION_READINGS):
        if not running:
            return False
        try:
            p, t = sensor.get_pressure(), sensor.get_temperature()
            readings.append((p, t))
            time.sleep(0.05)
        except OSError as e:
            log_error(f'Calibration read error: {e}')
            return False
        except Exception as e:
            log_error(f'Calibration unexpected error: {e}')
            return False
    if not readings:
        log_error('Calibration failed: no readings collected.')
        return False
    avg_p = sum(r[0] for r in readings) / len(readings)
    avg_t = sum(r[1] for r in readings) / len(readings)
    print(f'Calibration complete. Avg pressure: {avg_p:.2f} hPa, Avg temp: {avg_t:.2f} C')
    return True

def read_sensor(sensor):
    pressures = []
    for _ in range(SAMPLE_COUNT):
        if not running:
            return None, None
        try:
            p = sensor.get_pressure()
            pressures.append(p)
        except OSError as e:
            log_error(f'Sensor read error: {e}')
            return None, None
        except Exception as e:
            log_error(f'Sensor unexpected error: {e}')
            return None, None
        time.sleep(SAMPLE_DELAY)
    if not pressures:
        return None, None
    avg_p = sum(pressures) / len(pressures)
    avg_t = sensor.get_temperature()
    return avg_p, avg_t

def write_csv(pressure, temperature):
    try:
        os.makedirs(os.path.dirname(CSV_FILE), exist_ok=True)
        with open(CSV_FILE, 'a', newline='') as f:
            writer = csv.writer(f)
            writer.writerow([time.strftime('%Y-%m-%d %H:%M:%S'), f'{pressure:.2f}', f'{temperature:.2f}'])
    except OSError as e:
        log_error(f'Failed to write CSV: {e}')

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    if not init_sensor():
        print('Sensor initialization failed. Check error_log.txt.', file=sys.stderr)
        sys.exit(1)
    if not calibrate_sensor(bus):
        print('Calibration failed. Check error_log.txt.', file=sys.stderr)
        try:
            bus.close()
        except Exception:
            pass
        sys.exit(1)
    print('Starting logging every 5 seconds...')
    try:
        while running:
            pressure, temperature = read_sensor(bus)
            if pressure is not None and temperature is not None:
                write_csv(pressure, temperature)
            else:
                log_error('Sensor read failed; skipping cycle.')
            for _ in range(LOG_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    finally:
        if bus is not None:
            try:
                bus.close()
            except Exception:
                pass
        print('Program terminated.')

if __name__ == '__main__':
    main()

