import signal
import sys
import time
import logging
from datetime import datetime

import board
import busio
import adafruit_max30102

LOG_FILE = "heart_rate_log.txt"
WINDOW_SECONDS = 4.0
SAMPLE_INTERVAL = 1.0

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("max30102")

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _safe_format(value):
    """Defensive helper that returns a string representation of a value,
    casting to int where possible, to avoid _AdaValue formatting issues
    in emulated environments."""
    try:
        return str(int(value))
    except (TypeError, ValueError):
        return str(value)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_sigint)

    i2c = None
    sensor = None
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        sensor = adafruit_max30102.MAX30102(i2c)
        log.info("MAX30102 initialized on I2C bus.")
    except Exception as exc:
        log.error("Failed to initialize MAX30102: %s", exc)
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass
        sys.exit(1)

    window = []
    last_log = 0.0

    try:
        while _running:
            try:
                ir = sensor.ir
                red = sensor.red
            except Exception as exc:
                log.warning("Sensor read error: %s", exc)
                time.sleep(SAMPLE_INTERVAL)
                continue

            if ir is None or red is None:
                log.warning("Sensor returned None (ir=%s, red=%s)", ir, red)
                time.sleep(SAMPLE_INTERVAL)
                continue

            window.append(ir)
            if len(window) > WINDOW_SECONDS / SAMPLE_INTERVAL:
                window.pop(0)

            now = time.monotonic()
            if now - last_log >= 1.0:
                last_log = now
                try:
                    part_id = int(sensor.part_id)
                except (TypeError, ValueError):
                    part_id = str(sensor.part_id)

                avg = sum(window) / len(window) if window else 0.0
                ts = datetime.now().isoformat(timespec="seconds")
                line = f"{ts} | part_id={part_id} | ir={_safe_format(ir)} | red={_safe_format(red)} | avg={avg:.2f}"
                print(line)
                try:
                    with open(LOG_FILE, "a", encoding="utf-8") as fh:
                        fh.write(line + "\n")
                except OSError as exc:
                    log.warning("Failed to write log file: %s", exc)

            time.sleep(SAMPLE_INTERVAL)
    finally:
        log.info("Shutting down.")
        if sensor is not None:
            try:
                sensor.deinit()
            except Exception:
                pass
        if i2c is not None:
            try:
                i2c.deinit()
            except Exception:
                pass


if __name__ == "__main__":
    main()

