import io
import time
import json
import queue
import signal
import logging
import threading
import traceback
from picamera2 import Picamera2
from picamera2.encoders import MJPEGEncoder
from picamera2.outputs import FileOutput
import RPi.GPIO as GPIO

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class CameraHandler:
    def __init__(self, config):
        self.config = config
        self.camera = None
        self.frame_queue = queue.Queue(maxsize=config['max_queue_size'])
        self.running = True
        self.alert_timer = None
        self._lock = threading.Lock()

    def initialize(self):
        try:
            self.camera = Picamera2()
            resolution = self.config['resolution']
            framerate = self.config['framerate']
            config = self.camera.create_video_configuration(
                main={"size": resolution, "format": "RGB888"},
                controls={"FrameRate": framerate}
            )
            self.camera.configure(config)
            self.camera.start()
            time.sleep(2)
            logging.info("Camera initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing camera: {e}")
            self.camera = None
            raise

    def capture_frames(self):
        while self.running:
            try:
                frame = self.camera.capture_array()
                if frame is None:
                    logging.warning("Captured empty frame.")
                    continue
                if not self.frame_queue.full():
                    self.frame_queue.put(frame)
                else:
                    logging.warning("Frame queue is full. Dropping frame.")
                time.sleep(0.1)
            except Exception as e:
                logging.error(f"Error capturing frame: {e}")
                time.sleep(1)

    def detect_motion(self):
        while self.running:
            try:
                frame = self.frame_queue.get(timeout=1)
                if self.check_motion(frame):
                    with self._lock:
                        if self.alert_timer is None:
                            logging.info("Motion detected!")
                            self.trigger_alert()
            except queue.Empty:
                pass
            except Exception as e:
                logging.error(f"Error detecting motion: {e}")

    def check_motion(self, frame):
        try:
            gray = self.rgb_to_gray(frame)
            avg = sum(gray) / (len(gray) * len(gray[0]))
            return abs(avg - self.config['motion_threshold']) > 10
        except Exception as e:
            logging.error(f"Error checking motion: {e}")
            return False

    def rgb_to_gray(self, frame):
        return frame[:, :, 0] * 0.299 + frame[:, :, 1] * 0.587 + frame[:, :, 2] * 0.114

    def trigger_alert(self):
        try:
            led_pin = self.config.get('gpio_pin')
            if led_pin is not None:
                GPIO.output(led_pin, GPIO.HIGH)
                self.alert_timer = threading.Timer(self.config['alert_duration'], self.deactivate_led, [led_pin])
                self.alert_timer.start()
            else:
                logging.warning("GPIO pin not configured. Alert triggered without LED.")
        except Exception as e:
            logging.error(f"Error triggering alert: {e}")

    def deactivate_led(self, led_pin):
        try:
            GPIO.output(led_pin, GPIO.LOW)
            self.alert_timer = None
            logging.info("LED deactivated.")
        except Exception as e:
            logging.error(f"Error deactivating LED: {e}")

    def cleanup(self):
        logging.info("Cleaning up resources...")
        self.running = False
        if self.alert_timer:
            self.alert_timer.cancel()
        if self.camera:
            try:
                self.camera.stop()
                self.camera.close()
            except Exception as e:
                logging.error(f"Error closing camera: {e}")
        try:
            GPIO.cleanup()
            logging.info("GPIO cleaned up.")
        except Exception as e:
            logging.error(f"Error cleaning up GPIO: {e}")

def load_config(config_file):
    try:
        with open(config_file, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        logging.error(f"Config file not found: {config_file}")
        return None
    except json.JSONDecodeError:
        logging.error(f"Invalid JSON format in config file: {config_file}")
        return None

def main():
    config = load_config('config.json')
    if not config:
        return

    led_pin = config.get('gpio_pin')
    if led_pin is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(led_pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            logging.error(f"Error setting up GPIO pin {led_pin}: {e}")
            return

    camera_handler = CameraHandler(config)
    signal.signal(signal.SIGINT, lambda s, f: setattr(camera_handler, 'running', False))

    try:
        camera_handler.initialize()
        capture_thread = threading.Thread(target=camera_handler.capture_frames)
        motion_thread = threading.Thread(target=camera_handler.detect_motion)
        capture_thread.start()
        motion_thread.start()
        while camera_handler.running:
            time.sleep(1)
    except Exception as e:
        logging.error(f"An error occurred: {e}")
        traceback.print_exc()
    finally:
        camera_handler.cleanup()

if __name__ == "__main__":
    main()

