import cv2
import time
import signal
import sys
import os
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

LED_PIN = 14
BUTTON_PIN = 15
SERVO_PIN = 18
CASCADE_PATH = '/home/raspberry/RaspPi_CV/haarcascade_frontalface_default.xml'
RESIZE_DIM = 32
SERVO_INCREMENT = 20
SERVO_DELAY = 0.02
WINDOW_TITLE = 'Human Detection'

running = True

def signal_handler(signum, frame):
    global running
    logging.info(f'Received signal {signum}, shutting down...')
    running = False

def cleanup(cap, window_created, pwm_servo):
    logging.info('Cleaning up resources...')
    if cap is not None:
        cap.release()
    if window_created:
        cv2.destroyAllWindows()
    if pwm_servo is not None:
        try:
            pwm_servo.stop()
        except Exception:
            pass
    try:
        cv2.led_off(LED_PIN)
    except Exception:
        pass
    try:
        cv2.led_on(LED_PIN)
    except Exception:
        pass
    try:
        cv2.cleanup()
    except Exception:
        pass
    logging.info('Cleanup complete.')

def detect_human(frame, face_cascade):
    gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
    return len(faces) > 0

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cap = None
    window_created = False
    pwm_servo = None
    led_available = False
    button_available = False
    servo_available = False

    try:
        if not os.path.isfile(CASCADE_PATH):
            raise FileNotFoundError(f'Cascade file not found: {CASCADE_PATH}')
        face_cascade = cv2.CascadeClassifier(CASCADE_PATH)
        if face_cascade.empty():
            raise IOError(f'Failed to load cascade classifier from {CASCADE_PATH}')
        logging.info('Cascade classifier loaded successfully.')
    except Exception as e:
        logging.error(f'Error loading cascade classifier: {e}')
        sys.exit(0)

    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise IOError('Cannot open camera /dev/video0')
        logging.info('Camera opened successfully.')
    except Exception as e:
        logging.error(f'Error opening camera: {e}')
        sys.exit(0)

    try:
        led_available = True
        cv2.led_on(LED_PIN)
        cv2.led_off(LED_PIN)
        logging.info('LED control initialized.')
    except Exception as e:
        logging.warning(f'LED control unavailable: {e}')
        led_available = False

    try:
        button_available = True
        btn = cv2.gpio_input(BUTTON_PIN, pull_up=True)
        logging.info('Button control initialized.')
    except Exception as e:
        logging.warning(f'Button control unavailable: {e}')
        button_available = False

    try:
        pwm_servo = cv2.PWM(SERVO_PIN, 50)
        pwm_servo.start(7.5)
        logging.info('Servo control initialized.')
    except Exception as e:
        logging.warning(f'Servo control unavailable: {e}')
        pwm_servo = None

    servo_angle = 90.0

    try:
        while running:
            ret, frame = cap.read()
            if not ret:
                logging.error('Cannot receive frame. Exiting...')
                break

            try:
                resized_frame = cv2.resize(frame, (RESIZE_DIM, RESIZE_DIM))
            except Exception as e:
                logging.error(f'Error resizing frame: {e}')
                continue

            try:
                if detect_human(resized_frame, face_cascade):
                    cv2.led_on(LED_PIN)
                    if servo_available:
                        servo_angle += SERVO_INCREMENT if resized_frame.shape[1] // 2 < 16 else -SERVO_INCREMENT
                        servo_angle = max(0.0, min(180.0, servo_angle))
                        pwm_servo.set_duty_cycle(servo_angle / 18.0 + 2.5)
                        time.sleep(SERVO_DELAY)
                else:
                    cv2.led_off(LED_PIN)
            except Exception as e:
                logging.error(f'Error during detection processing: {e}')

            try:
                if button_available:
                    btn_state = cv2.gpio_input(BUTTON_PIN, pull_up=True)
                    if btn_state == 0:
                        logging.info('Button pressed!')
            except Exception as e:
                logging.error(f'Error reading button: {e}')

            try:
                if not window_created:
                    cv2.namedWindow(WINDOW_TITLE, cv2.WINDOW_AUTOSIZE)
                    window_created = True
                cv2.imshow(WINDOW_TITLE, frame)
                if cv2.waitKey(1) & 0xFF == ord('q'):
                    break
            except Exception as e:
                logging.error(f'Error displaying frame: {e}')
                window_created = False
    except KeyboardInterrupt:
        logging.info('Program interrupted by user.')
    except Exception as e:
        logging.error(f'An unexpected error occurred: {e}')
    finally:
        cleanup(cap, window_created, pwm_servo)

if __name__ == '__main__':
    main()

