import time
import datetime
import sqlite3
import signal
import sys
import os
import traceback

try:
    import smbus2
except ImportError:
    smbus2 = None

try:
    import bme280
except ImportError:
    bme280 = None

try:
    import ms8607
except ImportError:
    ms8607 = None

try:
    import bmp280
except ImportError:
    bmp280 = None

# Constants
DATABASE_NAME = 'wildlife_data.db'
ERROR_LOG_FILE = 'error.log'
I2C_BUS = 1
MIN_PRESSURE = 70000
MAX_PRESSURE = 110000
MIN_TEMP = -20
MAX_TEMP = 50
MIN_HUMIDITY = 0
MAX_HUMIDITY = 100

# Global state
running = True
db_conn = None


def log_error(message):
    """Logs an error message to the error log file with a timestamp."""
    timestamp = datetime.datetime.now().isoformat()
    try:
        with open(ERROR_LOG_FILE, 'a') as f:
            f.write(f"{timestamp} - ERROR: {message}\n")
    except Exception as e:
        print(f"Failed to write to error log: {e}", file=sys.stderr)


def load_config(config_file="config.txt"):
    """Loads configuration from a file. Returns dict with defaults for missing keys."""
    config = {
        'Sensor1_Type': 'BME280',
        'Sensor1_Address': '0x77',
        'Sensor1_ID': 'Sensor1',
        'Sensor2_Type': 'BMP280',
        'Sensor2_Address': '0x76',
        'Sensor2_ID': 'Sensor2',
        'Sensor3_Type': 'MS8607',
        'Sensor3_Address': '0x76',
        'Sensor3_ID': 'Sensor3',
        'Sampling_Interval_Seconds': '60',
    }
    try:
        with open(config_file, 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' not in line:
                    log_error(f"Invalid config line (no '='): {line}")
                    continue
                key, value = line.split('=', 1)
                key = key.strip()
                value = value.strip()
                if key in config:
                    config[key] = value
                else:
                    log_error(f"Unknown config key: {key}")
    except FileNotFoundError:
        log_error(f"Configuration file not found: {config_file}")
    except Exception as e:
        log_error(f"Error reading configuration file: {e}")
    return config


def init_sensor(sensor_type, sensor_address, sensor_id):
    """Initializes a sensor based on type. Returns sensor object or None on failure."""
    try:
        if sensor_type == 'BME280':
            if bme280 is None:
                log_error("bme280 library not installed")
                return None
            if smbus2 is None:
                log_error("smbus2 library not installed")
                return None
            address = int(sensor_address, 16)
            bus = smbus2.SMBus(I2C_BUS)
            calibration_params = bme280.load_calibration_params(bus, address)
            return {'type': 'BME280', 'bus': bus, 'params': calibration_params, 'id': sensor_id}
        elif sensor_type == 'BMP280':
            if bmp280 is None:
                log_error("bmp280 library not installed")
                return None
            if smbus2 is None:
                log_error("smbus2 library not installed")
                return None
            address = int(sensor_address, 16)
            bus = smbus2.SMBus(I2C_BUS)
            calibration_params = bmp280.load_calibration_params(bus, address)
            return {'type': 'BMP280', 'bus': bus, 'params': calibration_params, 'id': sensor_id}
        elif sensor_type == 'MS8607':
            if ms8607 is None:
                log_error("ms8607 library not installed")
                return None
            if smbus2 is None:
                log_error("smbus2 library not installed")
                return None
            address = int(sensor_address, 16)
            bus = smbus2.SMBus(I2C_BUS)
            sensor = ms8607.MS8607(bus, address)
            return {'type': 'MS8607', 'bus': bus, 'sensor': sensor, 'id': sensor_id}
        else:
            log_error(f"Unknown sensor type: {sensor_type}")
            return None
    except Exception as e:
        log_error(f"Failed to initialize {sensor_type} at {sensor_address}: {e}")
        return None


def read_sensor(sensor):
    """Reads data from a sensor. Returns dict with pressure, temperature, humidity or None on failure."""
    try:
        if sensor['type'] == 'BME280':
            data = bme280.sample(sensor['bus'], sensor['params'])
            return {
                'pressure': data.pressure,
                'temperature': data.temperature,
                'humidity': data.humidity,
            }
        elif sensor['type'] == 'BMP280':
            data = bmp280.sample(sensor['bus'], sensor['params'])
            return {
                'pressure': data.pressure,
                'temperature': data.temperature,
            }
        elif sensor['type'] == 'MS8607':
            data = sensor['sensor'].read()
            return {
                'pressure': data.pressure,
                'temperature': data.temperature,
                'humidity': data.humidity,
            }
        else:
            log_error(f"Unknown sensor type: {sensor['type']}")
            return None
    except Exception as e:
        log_error(f"Failed to read {sensor['type']} {sensor['id']}: {e}")
        return None


def validate_data(pressure, temperature, humidity):
    """Validates sensor readings against physical limits."""
    if not (MIN_PRESSURE <= pressure <= MAX_PRESSURE):
        log_error(f"Pressure out of range: {pressure} Pa")
        return False
    if not (MIN_TEMP <= temperature <= MAX_TEMP):
        log_error(f"Temperature out of range: {temperature} °C")
        return False
    if humidity is not None and not (MIN_HUMIDITY <= humidity <= MAX_HUMIDITY):
        log_error(f"Humidity out of range: {humidity} %")
        return False
    return True


def store_data(timestamp, sensor_type, sensor_id, pressure, temperature, humidity):
    """Stores sensor data in the SQLite database."""
    global db_conn
    try:
        cursor = db_conn.cursor()
        cursor.execute('''
            INSERT INTO sensor_data (timestamp, sensor_type, sensor_id, pressure_pa, temperature_c, humidity_percent)
            VALUES (?, ?, ?, ?, ?, ?)
        ''', (timestamp, sensor_type, sensor_id, pressure, temperature, humidity))
        db_conn.commit()
    except sqlite3.Error as e:
        log_error(f"Database error: {e}")


def create_database():
    """Creates the SQLite database and table if they don't exist."""
    global db_conn
    try:
        db_conn = sqlite3.connect(DATABASE_NAME)
        cursor = db_conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS sensor_data (
                timestamp TEXT,
                sensor_type TEXT,
                sensor_id TEXT,
                pressure_pa REAL,
                temperature_c REAL,
                humidity_percent REAL
            )
        ''')
        db_conn.commit()
    except sqlite3.Error as e:
        log_error(f"Database creation error: {e}")
        db_conn = None


def cleanup(signum=None, frame=None):
    """Clean up resources on exit."""
    global running, db_conn
    running = False
    if db_conn:
        try:
            db_conn.close()
        except Exception:
            pass
        db_conn = None
    if signum is not None:
        print(f"\nReceived signal {signum}, exiting.")
        sys.exit(0)


def main():
    """Main function to read sensor data and store it in the database."""
    global running

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    create_database()
    if db_conn is None:
        print("Failed to initialize database. Exiting.", file=sys.stderr)
        sys.exit(1)

    config = load_config()
    sensors = []
    for i in range(1, 4):
        sensor_type = config[f'Sensor{i}_Type']
        sensor_address = config[f'Sensor{i}_Address']
        sensor_id = config[f'Sensor{i}_ID']
        sensor = init_sensor(sensor_type, sensor_address, sensor_id)
        if sensor:
            sensors.append(sensor)

    if not sensors:
        print("No sensors initialized. Exiting.", file=sys.stderr)
        cleanup()
        sys.exit(0)

    sampling_interval = int(config['Sampling_Interval_Seconds'])

    try:
        while running:
            timestamp = datetime.datetime.now().isoformat()
            for sensor in sensors:
                data = read_sensor(sensor)
                if data:
                    if validate_data(data['pressure'], data['temperature'], data.get('humidity')):
                        store_data(timestamp, sensor['type'], sensor['id'],
                                   data['pressure'], data['temperature'], data.get('humidity'))
                    else:
                        log_error(f"Invalid data from {sensor['type']} {sensor['id']}: "
                                  f"P={data['pressure']} T={data['temperature']} H={data.get('humidity')}")
            time.sleep(sampling_interval)
    except Exception as e:
        log_error(f"Unexpected error in main loop: {e}\n{traceback.format_exc()}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

