import time
import signal
import sys
import random
import smbus2
from gpiozero import Buzzer

# Constants
I2C_BUS = 1
AMG8833_ADDR = 0x69
THRESHOLD_TEMP = 30.0
BUZZER_PIN = 17
POLL_INTERVAL = 0.1
BUZZER_DURATION = 1.0

# Global resources for cleanup
buzzer = None
bus = None
running = True


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global running
    running = False


def init_buzzer():
    """Initialize the buzzer on GPIO17."""
    return Buzzer(BUZZER_PIN)


def init_i2c_bus():
    """Initialize the I2C bus."""
    return smbus2.SMBus(I2C_BUS)


def read_thermal_data(bus):
    """Read 8x8 temperature data from the AMG8833 sensor.

    Returns a list of 64 floats, or None on error.
    """
    data = []
    for i in range(64):
        try:
            row = bus.read_i2c_block_data(AMG8833_ADDR, 0x80 | (i << 3), 2)
            raw = (row[0] << 8) | row[1]
            if raw & 0x8000:
                raw -= 0x10000
            temp = raw * 0.25
            data.append(temp)
        except OSError as e:
            print(f"I2C read error at pixel {i}: {e}")
            return None
    return data


def detect_human(thermal_data):
    """Detect human presence based on thermal data."""
    return any(temp > THRESHOLD_TEMP for temp in thermal_data)


def trigger_alert(buzzer):
    """Trigger the buzzer for a specified duration."""
    try:
        buzzer.on()
        time.sleep(BUZZER_DURATION)
        buzzer.off()
    except Exception as e:
        print(f"Error triggering buzzer: {e}")


def simulate_thermal_data():
    """Simulate thermal data if sensor is unavailable."""
    return [random.uniform(20, 45) for _ in range(64)]


def cleanup():
    """Release resources cleanly."""
    global buzzer, bus
    if buzzer is not None:
        try:
            buzzer.close()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def main():
    global buzzer, bus

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        buzzer = init_buzzer()
    except Exception as e:
        print(f"Failed to initialize buzzer: {e}")
        sys.exit(1)

    try:
        bus = init_i2c_bus()
    except Exception as e:
        print(f"Failed to initialize I2C bus: {e}")
        cleanup()
        sys.exit(1)

    print("Thermal monitoring started. Press Ctrl+C to exit.")

    while running:
        try:
            thermal_data = read_thermal_data(bus)
            if thermal_data is None:
                print("Sensor error detected. Simulating thermal data...")
                thermal_data = simulate_thermal_data()
            else:
                print("Thermal data read successfully.")

            if detect_human(thermal_data):
                print("Human detected! Triggering alert.")
                trigger_alert(buzzer)
            else:
                print("No human detected.")

        except Exception as e:
            print(f"An unexpected error occurred: {e}")

        time.sleep(POLL_INTERVAL)

    print("Exiting program.")
    cleanup()


if __name__ == "__main__":
    main()

