#!/usr/bin/env python3
"""
QR Code Scanner for Raspberry Pi

Captures a single frame from the Raspberry Pi Camera Module via the CSI bus,
converts it to grayscale, and attempts to decode any QR code present.
Prints 'Hello, World!' when a QR code is detected, otherwise prints
'No QR code detected.' All camera resources are released on every exit path.
"""

import sys
import signal
from typing import Optional

try:
    from picamera2 import Picamera2
except ImportError:
    print("Error: picamera2 library is not installed. Install with: pip install picamera2", file=sys.stderr)
    sys.exit(1)

try:
    from pyzbar.pyzbar import decode as zbar_decode
    from PIL import Image
except ImportError:
    print("Error: pyzbar or Pillow is not installed. Install with: pip install pyzbar Pillow", file=sys.stderr)
    sys.exit(1)


class QRCodeScanner:
    """Encapsulates camera capture and QR code decoding."""

    def __init__(self) -> None:
        self.camera: Optional[Picamera2] = None

    def __enter__(self) -> "QRCodeScanner":
        try:
            self.camera = Picamera2()
            # Configure for a single capture at the default 640x480.
            config = self.camera.create_still_configuration(
                main={"size": (640, 480), "format": "RGB888"}
            )
            self.camera.configure(config)
            self.camera.start()
        except Exception as exc:
            print(f"Error initializing camera: {exc}", file=sys.stderr)
            self._cleanup()
            raise
        return self

    def __exit__(self, exc_type, exc_val, exc_tb) -> None:
        self._cleanup()

    def _cleanup(self) -> None:
        """Release camera resources."""
        if self.camera is not None:
            try:
                self.camera.stop()
            except Exception:
                pass
            try:
                self.camera.close()
            except Exception:
                pass
            self.camera = None

    def capture_and_decode(self) -> None:
        """Capture a frame, convert to grayscale, and decode any QR codes."""
        if self.camera is None:
            raise RuntimeError("Camera not initialized")

        try:
            # Capture a numpy array (RGB888).
            frame = self.camera.capture_array()
        except Exception as exc:
            print(f"Error capturing frame: {exc}", file=sys.stderr)
            return

        if frame is None:
            print("No frame captured.")
            return

        try:
            # Convert RGB to grayscale for pyzbar.
            gray = Image.fromarray(frame).convert("L")
        except Exception as exc:
            print(f"Error converting image to grayscale: {exc}", file=sys.stderr)
            return

        try:
            decoded_objects = zbar_decode(gray)
        except Exception as exc:
            print(f"Error decoding QR code: {exc}", file=sys.stderr)
            return

        if decoded_objects:
            print("Hello, World!")
        else:
            print("No QR code detected.")


def main() -> None:
    scanner = QRCodeScanner()
    # Ensure cleanup on SIGINT/SIGTERM.
    signal.signal(signal.SIGINT, lambda *_: sys.exit(0))
    signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))

    try:
        with scanner:
            scanner.capture_and_decode()
    except Exception as exc:
        print(f"An unexpected error occurred: {exc}", file=sys.stderr)
        sys.exit(1)


if __name__ == "__main__":
    main()

