        picam2 = Picamera2()
        config = picam2.create_preview_configuration(main={"format": 'RGB888', "size": (64, 1)})
        picam2.configure(config)
        picam2.start()
        time.sleep(CAMERA_WARMUP_TIME)
        return picam2
    except Exception as e:
        raise CameraInitializationError(f"Error initializing camera: {e}")

def capture_frame(camera):
    try:
        frame = camera.capture_array()
        return frame
    except Exception as e:
        raise GestureRecognitionError(f"Error capturing frame: {e}")

def preprocess_frame(frame):
    try:
        resized_frame = np.resize(frame, (224, 224, 3))
        return resized_frame.astype(np.float32)
    except Exception as e:
        raise GestureRecognitionError(f"Error preprocessing frame: {e}")

# Gesture Recognition and Smart Home Control Functions
def recognize_gesture(interpreter, frame, confidence_threshold):
    try:
        input_details = interpreter.get_input_details()
        output_details = interpreter.get_output_details()
        input_data = np.expand_dims(frame, axis=0)
        interpreter.set_tensor(input_details[0]['index'], input_data)
        interpreter.invoke()
        output_data = interpreter.get_tensor(output_details[0]['index'])
        results = np.squeeze(output_data)
        predicted_label = GESTURE_LABELS[np.argmax(results)]
        confidence = float(results[GESTURE_INDICES[predicted_label]])
        if confidence >= confidence_threshold:
            return predicted_label, confidence
        return None, None
    except Exception as e:
        raise GestureRecognitionError(f"Error recognizing gesture: {e}")

def control_smart_home(gesture, confidence):
    global light_state, thermostat_temperature, tv_state, last_gesture_time
    current_time = time.time()
    if current_time - last_gesture_time >= DEFAULT_COOLDOWN_PERIOD:
        if gesture == 'Open Hand':
            light_state = not light_state
        elif gesture == 'Closed Fist':
            light_state = False
        elif gesture == 'Pointing Up':
            thermostat_temperature = min(30, thermostat_temperature + 1)
        elif gesture == 'Pointing Down':
            thermostat_temperature = max(15, thermostat_temperature - 1)
        elif gesture == 'Peace Sign':
            tv_state = not tv_state
        last_gesture_time = current_time
        log_event(f"Gesture: {gesture}, Confidence: {confidence:.2f}, Light: {light_state}, Thermostat: {thermostat_temperature}, TV: {tv_state}")
        log_to_cloud(gesture, confidence, light_state, thermostat_temperature, tv_state)
    else:
        log_event(f"Gesture ignored (cooldown active): {gesture}, Confidence: {confidence:.2f}")

# Cloud Logging and Error Handling Functions
def log_to_cloud(gesture, confidence, light_state, thermostat_temperature, tv_state):
    try:
        data = {
            "timestamp": time.time(),
            "user_id": "unique_user_id",
            "gesture": gesture,
            "confidence": confidence,
            "light_state": light_state,
            "thermostat_temperature": thermostat_temperature,
            "tv_state": tv_state
        }
        with open("cloud_data.json", "a") as f:
            f.write(json.dumps(data) + "\n")
    except Exception as e:
        raise CloudLoggingError(f"Error logging to cloud: {e}")

def log_event(message):
    logging.info(message)

# Resource Management Functions
def cleanup(camera):
    if camera:
        try:
            camera.stop()
        except Exception:
            pass

# Signal Handling
def signal_handler(sig, frame):
    global running
    running = False

# Main Program
def main():
    global running
    args = parse_arguments()
    log_level = getattr(logging, args.log_level.upper(), None)
    if not isinstance(log_level, int):
        raise ValueError('Invalid log level: %s' % args.log_level)
    logging.basicConfig(filename='smart_home.log', level=log_level,
                        format='%(asctime)s - %(levelname)s - %(message)s')
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    camera = None
    try:
        camera = initialize_camera(args.camera_resolution, args.camera_framerate)
        interpreter = load_model(args.model_path)
        frame_queue = queue.Queue(maxsize=FRAME_QUEUE_MAXSIZE)
        stop_event = threading.Event()
        camera_thread = threading.Thread(target=capture_frames, args=(camera, frame_queue, stop_event))
        inference_thread = threading.Thread(target=process_frames, args=(interpreter, frame_queue, stop_event, args.confidence_threshold))
        camera_thread.start()
        inference_thread.start()
        while running:
            time.sleep(1)
        stop_event.set()
        camera_thread.join()
        inference_thread.join()
    except (CameraInitializationError, ModelLoadingError, GestureRecognitionError, CloudLoggingError) as e:
        logging.error(f"Error: {e}")
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        if camera:
            cleanup(camera)
        logging.info("Program finished.")

def capture_frames(camera, frame_queue, stop_event):
    while not stop_event.is_set():
        try:
            frame = capture_frame(camera)
            if not frame_queue.full():
                frame_queue.put(frame)
            else:
                logging.warning("Frame queue is full. Dropping frame.")
        except GestureRecognitionError as e:
            logging.error(f"Error capturing frame: {e}")
        except Exception as e:
            logging.error(f"Unexpected error in capture_frames: {e}")
        stop_event.wait(0.1)

def process_frames(interpreter, frame_queue, stop_event, confidence_threshold):
    while not stop_event.is_set():
        try:
            frame = frame_queue.get(timeout=1)
            gesture, confidence = recognize_gesture(interpreter, frame, confidence_threshold)
            if gesture:
                control_smart_home(gesture, confidence)
        except queue.Empty:
            continue
        except GestureRecognitionError as e:
            logging.error(f"Error processing frame: {e}")
        except Exception as e:
            logging.error(f"Unexpected error in process_frames: {e}")

if __name__ == "__main__":
    main()

