                log_dir = './'
    logger = logging.getLogger()
    logger.setLevel(logging.INFO)
    fmt = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    try:
        handler = logging.handlers.RotatingFileHandler(
            log_file, maxBytes=1024 * 1024, backupCount=5)
        handler.setFormatter(fmt)
        logger.addHandler(handler)
    except OSError as e:
        print(f"Warning: could not open log file {log_file}: {e}")
        try:
            handler = logging.handlers.RotatingFileHandler(
                os.path.join(log_dir, 'security_camera.log'),
                maxBytes=1024 * 1024, backupCount=5)
            handler.setFormatter(fmt)
            logger.addHandler(handler)
        except OSError:
            handler = logging.StreamHandler()
            handler.setFormatter(fmt)
            logger.addHandler(handler)
    return logger


def get_disk_space(path):
    try:
        statvfs = os.statvfs(path)
        return statvfs.f_frsize * statvfs.f_bavail / (1024 * 1024)
    except OSError:
        return 0


def manage_disk_space(storage_dir, threshold_mb):
    if get_disk_space(storage_dir) > threshold_mb:
        print("Disk space low. Deleting old files...")
        try:
            files = []
            for root, dirs, fnames in os.walk(storage_dir):
                for f in fnames:
                    files.append(os.path.join(root, f))
            files.sort(key=lambda x: os.stat(x).st_mtime)
            for f in files:
                try:
                    if os.path.isfile(f):
                        os.remove(f)
                        print(f"Deleted: {f}")
                except OSError as e:
                    print(f"Error deleting {f}: {e}")
                if get_disk_space(storage_dir) <= threshold_mb:
                    break
        except OSError as e:
            print(f"Error managing disk space: {e}")


