import json
import logging
import signal
import statistics
import sys
import time

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

DEFAULT_CONFIG = {
    "sensor1": {"offset": 0.0, "max_distance": 200.0},
    "sensor2": {"offset": 0.0, "max_distance": 200.0},
    "sensor3": {"offset": 0.0, "max_distance": 200.0},
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

TRIG_PINS = [17, 22, 24]
ECHO_PINS = [18, 23, 25]
POLL_INTERVAL = 5
TIMEOUT = 0.05
TRIGGER_PULSE = 10e-6
SENSOR_ERROR_LIMIT = 5

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(cfg)
        for s in ["sensor1", "sensor2", "sensor3"]:
            merged[s] = merged.get(s, {})
            merged[s].update(DEFAULT_CONFIG.get(s, {}))
        return merged
    except (FileNotFoundError, json.JSONDecodeError):
        logging.warning("config.json not found or invalid; using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_gpio():
    if GPIO is None:
        logging.error("RPi.GPIO not available; running in mock mode.")
        return True
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for trig in TRIG_PINS:
            GPIO.setup(trig, GPIO.OUT)
            GPIO.output(trig, False)
        for echo in ECHO_PINS:
            GPIO.setup(echo, GPIO.IN)
        logging.info("GPIO initialized successfully.")
        return True
    except Exception as e:
        logging.error(f"GPIO initialization failed: {e}")
        return False


def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    if GPIO is None:
        return 2.0
    try:
        GPIO.output(trigger_pin, True)
        time.sleep(TRIGGER_PULSE)
        GPIO.output(trigger_pin, False)

        deadline = time.time() + TIMEOUT
        while GPIO.input(echo_pin) == 0:
            if time.time() > deadline:
                return None
        pulse_start = time.time()

        deadline = time.time() + TIMEOUT
        while GPIO.input(echo_pin) == 1:
            if time.time() > deadline:
                return None
        pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        distance = pulse_duration * 17150 + offset
        if distance < 0 or distance > max_distance:
            return None
        return distance
    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        return None


def get_water_level(config):
    distances = []
    for i, (trig, echo) in enumerate(zip(TRIG_PINS, ECHO_PINS)):
        s = f"sensor{i + 1}"
        d = measure_distance(trig, echo, config[s]["offset"], config[s]["max_distance"])
        if d is not None:
            distances.append(d)
        else:
            logging.warning(f"Sensor {i + 1} reading failed.")
    if not distances:
        return None
    return statistics.median(distances)


def check_alerts(water_level, config, last_alerts):
    low = config["alert_threshold_low"]
    high = config["alert_threshold_high"]
    delay = config["alert_repeat_delay"]
