    "sensor1": {"offset": 0.0, "max_distance": 200.0},
    "sensor2": {"offset": 0.0, "max_distance": 200.0},
    "sensor3": {"offset": 0.0, "max_distance": 200.0},
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log",
}

TRIG_PINS = [17, 22, 24]
ECHO_PINS = [18, 23, 25]
POLL_INTERVAL = 5
TIMEOUT = 0.05
TRIGGER_PULSE = 10e-6
SENSOR_ERROR_LIMIT = 5

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def load_config(config_file="config.json"):
    try:
        with open(config_file, "r") as f:
            cfg = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(cfg)
        for s in ["sensor1", "sensor2", "sensor3"]:
            merged[s] = merged.get(s, {})
            merged[s].update(DEFAULT_CONFIG.get(s, {}))
        return merged
    except (FileNotFoundError, json.JSONDecodeError):
        logging.warning("config.json not found or invalid; using defaults.")
        return DEFAULT_CONFIG.copy()


def setup_gpio():
    if GPIO is None:
        logging.error("RPi.GPIO not available; running in mock mode.")
        return True
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        for trig in TRIG_PINS:
            GPIO.setup(trig, GPIO.OUT)
            GPIO.output(trig, False)
        for echo in ECHO_PINS:
