import signal
import sys
import time
import random
import threading
import wave
import contextlib
import io
import os
from typing import Optional, Tuple

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    GPIO = None

try:
    import board
    import adafruit_dht
except (ImportError, NotImplementedError, RuntimeError):
    board = None
    adafruit_dht = None

try:
    from picamera2 import Picamera2
except (ImportError, RuntimeError):
    Picamera2 = None

try:
    import speech_recognition as sr
except ImportError:
    sr = None

try:
    import pyaudio
except ImportError:
    pyaudio = None

# Configuration
DHT_PIN = 4
LIGHT_PIN = 17
WAKE_WORD = "Greenhouse"
TEMPERATURE_THRESHOLD = 25.0
LIGHT_THRESHOLD = 500
CAMERA_RESOLUTION = (640, 480)
CAMERA_QUALITY = 64
LISTENING_DURATION = 5

# Global state
running = True
last_temperature = 20.0
last_light_level = 500
dht_device = None
picam2 = None
gpio_simulated = False


def simulate_gpio():
    """Simulates GPIO functionality if real GPIO is unavailable."""
    global gpio_simulated
    print("Warning: GPIO library not available. Simulating GPIO.")
    gpio_simulated = True


def cleanup_gpio():
    """Cleans up GPIO resources if they were used."""
    if not gpio_simulated and GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def cleanup_camera():
    """Releases camera resources."""
    global picam2
    if picam2 is not None:
        try:
            picam2.close()
        except Exception:
            pass
        picam2 = None


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM for graceful shutdown."""
    global running
    print("\nShutting down gracefully...")
    running = False
    cleanup_gpio()
    cleanup_camera()
    sys.exit(0)


def init_gpio():
    """Initializes GPIO pins for controlling the lights."""
    global gpio_simulated
    if GPIO is None:
        simulate_gpio()
        return
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        simulate_gpio()


def init_camera() -> bool:
    """Initializes the Raspberry Pi camera."""
    global picam2
    if Picamera2 is None:
        print("Warning: picamera2 library not available. Camera disabled.")
        return False
    try:
        picam2 = Picamera2()
        config = picam2.create_still_configuration(main={"size": CAMERA_RESOLUTION})
        picam2.configure(config)
        picam2.start()
        return True
    except Exception as e:
        print(f"Error initializing camera: {e}")
        picam2 = None
        return False


def init_dht11() -> bool:
    """Initializes the DHT11 sensor."""
    global dht_device
    if adafruit_dht is None or board is None:
        print("Warning: adafruit_dht or board library not available. DHT11 disabled.")
        return False
    try:
        dht_device = adafruit_dht.DHT11(board.D4)
        return True
    except Exception as e:
        print(f"Error initializing DHT11: {e}")
        dht_device = None
        return False


def read_temperature() -> float:
    """Reads temperature from DHT11 sensor, simulating if unavailable."""
    global dht_device, last_temperature
    if dht_device is not None:
        try:
            temperature = dht_device.temperature
            if temperature is not None:
                last_temperature = temperature
                return temperature
        except RuntimeError as e:
            print(f"DHT11 read error (likely checksum): {e}")
        except Exception as e:
            print(f"Unexpected DHT11 error: {e}")
    # Fallback to simulated temperature
    last_temperature = random.uniform(15, 35)
    return last_temperature


def read_light_level() -> int:
    """Reads light level from the light sensor, simulating if unavailable."""
    global last_light_level
    try:
        light_level = random.randint(0, 1000)
        last_light_level = light_level
        return light_level
    except Exception as e:
        print(f"Error reading light level: {e}")
        return last_light_level


def control_lights(state: str):
    """Controls the lights based on the given state."""
    try:
        if state == "on":
            GPIO.output(LIGHT_PIN, GPIO.HIGH)
            print("Lights turned ON")
        elif state == "off":
            GPIO.output(LIGHT_PIN, GPIO.LOW)
            print("Lights turned OFF")
        else:
            print("Invalid light state")
    except Exception as e:
        print(f"Error controlling lights: {e}")


def take_picture() -> Optional[str]:
    """Takes a picture using the Raspberry Pi camera."""
    if picam2 is None:
        print("Camera not available. Skipping picture.")
        return None
    try:
        timestamp = time.strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        picam2.capture_file(filename)
        print(f"Picture saved as {filename}")
        return filename
    except Exception as e:
        print(f"Error taking picture: {e}")
        return None


def listen_for_command() -> Optional[str]:
    """Listens for a voice command and returns the recognized text."""
    if sr is None:
        print("Warning: speech_recognition library not available. Command listening disabled.")
        return None
    try:
        recognizer = sr.Recognizer()
        with sr.Microphone() as source:
            print("Listening for wake word...")
            recognizer.adjust_for_ambient_noise(source, duration=0.5)
            audio = recognizer.listen(source, timeout=LISTENING_DURATION, phrase_time_limit=LISTENING_DURATION)
        print("Processing audio...")
        try:
            text = recognizer.recognize_google(audio)
            print(f"You said: {text}")
            return text.lower()
        except sr.UnknownValueError:
            print("Could not understand audio")
            return None
        except sr.RequestError as e:
            print(f"Could not request results from Google Speech Recognition service: {e}")
            return None
    except sr.WaitTimeoutError:
        print("Listening timed out.")
        return None
    except Exception as e:
        print(f"Error during voice recognition: {e}")
        return None


def is_wake_word_present(text: str) -> bool:
    """Checks if the wake word is present in the given text."""
    return WAKE_WORD.lower() in text


def process_command(command: str):
    """Processes the given voice command."""
    if "turn on the lights" in command:
        control_lights("on")
    elif "turn off the lights" in command:
        control_lights("off")
    elif "what is the temperature" in command:
        temperature = read_temperature()
        print(f"The temperature is {temperature:.1f} degrees Celsius")
    elif "take a picture" in command:
        take_picture()
    else:
        print("Unknown command")


def main():
    """Main function to run the greenhouse control system."""
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    init_gpio()
    init_camera()
    init_dht11()

    print("Greenhouse control system started. Press Ctrl+C to exit.")

    try:
        while running:
            command_text = listen_for_command()
            if command_text and is_wake_word_present(command_text):
                process_command(command_text)
            time.sleep(0.1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        cleanup_gpio()
        cleanup_camera()


if __name__ == "__main__":
    main()

