import asyncio
import logging
import os
import signal
import datetime
from pathlib import Path

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
PIR_PIN = 17
IMAGE_DIR = Path("images")
LOG_FILE = Path("security.log")
LOG_QUEUE_MAXSIZE = 1000
DEBOUNCE_DELAY = 0.5  # seconds
KEEP_LOGS_DAYS = 7

# ---------------------------------------------------------------------------
# Logging setup
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)
logger = logging.getLogger(__name__)

# ---------------------------------------------------------------------------
# Global shutdown flag
# ---------------------------------------------------------------------------
_shutdown_event = asyncio.Event()


def _request_shutdown():
    """Signal the main loop to exit."""
    if not _shutdown_event.is_set():
        logger.info("Shutdown requested.")
    _shutdown_event.set()


def _handle_signal(signum, frame):
    """Handle SIGINT / SIGTERM for graceful termination."""
    logger.info("Received signal %s, initiating shutdown.", signum)
    _request_shutdown()


# ---------------------------------------------------------------------------
# Async log queue consumer
# ---------------------------------------------------------------------------
async def log_queue_consumer(queue: asyncio.Queue, log_file: Path) -> None:
    """Drains the queue and writes records to the log file with daily rotation."""
    while True:
        try:
            record = await asyncio.wait_for(queue.get(), timeout=1.0)
        except asyncio.TimeoutError:
            if _shutdown_event.is_set():
                break
            continue

        if record is None:
            break

        # Daily rotation: remove files older than KEEP_LOGS_DAYS
        cutoff = datetime.date.today() - datetime.timedelta(days=KEEP_LOGS_DAYS)
        for path in log_file.parent.iterdir():
            if path.suffix != ".log":
                continue
            try:
                mtime = path.stat().st_mtime
            except OSError:
                continue
            try:
                file_date = datetime.date.fromtimestamp(mtime)
            except ValueError:
                continue
            if file_date < cutoff:
                try:
                    path.unlink()
                except OSError as exc:
                    logger.warning("Could not remove old log file %s: %s", path, exc)

        # Append the new record
        try:
            with log_file.open("a", encoding="utf-8") as fh:
                fh.write(record)
                fh.write("\n")
                fh.flush()
                os.fsync(fh.fileno())
        except OSError as exc:
            logger.error("Failed to write log record: %s", exc)
        finally:
            queue.task_done()


# ---------------------------------------------------------------------------
# PIR callback
# ---------------------------------------------------------------------------
async def motion_detected_callback(channel: int, queue: asyncio.Queue) -> None:
    """Rising-edge callback with software debounce and image capture."""
    try:
        # Debounce: ignore if the previous event fired within DEBOUNCE_DELAY
        if getattr(motion_detected_callback, "_last_event_time", 0) + DEBOUNCE_DELAY > time.monotonic():
            return
        motion_detected_callback._last_event_time = time.monotonic()

        timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        logger.info("Motion detected at %s", timestamp)

        # Capture image
        image_path = IMAGE_DIR / f"motion_{datetime.datetime.now().strftime('%Y%m%d_%H%M%S')}.jpg"
        try:
            if Picamera2 is not None:
                cam = Picamera2()
                cam.start()
                try:
                    cam.capture_file(str(image_path))
                finally:
                    cam.stop()
                    cam.close()
                logger.info("Image saved to %s", image_path)
            else:
                logger.warning("picamera2 not installed; skipping image capture.")
        except Exception as exc:
            logger.error("Failed to capture image: %s", exc)

        # Enqueue the log record
        record = f"{timestamp} - INFO - Motion detected"
        try:
            await queue.put(record)
        except asyncio.QueueFull:
            logger.warning("Log queue full; dropping record.")
    except Exception as exc:
        logger.error("Error in motion callback: %s", exc)


# ---------------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------------
async def main() -> None:
    # Register signal handlers for graceful shutdown
    loop = asyncio.get_running_loop()
    for sig in (signal.SIGINT, signal.SIGTERM):
        try:
            loop.add_signal_handler(sig, _handle_signal, sig, None)
        except NotImplementedError:
            # Fallback for environments where add_signal_handler is unavailable
            signal.signal(sig, _handle_signal)

    # Ensure directories exist
    try:
        IMAGE_DIR.mkdir(parents=True, exist_ok=True)
        LOG_FILE.parent.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        logger.error("Failed to create directories: %s", exc)
        return

    # Initialize GPIO
    if GPIO is not None:
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
            logger.info("GPIO initialized: BCM %d (pull-down).", PIR_PIN)
        except Exception as exc:
            logger.error("Failed to initialize GPIO: %s", exc)
            return
    else:
        logger.warning("RPi.GPIO not available; running in simulation mode.")

    # Initialize camera
    camera = None
    if Picamera2 is not None:
        try:
            camera = Picamera2()
            camera.configure(camera.create_still_configuration())
            camera.start()
            logger.info("Camera initialized.")
        except Exception as exc:
            logger.error("Failed to initialize camera: %s", exc)
            camera = None

    # Create queue and consumer task
    queue: asyncio.Queue = asyncio.Queue(maxsize=LOG_QUEUE_MAXSIZE)
    consumer_task = asyncio.create_task(log_queue_consumer(queue, LOG_FILE))

    # Register PIR callback
    if GPIO is not None:
        try:
            GPIO.add_event_detect(PIR_PIN, GPIO.RISING, callback=lambda ch: asyncio.create_task(motion_detected_callback(ch, queue)))
            logger.info("PIR sensor monitoring started on BCM %d.", PIR_PIN)
        except Exception as exc:
            logger.error("Failed to register PIR callback: %s", exc)
            GPIO.cleanup()
            return

    try:
        while not _shutdown_event.is_set():
            try:
                await asyncio.wait_for(_shutdown_event.wait(), timeout=1.0)
            except asyncio.TimeoutError:
                pass
    finally:
        logger.info("Shutting down...")
        # Cancel consumer task
        consumer_task.cancel()
        try:
            await consumer_task
        except asyncio.CancelledError:
            pass

        # Drain remaining queue entries
        while not queue.empty():
            try:
                queue.get_nowait()
                queue.task_done()
            except asyncio.QueueEmpty:
                break

        # Release camera
        if camera is not None:
            try:
                camera.stop()
                camera.close()
            except Exception as exc:
                logger.warning("Error releasing camera: %s", exc)

        # Release GPIO
        if GPIO is not None:
            try:
                GPIO.cleanup()
                logger.info("GPIO cleaned up.")
            except Exception as exc:
                logger.warning("Error cleaning up GPIO: %s", exc)

        logger.info("Shutdown complete.")


if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        _request_shutdown()
        try:
            asyncio.run(main())
        except RuntimeError:
            pass

