import time

try:
    import RPi.GPIO as GPIO
except RuntimeError as exc:
    print(f"Error: RPi.GPIO could not be initialized: {exc}", file=sys.stderr)
    sys.exit(1)

INPUT_PINS = (4, 5, 6)
OUTPUT_PINS = (23, 24)
POLL_INTERVAL = 0.05

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def main():
    global _running
    _running = True

    signal.signal(signal.SIGINT, _handle_sigint)

    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)

        for pin in INPUT_PINS:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)

        for pin in OUTPUT_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)

        output_24_state = False

        while _running:
            try:
                input_4_state = GPIO.input(INPUT_PINS[0])
                input_5_state = GPIO.input(INPUT_PINS[1])
                input_6_state = GPIO.input(INPUT_PINS[2])
            except Exception as exc:
                print(f"Error reading GPIO inputs: {exc}", file=sys.stderr)
                time.sleep(POLL_INTERVAL)
                continue

            if input_4_state == GPIO.LOW:
                GPIO.output(OUTPUT_PINS[0], GPIO.HIGH)
            elif input_4_state == GPIO.HIGH:
                GPIO.output(OUTPUT_PINS[0], GPIO.LOW)

            if input_5_state == GPIO.LOW:
                GPIO.output(OUTPUT_PINS[0], GPIO.LOW)

            if input_6_state == GPIO.LOW:
                output_24_state = not output_24_state
                GPIO.output(OUTPUT_PINS[1], GPIO.HIGH if output_24_state else GPIO.LOW)

            time.sleep(POLL_INTERVAL)

    except Exception as exc:
        print(f"Error during GPIO operation: {exc}", file=sys.stderr)
    finally:
        try:
            GPIO.cleanup()
        except Exception:
            pass


if __name__ == "__main__":
    main()

