import io
import os
import signal
import sys
import time
import threading
import subprocess
import zmq
from threading import Condition, Lock, Event

try:
    from picamera2 import Picamera2
    from picamera2.encoders import MJPEGEncoder
    from picamera2.outputs import Output
except ImportError:
    print("picamera2 is not installed. Install with: pip install picamera2")
    sys.exit(1)

try:
    import gps3
except ImportError:
    print("gps3 is not installed. Install with: pip install gps3")
    sys.exit(1)

DEFAULT_LAT = 22.483425
DEFAULT_LON = 88.455463
GPS_RESTART_CMD = "sudo systemctl restart gpsd"

shutdown_event = Event()
coord_lock = Lock()
coord_cond = Condition(coord_lock)
lat = DEFAULT_LAT
lon = DEFAULT_LON
mag = 0.0
alt = 0.0


def restart_gpsd():
    try:
        subprocess.run(GPS_RESTART_CMD.split(), check=True, timeout=10)
        print("GPS service restarted.")
    except subprocess.CalledProcessError as e:
        print(f"Error restarting GPS service: {e}")
    except subprocess.TimeoutExpired:
        print("Timeout restarting GPS service.")
    except FileNotFoundError:
        print("Error: 'sudo' or 'systemctl' not found.")
    except Exception as e:
        print(f"Unexpected error restarting GPS: {e}")


def validate_coordinates(latitude, longitude):
    try:
        lat_val = float(latitude)
        lon_val = float(longitude)
        if -90 <= lat_val <= 90 and -180 <= lon_val <= 180:
            return lat_val, lon_val
        print("Invalid latitude or longitude range.")
        return None, None
    except (ValueError, TypeError):
        print("Invalid latitude or longitude format.")
        return None, None


def send_data_with_retry(socket, data, max_retries=1):
    for attempt in range(max_retries + 1):
        try:
            socket.send_string(data, zmq.SNDMORE)
            socket.send_string("lat,lon,mag,alt")
            return True
        except zmq.ZMQError as e:
            print(f"ZMQError sending data (attempt {attempt + 1}/{max_retries + 1}): {e}")
            if attempt == max_retries:
                return False
            time.sleep(1)
    return False


def capture_and_send_images(socket):
    global lat, lon, mag, alt
    try:
        picam2 = Picamera2()
        config = picam2.create_video_configuration(
            main={"size": (640, 480), "format": "MJPEG"},
            controls={"FrameRate": 100},
            transform=Transform(vflip=True, hflip=True)
        )
        picam2.configure(config)
        picam2.start()
        print("Camera started successfully.")

        while not shutdown_event.is_set():
            try:
                frame = picam2.capture_array()
                if frame is None:
                    print("Warning: Captured empty frame.")
                    continue

                stream = io.BytesIO()
                picam2.encoder.encode(frame, stream)
                stream.seek(0)

                with coord_lock:
                    lat_val, lon_val, mag_val, alt_val = lat, lon, mag, alt

                csv_data = f"{lat_val},{lon_val},{mag_val},{alt_val}"
                if not send_data_with_retry(socket, csv_data):
                    print("Failed to send data after retries. Shutting down.")
                    shutdown_event.set()
                    break

                with coord_cond:
                    if not coord_cond.wait(timeout=0.1):
                        continue

                stream.seek(0)
                socket.send(stream.read())
            except Exception as e:
                print(f"Error capturing or sending image: {e}")
                if not shutdown_event.is_set():
                    time.sleep(1)
    except Exception as e:
        print(f"Camera initialization or runtime error: {e}")
    finally:
        try:
            picam2.stop()
            picam2.close()
        except Exception:
            pass
        print("Camera thread exiting.")


def get_gps_data():
    global lat, lon, mag, alt
    gps_socket = gps3.GPSDSocket()
    data_stream = gps3.DataStream()

    try:
        gps_socket.connect()
        gps_socket.watch()
        print("GPS socket connected.")

        while not shutdown_event.is_set():
            try:
                for new_data in gps_socket:
                    if shutdown_event.is_set():
                        break
                    if new_data:
                        data_stream.unpack(new_data)
                        latitude = data_stream.TPV['lat']
                        longitude = data_stream.TPV['lon']
                        mag_field = data_stream.TPV['mag']
                        altitude = data_stream.TPV['alt']

                        if isinstance(latitude, (int, float)) and isinstance(longitude, (int, float)):
                            lat, lon = validate_coordinates(latitude, longitude)
                            if lat is not None and lon is not None:
                                with coord_lock:
                                    lat = lat
                                    lon = lon
                                print(f"GPS: Latitude={lat}, Longitude={lon}")
                            else:
                                print("Invalid GPS coordinates received.")
                        else:
                            print("Incomplete GPS data received.")

                        if isinstance(mag_field, (int, float)):
                            with coord_lock:
                                mag = mag_field
                        if isinstance(altitude, (int, float)):
                            with coord_lock:
                                alt = altitude

                        with coord_cond:
                            coord_cond.notify_all()

                    if shutdown_event.is_set():
                        break
                    time.sleep(0.5)
            except StopIteration:
                print("GPS socket closed.")
                break
            except Exception as e:
                print(f"Error reading GPS data: {e}")
                restart_gpsd()
                time.sleep(1)
    except Exception as e:
        print(f"GPS socket connection error: {e}")
        restart_gpsd()
    finally:
        try:
            gps_socket.close()
        except Exception:
            pass
        print("GPS thread exiting.")


def main():
    context = None
    footage_socket = None
    image_thread = None
    gps_thread = None

    def signal_handler(signum, frame):
        print(f"Signal {signum} received, shutting down...")
        shutdown_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        context = zmq.Context()
        footage_socket = context.socket(zmq.PUB)
        footage_socket.setsockopt(zmq.LINGER, 0)
        footage_socket.bind('tcp://0.0.0.0:5555')
        print("ZMQ socket bound to tcp://0.0.0.0:5555")

        image_thread = threading.Thread(target=capture_and_send_images, args=(footage_socket,))
        gps_thread = threading.Thread(target=get_gps_data)

        image_thread.start()
        gps_thread.start()

        while not shutdown_event.is_set():
            time.sleep(0.1)

    except zmq.ZMQError as e:
        print(f"ZMQError: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        shutdown_event.set()
        if image_thread:
            image_thread.join(timeout=5)
        if gps_thread:
            gps_thread.join(timeout=5)
        if footage_socket:
            try:
                footage_socket.close()
            except Exception:
                pass
        if context:
            context.term()
        print("Program finished.")


if __name__ == '__main__':
    main()

