import sys
import time
from datetime import datetime

import cv2
import numpy as np
from pyzbar.pyzbar import decode as zbar_decode

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
CAMERA_INDEX = 0                       # First USB camera
CAPTURE_INTERVAL = 0.2                 # seconds between captures
LOG_FILE = "inventory_log.csv"         # CSV inventory log
ERROR_FILE = "error_log.txt"           # Errors are appended here
CAMERA_IDENTIFIER = "Camera 1"         # Fixed identifier for the camera

# ---------------------------------------------------------------------------
# Globals for signal handling
# ---------------------------------------------------------------------------
_running = True


def _signal_handler(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    _running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def log_error(message: str) -> None:
    """Append a timestamped error line to ERROR_FILE."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(ERROR_FILE, "a", encoding="utf-8") as fh:
            fh.write(f"{timestamp} - {message}\n")
    except OSError as exc:
        # Last-resort: print to stderr so the error is not silently lost.
        print(f"[ERROR] Cannot write to {ERROR_FILE}: {exc}", file=sys.stderr)


def init_camera() -> cv2.VideoCapture | None:
    """Open the USB camera; return None on failure."""
    try:
        cap = cv2.VideoCapture(CAMERA_INDEX, cv2.CAP_V4L2)
    except Exception as exc:
        log_error(f"cv2.VideoCapture({CAMERA_INDEX}) failed: {exc}")
        return None

    if not cap.isOpened():
        log_error(f"Camera {CAMERA_INDEX} did not open.")
        return None

    # Brief warm-up so auto-exposure / white-balance settle.
    for _ in range(5):
        if not _running:
            cap.release()
            return None
        time.sleep(0.1)

    return cap


def capture_frame(cap: cv2.VideoCapture) -> np.ndarray | None:
    """Capture a single grayscale frame; return None on failure."""
    try:
        ok, frame = cap.read()
    except Exception as exc:
        log_error(f"cap.read() failed: {exc}")
        return None

    if not ok or frame is None:
        log_error("Camera read returned invalid frame.")
        return None

    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
    except Exception as exc:
        log_error(f"cvtColor failed: {exc}")
        return None

    return gray


def decode_qr_code(gray: np.ndarray) -> str | None:
    """Decode the first QR code found in the grayscale frame."""
    try:
        for obj in zbar_decode(gray):
            data = obj.data
            if not isinstance(data, str):
                data = str(data)
            return data
    except Exception as exc:
        log_error(f"zbar_decode failed: {exc}")
    return None


def validate_data(data: str) -> bool:
    """Return True only if data is non-empty and contains only letters or digits."""
    if not data:
        return False
    return data.isalnum()


def log_inventory_data(data: str) -> None:
    """Append a validated record to the CSV log file."""
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    try:
        with open(LOG_FILE, "a", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow([CAMERA_IDENTIFIER, data, timestamp])
    except OSError as exc:
        log_error(f"Failed to write CSV row: {exc}")


def main() -> int:
    cap = init_camera()
    if cap is None:
        print("Failed to initialise camera. See error_log.txt.", file=sys.stderr)
        return 1

    # Write CSV header only if the file is new / empty.
    try:
        needs_header = os.path.exists(LOG_FILE) and os.path.getsize(LOG_FILE) == 0
    except OSError:
        needs_header = True

    if needs_header:
        try:
            with open(LOG_FILE, "a", newline="", encoding="utf-8") as fh:
                writer = csv.writer(fh)
                writer.writerow(["Camera Identifier", "Item Identifier", "Timestamp"])
        except OSError as exc:
            log_error(f"Failed to write CSV header: {exc}")

    print("QR code scanner running. Press Ctrl-C to stop.")

    try:
        while _running:
            frame = capture_frame(cap)
            if frame is None:
                time.sleep(CAPTURE_INTERVAL)
                continue

            data = decode_qr_code(frame)
            if data is None:
                time.sleep(CAPTURE_INTERVAL)
                continue

            if validate_data(data):
                log_inventory_data(data)
                print(f"Scanned: {data}")
            else:
                log_error(f"Invalid data scanned: {data!r}")

            time.sleep(CAPTURE_INTERVAL)
    finally:
        cap.release()
        cv2.destroyAllWindows()
        print("Camera released. Exiting.")

    return 0


if __name__ == "__main__":
    sys.exit(main())

