import logging
import signal
import sys
import time
import cv2
import numpy as np
from functools import partial

try:
    import RPi.GPIO as GPIO
except ImportError:
    GPIO = None

try:
    import libcamera
    from libcamera import Transform
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None
    libcamera = None

try:
    import serial
except ImportError:
    serial = None

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

X_THRESHOLD = 24
CENTER_X = 128
CENTER_Y = 96
SERVO_PIN_1 = 7
SERVO_PIN_2 = 13
SERVO_FREQ = 50
SERVO_CENTER_DUTY = 7.0
UART_BAUDRATE = 115200
CAMERA_RESOLUTION = (640, 480)
CAMERA_FRAMERATE = 16
MIN_AREA = 10
MAX_RECONNECT_ATTEMPTS = 3
RECONNECT_DELAY = 5

running = True


def signal_handler(sig, frame):
    global running
    running = False


signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)


def clamp(value, min_val, max_val):
    return max(min_val, min(value, max_val))


def calculate_distance(x1, y1, x2, y2):
    return ((x2 - x1) ** 2 + (y2 - y1) ** 2) ** 0.5


def calculate_angle(dx, dy):
    if dx == 0:
        return 90 if dy > 0 else 270
    angle = int(np.degrees(np.arctan2(dy, dx)))
    return angle if angle >= 0 else angle + 360


def set_servo_angle(angle):
    if GPIO is None:
        logger.error("RPi.GPIO not available; cannot set servo angle.")
        return
    try:
        pwm1.ChangeDutyCycle(angle)
        pwm2.ChangeDutyCycle(angle)
    except Exception as e:
        logger.error(f"Error setting servo angle: {e}")


def set_servo_center():
    set_servo_angle(SERVO_CENTER_DUTY)


def set_servo_left():
    set_servo_angle(90)


def set_servo_right():
    set_servo_angle(270)


def set_servo_up():
    set_servo_angle(180)


def set_servo_down():
    set_servo_angle(0)


def segment_color_hsv(frame, lower_bound, upper_bound):
    hsv = cv2.cvtColor(frame, cv2.COLOR_BGR2HSV)
    return cv2.inRange(hsv, lower_bound, upper_bound)


def segment_color_ycrcb(frame, lower_bound, upper_bound):
    ycrcb = cv2.cvtColor(frame, cv2.COLOR_BGR2YCrCb)
    return cv2.inRange(ycrcb, lower_bound, upper_bound)


def find_blob(mask):
    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_SIMPLE)
    largest_contour = None
    for contour in contours:
        area = cv2.contourArea(contour)
        if area > MIN_AREA:
            if largest_contour is None or area > cv2.contourArea(largest_contour):
                largest_contour = contour
    return largest_contour


def calculate_center(contour):
    if contour is None:
        return None, None
    x, y, w, h = cv2.boundingRect(contour)
    return int(x + w / 2), int(y + h / 2)


def track_object(x, y):
    if x is None or y is None:
        return
    global running
    try:
        if x < CENTER_X - X_THRESHOLD:
            logger.info("Tracking error: Object too far left")
            set_servo_left()
        elif x > CENTER_X + X_THRESHOLD:
            logger.info("Tracking error: Object too far right")
            set_servo_right()
        else:
            logger.info("Object centered")
            set_servo_center()
    except Exception as e:
        logger.error(f"Error tracking object: {e}")


def initialize_camera():
    if Picamera2 is None:
        logger.error("picamera2 library not available.")
        return None
    try:
        picam2 = Picamera2()
        config = picam2.create_preview_configuration(
            main={"size": CAMERA_RESOLUTION, "format": "BGR888"},
            transform=Transform(hflip=True, vflip=True)
        )
        picam2.configure(config)
        picam2.start()
        time.sleep(2)
        return picam2
    except Exception as e:
        logger.error(f"Error initializing camera: {e}")
        return None


def initialize_gpio():
    if GPIO is None:
        logger.warning("RPi.GPIO not available; servo control disabled.")
        return None, None
    try:
        GPIO.setmode(GPIO.BOARD)
        GPIO.setup(SERVO_PIN_1, GPIO.OUT)
        GPIO.setup(SERVO_PIN_2, GPIO.OUT)
        pwm1 = GPIO.PWM(SERVO_PIN_1, SERVO_FREQ)
        pwm2 = GPIO.PWM(SERVO_PIN_2, SERVO_FREQ)
        pwm1.start(SERVO_CENTER_DUTY)
        pwm2.start(SERVO_CENTER_DUTY)
        return pwm1, pwm2
    except Exception as e:
        logger.error(f"Error initializing GPIO: {e}")
        return None, None


def initialize_uart():
    if serial is None:
        logger.warning("pyserial not available; UART disabled.")
        return None
    try:
        uart = serial.Serial("/dev/serial0", baudrate=UART_BAUDRATE, timeout=1)
        return uart
    except Exception as e:
        logger.error(f"Error initializing UART: {e}")
        return None


def process_frame(frame, uart):
    hsv_lower = np.array([160, 160, 10])
    hsv_upper = np.array([190, 255, 255])
    ycrcb_lower = np.array([0, 165, 0])
    ycrcb_upper = np.array([255, 255, 255])

    mask_hsv = segment_color_hsv(frame, hsv_lower, hsv_upper)
    mask_ycrcb = segment_color_ycrcb(frame, ycrcb_lower, ycrcb_upper)
    mask = cv2.bitwise_or(mask_hsv, mask_ycrcb)

    contour = find_blob(mask)
    x, y = calculate_center(contour)

    if x is not None and y is not None:
        track_object(x, y)
        distance = calculate_distance(x, y, CENTER_X, CENTER_Y)
        angle = calculate_angle(x - CENTER_X, y - CENTER_Y)
        if uart:
            try:
                uart.write(f"{distance},{angle}\n".encode())
            except Exception as e:
                logger.error(f"Error sending data over UART: {e}")
    else:
        logger.info("No object detected")


def main():
    global pwm1, pwm2
    picam2 = None
    uart = None
    pwm1, pwm2 = None, None

    try:
        picam2 = initialize_camera()
        if picam2 is None:
            raise RuntimeError("Camera initialization failed.")

        pwm1, pwm2 = initialize_gpio()
        if pwm1 is None or pwm2 is None:
            raise RuntimeError("GPIO initialization failed.")

        uart = initialize_uart()
        if uart is not None:
            logger.info("UART initialized successfully.")

        reconnect_attempts = 0
        while running:
            try:
                frame = picam2.capture_array()
                if frame is None:
                    raise RuntimeError("Failed to capture frame.")
                process_frame(frame, uart)
            except Exception as e:
                logger.error(f"Error processing frame: {e}")
                if reconnect_attempts < MAX_RECONNECT_ATTEMPTS:
                    reconnect_attempts += 1
                    logger.info(f"Reconnecting in {RECONNECT_DELAY} seconds...")
                    time.sleep(RECONNECT_DELAY)
                    picam2 = initialize_camera()
                    if picam2 is None:
                        raise RuntimeError("Camera reconnection failed.")
                    reconnect_attempts = 0
                else:
                    logger.error("Max reconnect attempts reached. Exiting.")
                    break
    except Exception as e:
        logger.error(f"Fatal error: {e}")
    finally:
        logger.info("Cleaning up resources...")
        if picam2:
            try:
                picam2.stop()
            except Exception:
                pass
        if uart:
            try:
                uart.close()
            except Exception:
                pass
        if pwm1:
            try:
                pwm1.stop()
            except Exception:
                pass
        if pwm2:
            try:
                pwm2.stop()
            except Exception:
                pass
        if GPIO is not None:
            try:
                GPIO.cleanup()
            except Exception:
                pass
        logger.info("Cleanup complete. Exiting.")


if __name__ == "__main__":
    main()

