import asyncio
import logging
import signal
import threading
from typing import Callable, Optional

import cv2
import numpy as np

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)


class Camera:
    """Thin wrapper around OpenCV VideoCapture for Raspberry Pi camera streaming."""

    def __init__(self, src: int = 0, buffer_size: int = 64, callback: Optional[Callable] = None):
        self.src = src
        self.buffer_size = buffer_size
        self.callback = callback
        self._cap: Optional[cv2.VideoCapture] = None
        self._lock = threading.Lock()
        self._frame: Optional[np.ndarray] = None
        self._running = False

    def open(self) -> bool:
        self._cap = cv2.VideoCapture(self.src, cv2.CAP_V4L2)
        if not self._cap.isOpened():
            logger.error("Failed to open camera source %s", self.src)
            self._cap = None
            return False
        self._cap.set(cv2.CAP_PROP_FRAME_WIDTH, 640)
        self._cap.set(cv2.CAP_PROP_FRAME_HEIGHT, 480)
        self._cap.set(cv2.CAP_PROP_FPS, 10)
        self._running = True
        logger.info("Camera opened: %s", self.src)
        return True

    def start(self):
        if self._running:
            return
        self._running = True
        t = threading.Thread(target=self._loop, daemon=True)
        t.start()

    def stop(self):
        self._running = False
        if self._cap is not None:
            with self._lock:
                if self._cap is not None:
                    self._cap.release()
                    self._cap = None
            logger.info("Camera stopped")

    def _loop(self):
        while self._running:
            ok, frame = self._cap.read()
            if not ok or frame is None:
                logger.warning("Frame read failed; retrying")
                time.sleep(0.1)
                continue
            with self._lock:
                self._frame = frame
            if self.callback is not None:
                try:
                    self.callback(frame)
                except Exception as exc:
                    logger.error("Callback error: %s", exc)
            if self.buffer_size > 0:
                time.sleep(1.0 / 10.0)

    def read(self) -> Optional[np.ndarray]:
        with self._lock:
            return self._frame.copy() if self._frame is not None else None


class WebSocketHandler:
    """Minimal WebSocket handler exposing connection tracking and broadcast."""

    def __init__(self):
        self._lock = threading.Lock()
        self._connections: list = []

    def has_connections(self) -> bool:
        with self._lock:
            return bool(self._connections)

    def add_connection(self, conn):
        with self._lock:
            self._connections.append(conn)

    def remove_connection(self, conn):
        with self._lock:
            self._connections.remove(conn)

    def broadcast(self, data: bytes):
        with self._lock:
            for conn in list(self._connections):
                try:
                    conn.send(data)
                except Exception as exc:
                    logger.warning("Broadcast send error: %s", exc)


def detect_motion_function(prev_frame: Optional[np.ndarray], curr_frame: Optional[np.ndarray]) -> bool:
    if prev_frame is None or curr_frame is None:
        return False
    try:
        diff = cv2.absdiff(prev_frame, curr_frame)
        gray = cv2.cvtColor(diff, cv2.COLOR_BGR2GRAY)
        blur = cv2.GaussianBlur(gray, (5, 5), 0)
        _, thresh = cv2.threshold(blur, 20, 255, cv2.THRESH_BINARY)
        dilated = cv2.dilate(thresh, None, iterations=3)
        contours, _ = cv2.findContours(dilated, cv2.RETR_TREE, cv2.CHAIN_APPROX_SIMPLE)
        return bool(contours)
    except Exception as exc:
        logger.error("Motion detection error: %s", exc)
        return False


def convert_jpeg_to_frame(data: bytes) -> Optional[np.ndarray]:
    if not data:
        return None
    try:
        idx = data.find(b'\xff\xd8')
        if idx == -1:
            return None
        end = data.find(b'\xff\xd9', idx)
        if end == -1:
            return None
        jpeg_bytes = data[idx:end + 2]
        frame = cv2.imdecode(np.frombuffer(jpeg_bytes, dtype=np.uint8), cv2.IMREAD_COLOR)
        if frame is None:
            logger.warning("imdecode returned None for %d bytes", len(jpeg_bytes))
        return frame
    except Exception as exc:
        logger.error("JPEG decode error: %s", exc)
        return None


def send_frame(ws_handler: WebSocketHandler, frame: np.ndarray):
    try:
        ok, encoded = cv2.imencode('.jpg', frame)
        if not ok or encoded is None:
            logger.warning("JPEG encode failed")
            return
        data = encoded.tobytes()
        if ws_handler.has_connections():
            asyncio.get_event_loop().call_soon_threadsafe(ws_handler.broadcast, data)
    except Exception as exc:
        logger.error("Send frame error: %s", exc)


def signal_handler(signum, frame):
    logger.info("Signal %s received, shutting down", signum)
    raise SystemExit(0)


def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    cam = Camera(src=0, buffer_size=64)
    if not cam.open():
        logger.error("Camera init failed")
        return

    ws_handler = WebSocketHandler()
    cam.callback = lambda f: send_frame(ws_handler, f)

    cam.start()
    logger.info("Camera streaming started; press Ctrl+C to stop")

    try:
        while True:
            frame = cam.read()
            if frame is not None:
                prev_frame = frame.copy()
                curr_frame = frame.copy()
                if detect_motion_function(prev_frame, curr_frame):
                    logger.info("Motion detected")
            time.sleep(0.1)
    except SystemExit:
        pass
    finally:
        cam.stop()
        logger.info("Cleanup complete")


if __name__ == '__main__':
    import time
    main()

