import os
import time
import signal
import logging
import datetime
from PIL import Image

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("RPi.GPIO requires root privileges or a Raspberry Pi environment.")
    raise

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

# Configuration
PIR_PIN = 4
IMAGE_DIR = "wildlife_captures"
LOG_FILE = "wildlife_camera.log"
DEBOUNCE_DELAY = 3  # seconds
IMAGE_SIZE = (64, 64)

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)


def setup_camera():
    if Picamera2 is None:
        logging.warning("picamera2 not installed; using fallback image generation.")
        return None
    try:
        cam = Picamera2()
        cam.configure(cam.create_still_configuration())
        cam.start()
        logging.info("Picamera2 initialized successfully.")
        return cam
    except Exception as e:
        logging.error(f"Failed to initialize Picamera2: {e}")
        return None


def capture_image(cam):
    """Capture an image using the camera or generate a fallback if unavailable."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d_%H-%M-%S")
    filename = os.path.join(IMAGE_DIR, f"wildlife_{timestamp}.jpg")

    if cam is not None:
        try:
            cam.capture_file(filename)
            logging.info(f"Image captured by camera: {filename}")
            return filename
        except Exception as e:
            logging.error(f"Camera capture failed: {e}. Generating fallback image.")
            generate_fallback_image(filename)
            return filename
    else:
        generate_fallback_image(filename)
        return filename


def generate_fallback_image(filename):
    """Generate a 64x64 white image as a fallback."""
    try:
        img = Image.new("RGB", IMAGE_SIZE, "white")
        img.save(filename)
        logging.info(f"Fallback image generated: {filename}")
    except Exception as e:
        logging.error(f"Failed to generate fallback image: {e}")


def simulate_cloud_upload(filename):
    logging.info(f"Simulating cloud upload: {filename}")


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        os.makedirs(IMAGE_DIR, exist_ok=True)
    except OSError as e:
        logging.error(f"Failed to create image directory: {e}")
        return

    setup_gpio()
    cam = setup_camera()

    try:
        while _running:
            try:
                if GPIO.input(PIR_PIN):
                    logging.info("Motion detected!")
                    capture_image(cam)
                    simulate_cloud_upload("wildlife_captures/placeholder")
                    time.sleep(DEBOUNCE_DELAY)
                else:
                    time.sleep(0.1)
            except Exception as e:
                logging.error(f"Error in main loop: {e}")
                time.sleep(1)
    finally:
        if cam is not None:
            try:
                cam.stop()
            except Exception:
                pass
        GPIO.cleanup()
        logging.info("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

