import io
import logging
import signal
import threading
import time
from typing import Callable, Optional

import cv2
import numpy as np

try:
    from greenlet import getcurrent as get_ident
except ImportError:
    try:
        from thread import get_ident
    except ImportError:
        from _thread import get_ident

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(name)s - %(message)s",
)
logger = logging.getLogger(__name__)


class Camera:
    """Wrapper around the picamera2 / libcamera driver stack."""

    def __init__(self):
        self._video_stream: Optional["VideoStream"] = None
        self._picam2: Optional = None
        self._started = False
        self._lock = threading.Lock()

    def initialize(self, resolution=(640, 480), framerate=30):
        with self._lock:
            if self._started:
                logger.warning("Camera already started.")
                return self
            try:
                from picamera2 import Picamera2
            except ImportError:
                logger.error("picamera2 library is not installed.")
                return None

            try:
                self._picam2 = Picamera2()
                config = self._picam2.create_video_configuration(
                    main={"size": resolution, "format": "RGB888"},
                    controls={"FrameRate": framerate},
                )
                self._picam2.configure(config)
                self._picam2.start()
                self._started = True
                logger.info("Camera initialized successfully.")
                return self
            except Exception as e:
                logger.error(f"Error initializing camera: {e}")
                self._picam2 = None
                return None

    def start(self):
        if self._video_stream:
            return self._video_stream
        with self._lock:
            if self._started and self._picam2:
                self._video_stream = VideoStream(
                    self._picam2,
                    resolution=(640, 480),
                    framerate=30,
                    resolution_switch_callback=None,
                )
                self._video_stream._current_buffer = MotionDetectionBuffer(
                    self._video_stream.frame_count
                )
                return self._video_stream
            logger.error("Camera not initialized.")
            return None

    def stop(self):
        with self._lock:
            if self._video_stream:
                self._video_stream.stop()
            if self._picam2:
                try:
                    self._picam2.stop()
                except Exception as e:
                    logger.error(f"Error stopping camera: {e}")
                finally:
                    self._picam2 = None
            self._started = False

    def get_frame(self):
        if self._video_stream:
            return self._video_stream.read()
        return None


class VideoStream:
    """Streams video from a camera to connected WebSocket clients."""

    def __init__(
        self,
        camera,
        resolution,
        framerate,
        resolution_switch_callback=None,
    ):
        self.camera = camera
        self.resolution = resolution
        self.framerate = framerate
        self.resolution_switch_callback = resolution_switch_callback
        self.frame = None
        self.frame_count = 0
        self.buffer = CameraStreamBuffer()
        self._current_buffer = self.buffer
        self._lock = threading.Lock()
        self._thread = None
        self._stop_event = threading.Event()
        self._prev_frame = None
        self._curr_frame = None

    def start(self):
        if self._thread and self._thread.is_alive():
            return self
        self._stop_event.clear()
        self._thread = threading.Thread(target=self._update, daemon=True)
        self._thread.start()
        return self

    def stop(self):
        self._stop_event.set()
        if self._thread and self._thread.is_alive():
            self._thread.join(timeout=5.0)
        self._thread = None

    def _update(self):
        try:
            while not self._stop_event.is_set():
                try:
                    frame = self.camera.read()
                    if frame is None:
                        logger.warning("Failed to grab frame from camera.")
                        time.sleep(0.1)
                        continue

                    with self._lock:
                        self.frame = frame
                        self.frame_count += 1

                    self._current_buffer.write(frame)
