import io
import logging
import numpy as np
from typing import Callable, Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class CameraStreamBuffer:
    """Buffer for handling MJPEG streams from a Raspberry Pi camera driver."""

    def __init__(self, c, f: Callable, complete_frame: bool = False):
        self.c = c
        self.f = f
        self.buf = io.BytesIO()
        self.complete_frame = complete_frame
        self._frame_count = 0

    def write(self, data: bytes) -> int:
        try:
            self.buf.write(data)
            if self.complete_frame:
                frame_type = getattr(self.c, 'encode', {}).get('motion', 0)
                if frame_type != 1:
                    self.flush()
            return len(data)
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.write: {e}")
            return 0

    def flush(self) -> None:
        try:
            frame = self.buf.getvalue()
            if frame:
                self.f(frame)
            self.buf.seek(0)
            self.buf.truncate()
        except Exception as e:
            logger.error(f"Error in CameraStreamBuffer.flush: {e}")


class MotionDetectionBuffer:
    """Buffer for detecting motion in a MJPEG stream using a callback."""

    def __init__(self, f: Callable):
        self.f = f
        self.buf = io.BytesIO()
        self.previous_frame = None
        self.current_frame = None
        self._frame_count = 0

    def write(self, data: bytes) -> int:
        try:
            for byte in data:
                if byte == 0xFF and self.buf.tell() > 1:
                    prev_byte = self.buf.getvalue()[-2]
                    if prev_byte == 0xD8:
                        frame_data = self.buf.getvalue()
                        if frame_data:
                            try:
                                arr = np.frombuffer(frame_data, dtype=np.uint8)
                                self.previous_frame = self.current_frame
                                self.current_frame = self.f(arr)
                            except Exception as e:
                                logger.error(f"Error decoding frame in MotionDetectionBuffer: {e}")
                                self.previous_frame = None
                                self.current_frame = None
                        self.buf.seek(0)
                        self.buf.truncate()
                self.buf.write(bytes([byte]))
            return len(data)
        except Exception as e:
            logger.error(f"Error in MotionDetectionBuffer.write: {e}")
            return 0

