import cv2
import select
import sys
import time
import signal
import threading
import numpy as np
from typing import Optional, Tuple

import config
import face
from gpiozero import OutputDevice, Button

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_lock: Optional[OutputDevice] = None
_button: Optional[Button] = None
_mixer: Optional = None
_sounds: dict = {}
_running = True


def _cleanup() -> None:
    """Release all hardware and audio resources."""
    global _lock, _button, _mixer
    if _lock is not None:
        try:
            _lock.off()
            _lock.close()
        except Exception:
            pass
        _lock = None
    if _button is not None:
        try:
            _button.close()
        except Exception:
            pass
        _button = None
    if _mixer is not None:
        try:
            _mixer.cleanup()
        except Exception:
            pass
        _mixer = None


def _signal_handler(signum, frame) -> None:
    """Handle SIGINT / SIGTERM for a clean shutdown."""
    global _running
    _running = False


def _load_model() -> Optional[cv2.face.EigenFaceRecognizer]:
    """Load the EigenFaceRecognizer model from config.TRAINING_FILE."""
    try:
        model = cv2.face.EigenFaceRecognizer_create()
        model.read(config.TRAINING_FILE)
        return model
    except cv2.error as exc:
        print(f"[ERROR] Failed to load EigenFace model: {exc}", file=sys.stderr)
        return None
    except Exception as exc:
        print(f"[ERROR] Unexpected error loading model: {exc}", file=sys.stderr)
        return None


def _load_sounds() -> bool:
    """Pre-load the welcome, wait, and later sound files."""
    global _sounds
    for name, path in (
        ("welcome", "welcome.wav"),
        ("wait", "wait.wav"),
        ("later", "later.wav"),
    ):
        try:
            _sounds[name] = config.Sound(path)
        except Exception as exc:
            print(f"[ERROR] Failed to load sound '{path}': {exc}", file=sys.stderr)
            return False
    return True


def _process_face(model: cv2.face.EigenFaceRecognizer) -> Optional[Tuple[str, float]]:
    """Detect a face in the next frame and recognise it."""
    try:
        camera = cv2.VideoCapture(0)
    except Exception as exc:
        print(f"[ERROR] Failed to open camera: {exc}", file=sys.stderr)
        return None

    try:
        ret, frame = camera.read()
        if not ret or frame is None:
            print("[WARN] Could not read frame from camera.", file=sys.stderr)
            return None

        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        face_rect = face.detect_single(gray)
        if face_rect is None:
            print("[INFO] No face detected.")
            return None

        x, y, w, h = face_rect
        cropped = face.crop(gray, x, y, w, h)
        resized = face.resize(cropped)
        label, confidence = model.predict(resized)
        return label, float(confidence)
    except Exception as exc:
        print(f"[ERROR] Face recognition failed: {exc}", file=sys.stderr)
        return None
    finally:
        try:
            camera.release()
        except Exception:
            pass


def _play_sound(name: str) -> None:
    """Play a pre-loaded sound via the audio mixer."""
    sound = _sounds.get(name)
    if sound is None:
        print(f"[WARN] Sound '{name}' not loaded.", file=sys.stderr)
        return
    try:
        sound.play()
    except Exception as exc:
        print(f"[ERROR] Failed to play sound '{name}': {exc}", file=sys.stderr)


def _button_up() -> bool:
    """Return True when the button is currently pressed (active-low with pull-up)."""
    if _button is None:
        return False
    try:
        return _button.is_pressed
    except Exception:
        return False


def main() -> None:
    """Main door-lock control loop."""
    global _lock, _button, _mixer, _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # --- GPIO setup ----------------------------------------------------------
    try:
        _lock = OutputDevice(18, active_high=True, initial_value=True)
        _button = Button(17, pull_up=True, bounce_time=0.05)
    except Exception as exc:
        print(f"[ERROR] GPIO init failed: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    # --- Model / sound setup -------------------------------------------------
    model = _load_model()
    if model is None:
        _cleanup()
        sys.exit(1)

    if not _load_sounds():
        _cleanup()
        sys.exit(1)

    # --- Audio mixer setup ---------------------------------------------------
    try:
        _mixer = config.SimpleAudioPlayer()
    except Exception as exc:
        print(f"[ERROR] Audio mixer init failed: {exc}", file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print("[INFO] Door lock controller running. Press Ctrl+C to exit.")

    # --- Main loop -----------------------------------------------------------
    while _running:
        start = time.monotonic()

        if _button_up():
            result = _process_face(model)
            if result is None:
                _play_sound("later")
            else:
                label, confidence = result
                if (
                    label == config.POSITIVE_LABEL
                    and confidence < config.POSITIVE_THRESHOLD
                ):
                    try:
                        _lock.off()  # unlock
                    except Exception as exc:
                        print(f"[ERROR] Failed to unlock: {exc}", file=sys.stderr)
                    _play_sound("welcome")
                else:
                    _play_sound("wait")

        # Maintain ~0.1 s cadence
        elapsed = time.monotonic() - start
        remaining = 0.1 - elapsed
        if remaining > 0:
            time.sleep(remaining)

    _cleanup()
    print("[INFO] Shutdown complete.")


if __name__ == "__main__":
    main()

