import signal
import sys
import time

import smbus2
from luma.core.interface.serial import i2c
from luma.oled.device import ssd1306

I2C_BUS = 1
I2C_ADDR = 0x23
OLED_ADDR = 0x3C
BH1750_POWER_ON = 0x01
BH1750_RESET = 0x07
BH1750_CONTINUOUS_HIGH_RES_MODE = 0x10
CONVERSION_DELAY = 0.12
UPDATE_INTERVAL = 1.0

running = True
bus = None
display = None


def handle_signal(signum, frame):
    global running
    running = False


def init_sensor():
    try:
        bus = smbus2.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}", file=sys.stderr)
        return None

    try:
        bus.write_byte(I2C_ADDR, BH1750_POWER_ON)
        time.sleep(0.01)
        bus.write_byte(I2C_ADDR, BH1750_RESET)
        time.sleep(0.01)
        bus.write_byte(I2C_ADDR, BH1750_CONTINUOUS_HIGH_RES_MODE)
        time.sleep(CONVERSION_DELAY)
    except OSError as e:
        print(f"Warning: BH1750 not detected at 0x{I2C_ADDR:02X}: {e}", file=sys.stderr)
        try:
            bus.close()
        except Exception:
            pass
        return None

    return bus


def read_light_lux():
    try:
        data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 2)
        raw = (data[0] << 8) | data[1]
        lux = raw / 1.2
        return lux
    except OSError as e:
        print(f"Warning: I2C read error: {e}", file=sys.stderr)
        return None


def lux_to_contrast(lux):
    return max(0, min(255, int(lux)))


def init_display():
    try:
        serial = i2c(port=I2C_BUS, address=OLED_ADDR)
        dev = ssd1306(serial)
        dev.clear()
        return dev
    except Exception as e:
        print(f"Error: cannot initialize SSD1306 at 0x{OLED_ADDR:02X}: {e}", file=sys.stderr)
        return None


def cleanup():
    global display, bus
    if display is not None:
        try:
            display.clear()
        except Exception:
            pass
    if bus is not None:
        try:
            bus.close()
        except Exception:
            pass


def main():
    global bus, display, running

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    bus = init_sensor()
    if bus is None:
        cleanup()
        sys.exit(1)

    display = init_display()
    if display is None:
        cleanup()
        sys.exit(1)

    current_contrast = 0

    try:
        while running:
            lux = read_light_lux()
            if lux is not None:
                current_contrast = lux_to_contrast(lux)
                print(f"Light: {lux:.2f} lux -> Contrast: {current_contrast}")
                try:
                    display.contrast(current_contrast)
                except Exception as e:
                    print(f"Warning: display contrast update failed: {e}", file=sys.stderr)
            else:
                print("Sensor read failed; retaining previous contrast.", file=sys.stderr)

            time.sleep(UPDATE_INTERVAL)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

