import signal
import sys
import time
import spidev
import board
import busio
import adafruit_ssd1306

# --- Configuration -----------------------------------------------------------
SPI_BUS = 0
SPI_CS = 0          # CE0 on GPIO8 (BCM)
SPI_SPEED_HZ = 50000
I2C_BUS = 1
OLED_WIDTH = 128
OLED_HEIGHT = 64
SAMPLE_INTERVAL_S = 1.0

# --- Globals for cleanup -----------------------------------------------------
spi = None
i2c = None
oled = None
running = True


def cleanup():
    """Release hardware resources on exit."""
    global spi, i2c, oled
    if oled is not None:
        try:
            oled.fill(0)
            oled.show()
        except Exception:
            pass
    if spi is not None:
        try:
            spi.close()
        except Exception:
            pass
    if i2c is not None:
        try:
            i2c.deinit()
        except Exception:
            pass


def handle_signal(signum, frame):
    """Graceful shutdown on SIGINT / SIGTERM."""
    global running
    running = False


def init_spi():
    """Initialize SPI bus 0, CS0 at 50 kHz."""
    s = spidev.SpiDev()
    try:
        s.open(SPI_BUS, SPI_CS)
    except Exception as exc:
        print(f"[ERROR] Failed to open SPI bus {SPI_BUS}, CS{SPI_CS}: {exc}", file=sys.stderr)
        return None
    s.max_speed_hz = SPI_SPEED_HZ
    s.mode = 0
    return s


def init_i2c():
    """Initialize I2C bus 1."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as exc:
        print(f"[ERROR] Failed to initialize I2C bus {I2C_BUS}: {exc}", file=sys.stderr)
        return None


def init_oled(i2c_link):
    """Initialize SSD1306 OLED display."""
    try:
        return adafruit_ssd1306.SSD1306_I2C(
            OLED_WIDTH, OLED_HEIGHT, i2c_link, addr=0x3C
        )
    except Exception as exc:
        print(f"[ERROR] Failed to initialize SSD1306 OLED: {exc}", file=sys.stderr)
        return None


def read_adc_channel(spi_link, channel):
    """Read a single-ended channel (0-3) from the MCP3008.

    Returns the 10-bit value (0-1023) or None on error.
    """
    if not 0 <= channel <= 3:
        print(f"[WARN] Invalid ADC channel {channel}; must be 0-3.", file=sys.stderr)
        return None
    try:
        # MCP3008 single-ended read: start bit, config byte, padding
        resp = spi_link.xfer2([0x01, (0x08 | channel) << 4, 0x00])
        return ((resp[1] & 0x03) << 8) | resp[2]
    except Exception as exc:
        print(f"[ERROR] SPI read failed on channel {channel}: {exc}", file=sys.stderr)
        return None


def update_oled(display, voltages):
    """Render four channel voltages (0-3.3 V) on the OLED."""
    try:
        display.fill(0)
        for i, v in enumerate(voltages):
            if v is None:
                text = "CH{} ERR".format(i)
            else:
                text = "CH{}: {:.2f}V".format(i, v / 1023.0 * 3.3)
            display.text(text, 0, i * 10, 1)
        display.show()
    except Exception as exc:
        print(f"[ERROR] OLED update failed: {exc}", file=sys.stderr)


def main():
    global spi, i2c, oled

    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    spi = init_spi()
    if spi is None:
        cleanup()
        sys.exit(1)

    i2c = init_i2c()
    if i2c is None:
        cleanup()
        sys.exit(1)

    oled = init_oled(i2c)
    if oled is None:
        cleanup()
        sys.exit(1)

    try:
        while running:
            voltages = []
            for ch in range(4):
                raw = read_adc_channel(spi, ch)
                if raw is not None:
                    voltages.append(raw / 1023.0 * 3.3)
                else:
                    voltages.append(None)

            update_oled(oled, voltages)

            # Sleep in small increments so signals are caught promptly
            elapsed = 0.0
            while running and elapsed < SAMPLE_INTERVAL_S:
                time.sleep(0.1)
                elapsed += 0.1

    except Exception as exc:
        print(f"[ERROR] Unexpected error in main loop: {exc}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

