# Elder Care Monitor for Raspberry Pi 4 Model B
# Monitors temperature and humidity using a DHT22 sensor and displays data on an OLED display.
# Alerts the caregiver via a buzzer if temperature or humidity thresholds are exceeded.

import time
import logging
import signal
import sys
import board
import busio
import digitalio
from adafruit_ssd1306 import SSD1306_I2C
from adafruit_dht import DHT22
from gpiozero import Buzzer

# Configuration
DHT_PIN = board.D4
BUZZER_PIN = 17
TEMPERATURE_THRESHOLD_HIGH = 30.0
TEMPERATURE_THRESHOLD_LOW = 15.0
HUMIDITY_THRESHOLD_HIGH = 80.0
OLED_WIDTH = 128
OLED_HEIGHT = 64
LOG_FILE = "elder_care_monitor.log"
READ_INTERVAL = 5
MAX_RETRIES = 3
RETRY_DELAY = 1
BUZZER_ON_TIME = 0.2
BUZZER_OFF_TIME = 0.3
BUZZER_REPEAT_INTERVAL = 2

# Logging setup
logging.basicConfig(
    filename=LOG_FILE,
    level=logging.ERROR,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

# Global state for cleanup
running = True
oled = None
buzzer = None
dht_device = None

def signal_handler(sig, frame):
    global running
    running = False

def cleanup():
    global oled, buzzer, dht_device
    if buzzer is not None:
        buzzer.off()
    if oled is not None:
        oled.fill(0)
        oled.show()
    if dht_device is not None:
        try:
            dht_device.exit()
        except Exception:
            pass
    logging.info("Cleanup complete.")

def init_oled():
    try:
        i2c = busio.I2C(board.SCL, board.SDA)
        display = SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, i2c)
        display.fill(0)
        display.text("Initializing...", 0, 0, 1)
        display.show()
        return display
    except Exception as e:
        logging.error(f"OLED initialization failed: {e}")
        return None

def init_buzzer():
    try:
        return Buzzer(BUZZER_PIN)
    except Exception as e:
        logging.error(f"Buzzer initialization failed: {e}")
        return None

def init_dht22():
    try:
        return DHT22(DHT_PIN)
    except Exception as e:
        logging.error(f"DHT22 initialization failed: {e}")
        return None

def read_dht22(device):
    for attempt in range(MAX_RETRIES):
        try:
            temperature = device.temperature
            humidity = device.humidity
            if temperature is not None and humidity is not None:
                return temperature, humidity
        except RuntimeError as e:
            logging.error(f"DHT22 read error (attempt {attempt + 1}/{MAX_RETRIES}): {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT22 error (attempt {attempt + 1}/{MAX_RETRIES}): {e}")
        if attempt < MAX_RETRIES - 1:
            time.sleep(RETRY_DELAY)
    return None, None

def display_data(display, temperature, humidity):
    if display is None:
        return
    try:
        display.fill(0)
        timestamp = time.strftime("%H:%M:%S")
        display.text(f"Temp: {temperature:.1f} C", 0, 0, 1)
        display.text(f"Humidity: {humidity:.1f} %", 0, 16, 1)
        display.text(f"Time: {timestamp}", 0, 32, 1)
        display.show()
    except Exception as e:
        logging.error(f"OLED display update failed: {e}")

def check_thresholds(temperature, humidity):
    if temperature is None or humidity is None:
        return False
    if temperature > TEMPERATURE_THRESHOLD_HIGH:
        return True
    if temperature < TEMPERATURE_THRESHOLD_LOW:
        return True
    if humidity > HUMIDITY_THRESHOLD_HIGH:
        return True
    return False

def activate_buzzer(buzzer):
    if buzzer is None:
