            buzzer.off()
            time.sleep(BUZZER_OFF_TIME)
            if not check_thresholds(dht_device.temperature, dht_device.humidity):
                break
            time.sleep(BUZZER_REPEAT_INTERVAL)
    except Exception as e:
        logging.error(f"Buzzer activation failed: {e}")

def main():
    global oled, buzzer, dht_device
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    oled = init_oled()
    buzzer = init_buzzer()
    dht_device = init_dht22()
    if oled is None or buzzer is None or dht_device is None:
