import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO can only run on a Raspberry Pi.")
    sys.exit(1)

TRIGGER_PIN = 17
ECHO_PIN = 18
SPEED_OF_SOUND_CM_PER_S = 34300.0
MIN_DISTANCE_CM = 2.0
MAX_DISTANCE_CM = 400.0
MIN_WATER_LEVEL_CM = 0.0
MAX_WATER_LEVEL_CM = 50.0
TRIGGER_PULSE_S = 10e-6
MAX_ECHO_WAIT_S = 0.03
SETTLE_DELAY_S = 0.2
LOOP_DELAY_S = 2.0

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(TRIGGER_PIN, GPIO.OUT, initial=GPIO.LOW)
    GPIO.setup(ECHO_PIN, GPIO.IN)
    time.sleep(SETTLE_DELAY_S)


def _measure_distance():
    GPIO.output(TRIGGER_PIN, GPIO.HIGH)
    time.sleep(TRIGGER_PULSE_S)
    GPIO.output(TRIGGER_PIN, GPIO.LOW)

    deadline = time.monotonic() + MAX_ECHO_WAIT_S
    while GPIO.input(ECHO_PIN) == GPIO.LOW:
        if time.monotonic() > deadline:
            return None
    pulse_start = time.monotonic()

    deadline = time.monotonic() + MAX_ECHO_WAIT_S
    while GPIO.input(ECHO_PIN) == GPIO.HIGH:
        if time.monotonic() > deadline:
            return None
    pulse_end = time.monotonic()

    elapsed = pulse_end - pulse_start
    distance = (elapsed * SPEED_OF_SOUND_CM_PER_S) / 2.0
    if distance < MIN_DISTANCE_CM or distance > MAX_DISTANCE_CM:
        return None
    return distance


def _distance_to_water_level(distance_cm):
    if distance_cm is None:
        return None
    water_level = MAX_WATER_LEVEL_CM - distance_cm
    return max(MIN_WATER_LEVEL_CM, min(water_level, MAX_WATER_LEVEL_CM))


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _setup_gpio()
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        _cleanup()
        return

    try:
        while _running:
            try:
                distance = _measure_distance()
            except Exception as e:
                print(f"Error measuring distance: {e}")
                distance = None

            water_level = _distance_to_water_level(distance)

            if distance is not None and water_level is not None:
                print(f"Distance: {distance:.2f} cm, Water Level: {water_level:.2f} cm")
            elif distance is not None:
                print(f"Distance: {distance:.2f} cm, Water Level: invalid")
            else:
                print("Error: Invalid distance reading.")

            for _ in range(int(LOOP_DELAY_S / 0.05)):
                if not _running:
                    break
                time.sleep(0.05)
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

