import smbus
import time
import signal
import sys

I2C_BUS = 1
PCF8574_ADDR = 0x20
NUM_SENSORS = 8
POLL_INTERVAL = 0.1
RETRY_DELAY = 1.0

running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_sensor(bus, addr, pin):
    """Read a single bit from the PCF8574 port register and return True if LOW."""
    try:
        port = bus.read_byte_data(addr, 0x00)
        return (port & (1 << pin)) == 0
    except OSError as e:
        print(f"I2C error reading sensor {pin}: {e}")
        return None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = smbus.SMBus(I2C_BUS)
    except OSError as e:
        print(f"Failed to open I2C bus {I2C_BUS}: {e}")
        sys.exit(1)

    try:
        while running:
            for i in range(NUM_SENSORS):
                if not running:
                    break
                state = read_sensor(bus, PCF8574_ADDR, i)
                if state is None:
                    print(f"Sensor {i}: error, retrying in {RETRY_DELAY}s")
                    time.sleep(RETRY_DELAY)
                    break
                if state:
                    print(f"Obstacle detected by sensor {i}")
            if running:
                time.sleep(POLL_INTERVAL)
    finally:
        bus.close()
        print("I2C bus closed. Exiting.")

if __name__ == "__main__":
    main()

