#!/usr/bin/env python3
"""
Clean Energy Monitoring System Simulator for Raspberry Pi 4

Simulates light and temperature sensors on GPIO17 and GPIO4, respectively.
Logs data every 5 seconds with warnings and critical alerts.
"""

import time
import datetime
import random
import subprocess
import sys
import signal

# Constants
LOW_LIGHT_THRESHOLD = 300
HIGH_TEMP_THRESHOLD = 35
HIGH_PI_TEMP_THRESHOLD = 75
LIGHT_SENSOR_PIN = 17
TEMP_SENSOR_PIN = 4
LOOP_INTERVAL = 5  # seconds
VCGENCMD_TIMEOUT = 5  # seconds

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def get_simulated_light_level():
    """Simulate light level (lux) based on current time."""
    now = datetime.datetime.now()
    hour = now.hour
    if 6 <= hour < 18:
        return random.randint(600, 1000)
    else:
        return random.randint(100, 300)


def get_simulated_temperature():
    """Simulate temperature (°C)."""
    return random.randint(20, 30)


def get_simulated_voltage(light_level):
    """Simulate battery voltage (V) based on light level."""
    if light_level > 300:
        return round(random.uniform(11.5, 12.5), 2)
    else:
        return round(random.uniform(10.0, 11.0), 2)


def get_simulated_current(light_level):
    """Simulate battery current (A) based on light level."""
    if light_level > 300:
        return round(random.uniform(1.5, 2.5), 2)
    else:
        return round(random.uniform(0.5, 1.0), 2)


def get_pi_temperature():
    """Read Pi temperature via vcgencmd.

    Returns:
        float: Temperature in °C, or None on failure.
    """
    try:
        result = subprocess.run(
            ['vcgencmd', 'measure_temp'],
            capture_output=True,
            text=True,
            timeout=VCGENCMD_TIMEOUT,
            check=True
        )
        # Expected output: temp=42.8'C
        temp_str = result.stdout.strip()
        if not temp_str.startswith('temp=') or not temp_str.endswith("'C"):
            print(f"WARNING: Unexpected vcgencmd output: {temp_str}")
            return None
        return float(temp_str.split('=')[1].split("'C")[0])
    except subprocess.CalledProcessError as e:
        print(f"WARNING: vcgencmd failed (exit {e.returncode}): {e.stderr.strip()}")
        return None
    except subprocess.TimeoutExpired:
        print("WARNING: vcgencmd timed out")
        return None
    except (ValueError, IndexError) as e:
        print(f"WARNING: Could not parse vcgencmd output: {e}")
        return None
    except FileNotFoundError:
        print("WARNING: vcgencmd not found on this system")
        return None
    except Exception as e:
        print(f"WARNING: Unexpected error reading Pi temperature: {e}")
        return None


def log_data(light_level, temperature, voltage, current, pi_temp):
    """Log sensor data and warnings to console."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - Light: {light_level} lux, Temperature: {temperature} °C, "
          f"Voltage: {voltage} V, Current: {current} A, Pi Temp: {pi_temp if pi_temp is not None else 'N/A'} °C")

    if light_level < LOW_LIGHT_THRESHOLD:
        print("WARNING: Low light level detected!")

    if temperature > HIGH_TEMP_THRESHOLD:
        print("WARNING: High temperature detected! Cooling system activated.")

    if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
        print("CRITICAL: High Pi temperature detected! System shutdown simulated.")


def main():
    """Main loop for the clean energy monitoring system."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    print("Clean Energy Monitoring System Simulator started. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                light_level = get_simulated_light_level()
            except Exception as e:
                print(f"ERROR: Sensor read error - Light: {e}")
                light_level = 0

            try:
                temperature = get_simulated_temperature()
            except Exception as e:
                print(f"ERROR: Sensor read error - Temperature: {e}")
                temperature = 0

            try:
                voltage = get_simulated_voltage(light_level)
            except Exception as e:
                print(f"ERROR: Sensor read error - Voltage: {e}")
                voltage = 0.0

            try:
                current = get_simulated_current(light_level)
            except Exception as e:
                print(f"ERROR: Sensor read error - Current: {e}")
                current = 0.0

            pi_temp = get_pi_temperature()

            log_data(light_level, temperature, voltage, current, pi_temp)

            # Sleep in small increments to allow responsive shutdown
            slept = 0
            while _running and slept < LOOP_INTERVAL:
                time.sleep(0.1)
                slept += 0.1

    except Exception as e:
        print(f"ERROR: Unexpected error in main loop: {e}")
    finally:
        print("\nProgram terminated gracefully.")


if __name__ == "__main__":
    main()

