        print(f"WARNING: Unexpected error reading Pi temperature: {e}")
        return None


def log_data(light_level, temperature, voltage, current, pi_temp):
    """Log sensor data and warnings to console."""
    timestamp = datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    print(f"{timestamp} - Light: {light_level} lux, Temperature: {temperature} °C, "
          f"Voltage: {voltage} V, Current: {current} A, Pi Temp: {pi_temp if pi_temp is not None else 'N/A'} °C")

    if light_level < LOW_LIGHT_THRESHOLD:
        print("WARNING: Low light level detected!")

    if temperature > HIGH_TEMP_THRESHOLD:
        print("WARNING: High temperature detected! Cooling system activated.")

    if pi_temp is not None and pi_temp > HIGH_PI_TEMP_THRESHOLD:
        print("CRITICAL: High Pi temperature detected! System shutdown simulated.")


def main():
    """Main loop for the clean energy monitoring system."""
    global _running

    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    print("Clean Energy Monitoring System Simulator started. Press Ctrl+C to stop.")

    try:
        while _running:
            try:
                light_level = get_simulated_light_level()
            except Exception as e:
                print(f"ERROR: Sensor read error - Light: {e}")
                light_level = 0

            try:
                temperature = get_simulated_temperature()
            except Exception as e:
                print(f"ERROR: Sensor read error - Temperature: {e}")
                temperature = 0

            try:
                voltage = get_simulated_voltage(light_level)
            except Exception as e:
                print(f"ERROR: Sensor read error - Voltage: {e}")
                voltage = 0.0

            try:
                current = get_simulated_current(light_level)
            except Exception as e:
                print(f"ERROR: Sensor read error - Current: {e}")
                current = 0.0

            pi_temp = get_pi_temperature()

            log_data(light_level, temperature, voltage, current, pi_temp)

            # Sleep in small increments to allow responsive shutdown
            slept = 0
            while _running and slept < LOOP_INTERVAL:
                time.sleep(0.1)
                slept += 0.1

    except Exception as e:
        print(f"ERROR: Unexpected error in main loop: {e}")
    finally:
        print("\nProgram terminated gracefully.")


if __name__ == "__main__":
    main()

