import paho.mqtt.client as mqtt
import time
import random
import json
import threading
import sys

BROKER = "test.mosquitto.org"
PORT = 1883
KEEPALIVE = 60
TOPIC = "classroom/temperature"
NUM_MESSAGES = 5
RETRY_COUNT = 3
RETRY_DELAY = 2


def on_connect(client, userdata, flags, reason_code, properties):
    if reason_code == 0:
        userdata['connected'].set()
    else:
        userdata['connected'].set()


def on_publish(client, userdata, mid, reason_code, properties):
    userdata['published'].add(mid)


def simulate_temperature_reading():
    return round(random.uniform(19.00, 26.00), 2)


def main():
    userdata = {'connected': threading.Event(), 'published': set()}
    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        userdata=userdata
    )
    client.on_connect = on_connect
    client.on_publish = on_publish

    for attempt in range(1, RETRY_COUNT + 1):
        try:
            client.connect(BROKER, PORT, KEEPALIVE)
            break
        except Exception as e:
            print(f"Connection attempt {attempt}/{RETRY_COUNT} failed: {e}")
            if attempt < RETRY_COUNT:
                time.sleep(RETRY_DELAY)

    if not userdata['connected'].wait(timeout=10):
        print("Failed to connect to broker within timeout.")
        client.disconnect()
        sys.exit(1)

    successful = 0
    try:
        for i in range(NUM_MESSAGES):
            temperature = simulate_temperature_reading()
            payload = json.dumps({"index": i, "temperature": temperature})
            result = client.publish(TOPIC, payload, qos=1)
            userdata['published'].add(result.mid)
            time.sleep(1)

            while len(userdata['published']) < (i + 1):
                time.sleep(0.1)

            if result.rc == mqtt.MQTT_ERR_SUCCESS:
                successful += 1
            else:
                print(f"Publish failed for message {i}: rc={result.rc}")
    except Exception as e:
        print(f"Error during publishing: {e}")
    finally:
        client.disconnect()

    print(f"Successfully published {successful}/{NUM_MESSAGES} messages.")
    sys.exit(0 if successful == NUM_MESSAGES else 1)


if __name__ == "__main__":
    main()

