import csv
import os
import signal
import sys
import time
from datetime import datetime

import board
import adafruit_dht

DATA_DIR = "/home/pi/data"
CSV_PATH = os.path.join(DATA_DIR, "sensor_data.csv")
ERROR_LOG_PATH = os.path.join(DATA_DIR, "error.log")
DHT_PIN = board.D4

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _ensure_dir(path):
    try:
        os.makedirs(path, exist_ok=True)
    except OSError as exc:
        print(f"Error: cannot create directory {path}: {exc}", file=sys.stderr)
        sys.exit(1)


def _log_error(message):
    ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    line = f"{ts} - {message}\n"
    try:
        with open(ERROR_LOG_PATH, "a", encoding="utf-8") as fh:
            fh.write(line)
    except OSError as exc:
        print(f"Error: cannot write to error log: {exc}", file=sys.stderr)


def _write_csv_row(timestamp, temperature):
    try:
        with open(CSV_PATH, "a", newline="", encoding="utf-8") as fh:
            writer = csv.writer(fh)
            writer.writerow([timestamp, f"{temperature:.2f}"])
    except OSError as exc:
        _log_error(f"Failed to write CSV row: {exc}")


def main():
    global _running

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    _ensure_dir(DATA_DIR)

    try:
        sensor = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    except Exception as exc:
        _log_error(f"Failed to initialize DHT22 on GPIO4: {exc}")
        sys.exit(1)

    try:
        while _running:
            try:
                temperature = sensor.temperature
                if temperature is None:
                    raise RuntimeError("Sensor returned None")
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                _write_csv_row(ts, temperature)
                print(f"Logged: {ts}  T={temperature:.2f} °C")
            except RuntimeError as exc:
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                _log_error(f"DHT22 read error: {exc}")
            except OSError as exc:
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                _log_error(f"OS error reading DHT22: {exc}")
            except Exception as exc:
                ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                _log_error(f"Unexpected error: {exc}")

            for _ in range(5):
                if not _running:
                    break
                time.sleep(1)
    finally:
        try:
            sensor.exit()
        except Exception:
            pass
        print("Shutdown complete.")


if __name__ == "__main__":
    main()

