import time
import logging
import signal
import smbus2

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    DHT20_I2C_ADDR = 0x61
    DHT20_STATUS_REG = 0x71
    DHT20_MEASURE_REG = 0x71
    DHT20_DATA_REG = 0x71
    DHT20_STATUS_MASK = 0x18
    DHT20_STATUS_READY = 0x00
    DHT20_MEASURE_CMD = 0x01
    DHT20_RETRY_DELAY = 2.0
    DHT20_MAX_RETRIES = 5
    DHT20_MEASURE_TIMEOUT = 0.1
    DHT20_POWER_STABILIZE_DELAY = 0.5

    def __init__(self, i2c_bus=1):
        self.i2c_bus_number = i2c_bus
        self.bus = None
        self._closed = False
        try:
            self.bus = smbus2.SMBus(self.i2c_bus_number)
            time.sleep(self.DHT20_POWER_STABILIZE_DELAY)
            if not self._read_status():
                logger.error("DHT20 sensor not detected or not ready.")
                self.close()
                raise IOError("DHT20 sensor not detected or not ready.")
        except Exception as e:
            logger.error(f"Failed to initialize I2C bus {self.i2c_bus_number}: {e}")
            self.close()
            raise

    def _read_status(self):
        try:
            status = self.bus.read_byte_data(self.DHT20_I2C_ADDR, self.DHT20_STATUS_REG)
            if (status & self.DHT20_STATUS_MASK) != self.DHT20_STATUS_READY:
                logger.error(f"DHT20 status check failed. Status: 0x{status:02X}")
                return False
            return True
        except Exception as e:
            logger.error(f"Error reading DHT20 status: {e}")
            return False

    def _read_raw_data(self):
        try:
            data = self.bus.read_i2c_block_data(self.DHT20_I2C_ADDR, self.DHT20_DATA_REG, 7)
            return data
        except Exception as e:
            logger.error(f"Error reading DHT20 data: {e}")
            return None

    def _calculate_crc8(self, data):
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def _process_data(self, data):
        if data is None or len(data) < 7:
            logger.error("Incomplete data received from DHT20.")
            return None, None, True

        humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
        temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

        humidity = (humidity_raw / 1048576.0) * 100.0
        temperature = (temperature_raw / 1048576.0) * 200.0 - 50.0

        calculated_crc = self._calculate_crc8(data[:6])
        received_crc = data[6]

        if calculated_crc != received_crc:
            logger.warning(f"CRC error: calculated 0x{calculated_crc:02X}, received 0x{received_crc:02X}")
            return temperature, humidity, True

        return temperature, humidity, False

    def read(self):
        for attempt in range(self.DHT20_MAX_RETRIES):
            if not self._read_status():
                time.sleep(self.DHT20_RETRY_DELAY)
                continue

            try:
                self.bus.write_byte_data(self.DHT20_I2C_ADDR, self.DHT20_MEASURE_REG, self.DHT20_MEASURE_CMD)
            except Exception as e:
                logger.error(f"Error sending measurement command: {e}")
                time.sleep(self.DHT20_RETRY_DELAY)
                continue

            start_time = time.time()
            while time.time() - start_time < self.DHT20_MEASURE_TIMEOUT:
                if not self._read_status():
                    break
                time.sleep(0.005)

            data = self._read_raw_data()
            if data is not None:
                return self._process_data(data)

            time.sleep(self.DHT20_RETRY_DELAY)

        logger.error("Failed to read data from DHT20 after multiple retries.")
        return None, None, True

    def close(self):
        if self.bus is not None and not self._closed:
            try:
                self.bus.close()
            except Exception as e:
                logger.error(f"Error closing I2C bus: {e}")
            finally:
                self._closed = True

    def __del__(self):
        self.close()


def main():
    sensor = None
    try:
        sensor = DHT20(i2c_bus=1)
        temperature, humidity, crc_error = sensor.read()
        if temperature is not None and humidity is not None:
            print(f"Temperature: {temperature:.2f} °C")
            print(f"Humidity: {humidity:.2f} %")
            print(f"CRC Error: {crc_error}")
        else:
            print("Failed to read sensor data.")
    except Exception as e:
        logger.error(f"An error occurred: {e}")
    finally:
        if sensor is not None:
            sensor.close()


if __name__ == "__main__":
    main()

