import asyncio
import json
import logging
import logging.handlers
import signal
import sys
import time
from typing import Dict, Optional, Tuple

import RPi.GPIO as GPIO

DEFAULT_CONFIG = {
    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"name": "Grow Light", "system_code": "10101", "unit_code": "1"},
        {"name": "Vent Fan", "system_code": "10101", "unit_code": "2"},
        {"name": "Heater", "system_code": "10101", "unit_code": "3"},
    ],
}


class GreenhouseController:
    def __init__(self, config: Dict):
        self.config = config
        self.outlet_configurations = config["outlet_configurations"]
        self.dht22_read_interval = config["dht22_read_interval"]
        self.gpio_transmitter_pin = config["gpio_transmitter_pin"]
        self.gpio_dht22_pin = config["gpio_dht22_pin"]
        self.log_file = config["log_file"]
        self.logger = self._setup_logging()
        self._shutdown_event = asyncio.Event()
        self._running = True

    def _setup_logging(self) -> logging.Logger:
        logger = logging.getLogger("greenhouse")
        logger.setLevel(logging.INFO)
        handler = logging.handlers.RotatingFileHandler(
            self.log_file, maxBytes=1024 * 1024, backupCount=5
        )
        formatter = logging.Formatter(
            "%(asctime)s - %(name)s - %(levelname)s - %(message)s"
        )
        handler.setFormatter(formatter)
        logger.addHandler(handler)
        return logger

    def load_config(self, config_file: str = "greenhouse_config.json") -> Dict:
        try:
            with open(config_file, "r") as f:
                config = json.load(f)
            self.logger.info("Configuration loaded from %s", config_file)
            return config
        except FileNotFoundError:
            self.logger.warning(
                "Configuration file %s not found. Using default configuration.",
                config_file,
            )
            return DEFAULT_CONFIG.copy()
        except json.JSONDecodeError as e:
