import smbus2
import time
import logging
import signal
import sys

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class DHT20:
    DHT20_I2C_ADDR = 0x61
    STATUS_REG = 0x80
    MEASURE_REG = 0xAC
    MEASURE_CMD = 0x33
    CRC_POLY = 0x31
    CRC_INIT = 0xFF

    def __init__(self, bus_num=1):
        self.bus_num = bus_num
        self.bus = None
        try:
            self.bus = smbus2.SMBus(self.bus_num)
            time.sleep(0.05)
            status = self.bus.read_byte_data(self.DHT20_I2C_ADDR, self.STATUS_REG)
            if status != 0x00:
                logging.error(f"DHT20 not detected or not ready (status=0x{status:02X})")
                self.bus.close()
                self.bus = None
            else:
                logging.info("DHT20 initialized successfully")
        except Exception as e:
            logging.error(f"Failed to initialize DHT20 on bus {self.bus_num}: {e}")
            self.bus = None

    def _crc8(self, data):
        crc = self.CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLY) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc

    def measure(self):
        if self.bus is None:
            logging.error("DHT20 not initialized")
            return None, None, True

        try:
            self.bus.write_byte_data(self.DHT20_I2C_ADDR, self.MEASURE_REG, self.MEASURE_CMD)
            time.sleep(0.08)
            data = self.bus.read_i2c_block_data(self.DHT20_I2C_ADDR, 0x00, 7)
            crc_error = self._crc8(data[:6]) != data[6]
            if crc_error:
                logging.warning("CRC error detected")
            humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
            temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF
            temperature = temperature_raw * 200.0 / 1048576.0 - 50.0
            humidity = humidity_raw * 100.0 / 1048576.0
            return temperature, humidity, crc_error
        except Exception as e:
            logging.error(f"Error during measurement: {e}")
            return None, None, True

    def close(self):
        if self.bus is not None:
            try:
                self.bus.close()
            except Exception:
                pass
            self.bus = None

def main():
    sensor = DHT20(bus_num=1)
    if sensor.bus is None:
        sys.exit(1)

    def signal_handler(sig, frame):
        logging.info("Exiting gracefully...")
        sensor.close()
        sys.exit(0)

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    temp, hum, err = sensor.measure()
    if err:
        print("Measurement failed")
    else:
        print(f"Temperature: {temp:.2f} C, Humidity: {hum:.2f} %")
    sensor.close()

if __name__ == "__main__":
    main()

