import time
import logging
import signal
import sys
import board
import busio
import adafruit_bmp280

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

SAMPLE_COUNT = 100
DISCARD_PERCENT = 0.25
SEALEVEL_PRESSURE_HPA = 1013.25
I2C_ADDRESS = 0x76

_running = True


def _signal_handler(signum, frame):
    global _running
    _running = False


def _trimmed_mean(samples, discard_percent):
    if not samples:
        return None
    n = len(samples)
    if n == 1:
        return samples[0]
    discard = int(n * discard_percent)
    if discard == 0:
        discard = 1
    sorted_samples = sorted(samples)
    trimmed = sorted_samples[discard : n - discard]
    return sum(trimmed) / len(trimmed)


def get_altitude_baseline(i2c, address, sample_count, discard_percent):
    samples = []
    for i in range(sample_count):
        try:
            sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=address)
            sensor.sea_level_pressure = SEALEVEL_PRESSURE_HPA
            samples.append(sensor.pressure)
        except (ValueError, OSError, RuntimeError) as e:
            logging.error("Error reading pressure sample %d: %s", i, e)
        time.sleep(0.1)
    if not samples:
        raise RuntimeError("No pressure samples collected")
    return _trimmed_mean(samples, discard_percent)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        i2c = busio.I2C(board.SCL, board.SDA)
    except (ValueError, RuntimeError, OSError) as e:
        logging.error("Failed to initialize I2C bus: %s", e)
        sys.exit(1)

    try:
        baseline = get_altitude_baseline(
            i2c, I2C_ADDRESS, SAMPLE_COUNT, DISCARD_PERCENT
        )
        logging.info("Altitude baseline established: %.2f hPa", baseline)
    except (ValueError, OSError, RuntimeError) as e:
        logging.error("Failed to establish altitude baseline: %s", e)
        baseline = SEALEVEL_PRESSURE_HPA
        logging.warning("Falling back to default sea-level pressure: %.2f hPa", baseline)

    try:
        sensor = adafruit_bmp280.Adafruit_BMP280_I2C(i2c, address=I2C_ADDRESS)
        sensor.sea_level_pressure = SEALEVEL_PRESSURE_HPA
    except (ValueError, OSError, RuntimeError) as e:
        logging.error("Failed to initialize BMP280 sensor: %s", e)
        sys.exit(1)

    try:
        while _running:
            try:
