import csv
import signal
import sys
import time
from datetime import datetime

import serial

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1.0
LOG_FILE = 'temperature_log.csv'

_running = True


def _handle_signal(signum, frame):
    global _running
    _running = False


def celsius_to_fahrenheit(celsius):
    return (celsius * 9.0 / 5.0) + 32.0


def log_temperature(celsius, fahrenheit):
    timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    try:
        with open(LOG_FILE, 'a', newline='') as fh:
            writer = csv.writer(fh)
            writer.writerow([timestamp, f'{celsius:.2f}', f'{fahrenheit:.2f}'])
    except OSError as exc:
        print(f'Error writing to log file: {exc}', file=sys.stderr)


def main():
    global _running

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        ser = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f'Error opening serial port {SERIAL_PORT}: {exc}', file=sys.stderr)
        sys.exit(1)

    try:
        if not hasattr(ser, 'in_waiting') or ser.in_waiting == 0:
            time.sleep(0.5)

        while _running:
            try:
                raw = ser.readline()
            except serial.SerialException as exc:
                print(f'Serial read error: {exc}', file=sys.stderr)
                break

            if not raw:
                continue

            line = raw.decode('ascii', errors='replace').strip()
            if not line:
                continue

            try:
                celsius = float(line)
            except ValueError:
                print(f'Invalid data received (not numeric): {line!r}', file=sys.stderr)
                continue

            fahrenheit = celsius_to_fahrenheit(celsius)
            print(f'Temperature: {celsius:.2f} C / {fahrenheit:.2f} F')
            log_temperature(celsius, fahrenheit)

            time.sleep(0.5)
    finally:
        try:
            ser.close()
        except Exception:
            pass


if __name__ == '__main__':
    main()

