import json
import time
import random
import signal
import sys
import urllib.request
import urllib.error
import logging
import threading

try:
    import board
    import adafruit_dht
except ImportError:
    board = None
    adafruit_dht = None

CONFIG_FILE = "config.json"
logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
logger = logging.getLogger(__name__)

running = True
sensor = None
dht_pin = None

def load_config():
    try:
        with open(CONFIG_FILE, "r") as f:
            return json.load(f)
    except FileNotFoundError:
        logger.warning("Config file not found; using defaults.")
    except json.JSONDecodeError:
        logger.warning("Config file is invalid; using defaults.")
    return {"webhook_url": "https://example.com/webhook", "sensor_pin": 4}

def signal_handler(signum, frame):
    global running
    logger.info("Signal %s received, shutting down...", signum)
    running = False

def read_sensor_data():
    global sensor, dht_pin
    if adafruit_dht is None or board is None:
        logger.warning("adafruit_dht/board not installed; simulating data.")
        return random.uniform(20, 30), random.uniform(60, 80)
    try:
        if sensor is None:
            dht_pin = getattr(board, f"D{load_config()['sensor_pin']}")
            sensor = adafruit_dht.DHT22(dht_pin, use_pulseio=False)
        temperature = sensor.temperature
        humidity = sensor.humidity
        if temperature is None or humidity is None:
            raise RuntimeError("Sensor returned None")
        return temperature, humidity
    except Exception as e:
        logger.warning("Sensor read failed: %s; simulating data.", e)
        return random.uniform(20, 30), random.uniform(60, 80)

def validate_data(temperature, humidity):
    if not (-40 <= temperature <= 80):
        logger.warning("Temperature out of range: %.2f", temperature)
        return False
    if not (0 <= humidity <= 100):
        logger.warning("Humidity out of range: %.2f", humidity)
        return False
    return True

def calculate_moving_average(data, window_size=5):
    if not data:
        return 0.0
    if len(data) < window_size:
        return sum(data) / len(data)
    return sum(data[-window_size:]) / window_size

def send_webhook(data):
    config = load_config()
    url = config.get("webhook_url")
    if not url:
        logger.error("Webhook URL not configured.")
        return False
    payload = json.dumps(data).encode("utf-8")
    req = urllib.request.Request(url, data=payload, headers={"Content-Type": "application/json"}, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            if 200 <= resp.status < 300:
                logger.info("Webhook sent successfully.")
                return True
            logger.error("Webhook failed with status %s", resp.status)
            return False
    except urllib.error.URLError as e:
        logger.error("Webhook network error: %s", e)
        return False
    except Exception as e:
        logger.error("Webhook error: %s", e)
        return False

def retry_webhook(data, max_retries=3, backoff_intervals=[1, 3, 9]):
    retries = 0
    for interval in backoff_intervals:
        if send_webhook(data):
            return True
        retries += 1
        if retries < max_retries:
            logger.info("Retrying webhook in %d seconds...", interval)
            time.sleep(interval)
    logger.error("Max webhook retries reached.")
    return False

def cleanup():
    global sensor, dht_pin
    if sensor is not None:
        try:
            sensor.exit()
        except Exception:
            pass
        sensor = None
    if dht_pin is not None:
        try:
            dht_pin.deinit()
        except Exception:
            pass
        dht_pin = None

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    data_queue = []
    last_webhook_time = 0
    webhook_interval = 300
    while running:
        try:
            temperature, humidity = read_sensor_data()
            if not validate_data(temperature, humidity):
                logger.warning("Invalid data, skipping.")
                time.sleep(60)
                continue
            data_queue.append({"temperature": temperature, "humidity": humidity})
            if len(data_queue) > 5:
                data_queue.pop(0)
            avg_temp = calculate_moving_average([d["temperature"] for d in data_queue])
            avg_hum = calculate_moving_average([d["humidity"] for d in data_queue])
            logger.info("Avg Temp: %.2f C, Avg Hum: %.2f %%", avg_temp, avg_hum)
            now = time.time()
            if now - last_webhook_time >= webhook_interval:
                data = {"temperature": avg_temp, "humidity": avg_hum}
                if retry_webhook(data):
                    last_webhook_time = now
            time.sleep(60)
        except Exception as e:
            logger.error("Unexpected error: %s", e)
            time.sleep(60)
    cleanup()

if __name__ == "__main__":
    main()

