import config
import signal
import sys
import time
import logging
import paho.mqtt.client as mqtt
from gpiozero import Device, DigitalInputDevice
from gpiozero.pins.native import NativeFactory
from adafruit_dht import DHT22

logging.basicConfig(level=logging.INFO, format="%(asctime)s [%(levelname)s] %(message)s")
log = logging.getLogger("dht22_homie")

DEGREE_CELSIUS = "\u00B0C"

running = True
client: mqtt.Client | None = None
dht: DHT22 | None = None


def _signal_handler(signum, frame):
    global running
    log.info("Signal %s received, shutting down…", signum)
    running = False


signal.signal(signal.SIGINT, _signal_handler)
signal.signal(signal.SIGTERM, _signal_handler)


def _on_connect(c, userdata, flags, reason_code, properties):
    if reason_code == 0:
        log.info("Connected to MQTT broker")
    else:
        log.error("MQTT connect failed: %s", reason_code)


def _on_disconnect(c, userdata, flags, reason_code, properties):
    if reason_code != 0:
        log.warning("Unexpected MQTT disconnect: %s", reason_code)
    else:
        log.info("MQTT disconnected cleanly")


def _publish(topic, payload):
    if client is None or not client.is_connected():
        log.error("MQTT client not connected; cannot publish %s", topic)
        return False
    full = f"homie/{config.homieclientid}/{topic}"
    try:
        info = client.publish(full, str(payload), qos=1)
        info.wait_for_publish(timeout=5)
        return True
    except Exception as exc:
        log.error("Publish failed on %s: %s", full, exc)
        return False


def _publish_discovery():
    _publish("$state", "init")
    _publish("$homie", "4.0")
    _publish("$name", config.homieclientname)
    _publish("$nodes", config.homienodes)
    _publish(f"{config.homienodes}/$name", "DHT22 Sensor")
    _publish(f"{config.homienodes}/$properties", "temperature,humidity")
    for prop, name, unit in (
        ("temperature", "Temperature", DEGREE_CELSIUS),
        ("humidity", "Humidity", "%"),
    ):
        _publish(f"{config.homienodes}/{prop}/$name", name)
        _publish(f"{config.homienodes}/{prop}/$unit", unit)
        _publish(f"{config.homienodes}/{prop}/$datatype", "float")
        _publish(f"{config.homienodes}/{prop}/$settable", "false")
    _publish("$state", "ready")


def _connect_mqtt():
    global client
    client = mqtt.Client(
        callback_api_version=mqtt.CallbackAPIVersion.VERSION2,
        client_id=config.mqttclientid,
    )
    if config.mqttusername:
        client.username_pw_set(config.mqttusername, config.mqttpassword)
    client.on_connect = _on_connect
    client.on_disconnect = _on_disconnect
    try:
        client.connect(config.mqttbroker, port=config.mqttport, keepalive=30)
        client.loop_start()
        time.sleep(2)
