import signal
import sys
import time
import logging
import requests
from requests.auth import HTTPBasicAuth
from gpiozero import InputDevice
from gpiozero.exc import GPIOZeroError

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

SERVER_URL = 'http://localhost:5000/sensor'
USERNAME = 'user'
PASSWORD = 'pass'
SENSOR_PIN = 4
POLL_INTERVAL = 5
REQUEST_TIMEOUT = 10

_running = True

def _handle_signal(signum, frame):
    global _running
    logging.info('Received signal %s, shutting down...', signum)
    _running = False

def read_sensor_value(sensor):
    try:
        return int(sensor.value)
    except GPIOZeroError as e:
        logging.error('GPIO read error: %s', e)
        return None

def create_payload(sensor_value):
    return {'sensor': 'Temperature', 'value': sensor_value}

def send_data(payload):
    try:
        response = requests.post(
            SERVER_URL,
            json=payload,
            auth=HTTPBasicAuth(USERNAME, PASSWORD),
            timeout=REQUEST_TIMEOUT
        )
        response.raise_for_status()
        logging.info('Server response: %s - %s', response.status_code, response.text)
    except requests.exceptions.Timeout:
        logging.error('Request timed out after %d seconds', REQUEST_TIMEOUT)
    except requests.exceptions.ConnectionError as e:
        logging.error('Connection error: %s', e)
    except requests.exceptions.HTTPError as e:
        logging.error('HTTP error: %s - %s', e.response.status_code, e.response.text)
    except requests.exceptions.RequestException as e:
        logging.error('Request failed: %s', e)

def main():
    global _running
    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    try:
        sensor = InputDevice(SENSOR_PIN)
    except GPIOZeroError as e:
        logging.error('Failed to initialize GPIO pin %d: %s', SENSOR_PIN, e)
        sys.exit(1)

    logging.info('Starting sensor monitoring on BCM pin %d', SENSOR_PIN)

    try:
        while _running:
            sensor_value = read_sensor_value(sensor)
            if sensor_value is not None:
                payload = create_payload(sensor_value)
                send_data(payload)
            time.sleep(POLL_INTERVAL)
    finally:
        sensor.close()
        logging.info('GPIO cleanup completed.')

if __name__ == '__main__':
    main()

