import time
import signal
import sys
import board
import adafruit_dht

# Global flag for graceful shutdown
_running = True

def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False

def main():
    global _running

    # Register signal handlers for graceful termination
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    # Initialize the DHT11 sensor on board.D4 (BCM GPIO 4, physical pin 7)
    # adafruit_dht.DHT11 uses the BCM numbering scheme by default
    try:
        sensor = adafruit_dht.DHT11(board.D4, use_pulseio=False)
    except Exception as e:
        print(f"Failed to initialize DHT11 sensor on board.D4: {e}")
        sys.exit(1)

    try:
        while _running:
            try:
                temperature = sensor.temperature
                humidity = sensor.humidity

                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f} C")
                    print(f"Humidity: {humidity:.1f} %")
                else:
                    print("Sensor returned None for temperature or humidity.")

            except RuntimeError as e:
                # DHT sensors frequently throw RuntimeErrors on missed reads or checksum failures
                print(f"Sensor read error: {e}")
            except Exception as e:
                # Catch any other unexpected errors (e.g., GPIO access issues)
                print(f"Unexpected error during sensor read: {e}")

            # Wait 5 seconds before the next reading, checking _running flag for early exit
            for _ in range(50):
                if not _running:
                    break
                time.sleep(0.1)

    finally:
        # Release the sensor resources on every exit path
        try:
            sensor.exit()
        except Exception:
            pass
        print("\nSensor released. Exiting.")

if __name__ == "__main__":
    main()

