import json
import signal
import sys
import time
import logging
from datetime import datetime

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO is not available. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

try:
    import adafruit_dht
    import board
    _DHT_AVAILABLE = True
except ImportError:
    _DHT_AVAILABLE = False

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
LED_PIN = 17          # BCM 17 – LED through MOSFET gate to load
DHT_PIN = 4           # BCM 4  – optional DHT22 data line
PWM_FREQ = 100        # Hz
MAX_BRIGHTNESS = 90   # %
RAMP_TIME = 600       # seconds to ramp up/down
HOLD_TIME = 10        # seconds to hold at peak
DHT_INTERVAL = 5      # seconds between DHT22 reads
RETRY_LIMIT = 3

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("led_sunrise")

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
_pwm = None
_dht = None
_running = True


def _iso(ts: float) -> str:
    return datetime.fromtimestamp(ts).isoformat(timespec="seconds")


def _log_entry(brightness: float, temp, hum):
    ts = time.time()
    data = {
        "timestamp": _iso(ts),
        "brightness_pct": round(brightness, 2),
        "temperature_c": temp,
        "humidity_pct": hum,
    }
    print(json.dumps(data), flush=True)


def _read_dht22():
    """Return (temp, hum) or (None, None) on failure."""
    if _dht is None:
        return None, None
    for attempt in range(1, RETRY_LIMIT + 1):
        try:
            t = _dht.temperature
            h = _dht.humidity
            if t is not None and h is not None:
                return t, h
        except RuntimeError as exc:
            log.warning("DHT22 read attempt %d/%d failed: %s", attempt, RETRY_LIMIT, exc)
        except Exception as exc:
            log.error("DHT22 unexpected error: %s", exc)
            break
        time.sleep(0.5)
    return None, None


def _emergency_shutdown():
    global _pwm
    log.info("Emergency shutdown – setting LED brightness to 0 %%")
    if _pwm is not None:
        try:
            _pwm.ChangeDutyCycle(0)
        except Exception:
            pass
        try:
            _pwm.stop()
        except Exception:
            pass
    try:
        GPIO.cleanup()
    except Exception:
        pass
    _pwm = None
    log.info("GPIO cleaned up. Exiting.")
    sys.exit(0)


def _signal_handler(signum, frame):
    global _running
    log.info("Signal %s received – initiating shutdown.", signum)
    _running = False


def _setup():
    global _pwm, _dht
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    GPIO.setup(LED_PIN, GPIO.OUT, initial=GPIO.LOW)
    _pwm = GPIO.PWM(LED_PIN, PWM_FREQ)
    _pwm.start(0)
    if _DHT_AVAILABLE:
        try:
            _dht = adafruit_dht.DHT22(board.D4, use_pulseio=False)
        except Exception as exc:
            log.warning("DHT22 init failed (%s) – sensor disabled.", exc)
            _dht = None


def _cleanup():
    global _pwm
    if _pwm is not None:
        try:
            _pwm.ChangeDutyCycle(0)
        except Exception:
            pass
        try:
            _pwm.stop()
        except Exception:
            pass
        _pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def _ramp_up(duration: float, target: float):
    steps = 100
    delay = duration / steps
    for i in range(1, steps + 1):
        if not _running:
            return
        pct = (i / steps) * target
        pct = min(pct, MAX_BRIGHTNESS)
        try:
            _pwm.ChangeDutyCycle(pct)
        except Exception as exc:
            log.error("PWM duty-cycle update failed: %s", exc)
            return
        temp, hum = _read_dht22()
        _log_entry(pct, temp, hum)
        time.sleep(delay)


def _hold(duration: float, brightness: float):
    end = time.time() + duration
    while time.time() < end:
        if not _running:
            return
        try:
            _pwm.ChangeDutyCycle(brightness)
        except Exception as exc:
            log.error("PWM duty-cycle update failed: %s", exc)
            return
        temp, hum = _read_dht22()
        _log_entry(brightness, temp, hum)
        time.sleep(0.1)


def _ramp_down(duration: float, start: float):
    steps = 100
    delay = duration / steps
    for i in range(steps, 0, -1):
        if not _running:
            return
        pct = (i / steps) * start
        pct = max(0.0, pct)
        try:
            _pwm.ChangeDutyCycle(pct)
        except Exception as exc:
            log.error("PWM duty-cycle update failed: %s", exc)
            return
        temp, hum = _read_dht22()
        _log_entry(pct, temp, hum)
        time.sleep(delay)


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    _setup()
    log.info("Starting sunrise/sunset cycle (max %d%%, ramp %ds, hold %ds).", MAX_BRIGHTNESS, RAMP_TIME, HOLD_TIME)
    try:
        while _running:
            _ramp_up(RAMP_TIME, MAX_BRIGHTNESS)
            if not _running:
                break
            _hold(HOLD_TIME, MAX_BRIGHTNESS)
            if not _running:
                break
            _ramp_down(RAMP_TIME, MAX_BRIGHTNESS)
            if not _running:
                break
            _hold(HOLD_TIME, 0.0)
    except Exception as exc:
        log.exception("Fatal error in main loop: %s", exc)
    finally:
        _cleanup()


if __name__ == "__main__":
    main()

