    while time.time() < end:
        if not _running:
            return
        try:
            _pwm.ChangeDutyCycle(brightness)
        except Exception as exc:
            log.error("PWM duty-cycle update failed: %s", exc)
            return
        temp, hum = _read_dht22()
        _log_entry(brightness, temp, hum)
        time.sleep(0.1)


def _ramp_down(duration: float, start: float):
    steps = 100
    delay = duration / steps
    for i in range(steps, 0, -1):
        if not _running:
            return
        pct = (i / steps) * start
        pct = max(0.0, pct)
        try:
            _pwm.ChangeDutyCycle(pct)
        except Exception as exc:
            log.error("PWM duty-cycle update failed: %s", exc)
