import signal
import sys
import time
import logging
from datetime import datetime

try:
    import board
    import adafruit_dht
    from gpiozero import OutputDevice
    _PLATFORM_HARDWARE = True
except Exception:
    board = None
    adafruit_dht = None
    OutputDevice = None
    _PLATFORM_HARDWARE = False

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
DHT_PIN = 17          # BCM 17 – DHT11 data line
FAN_PIN = 18          # BCM 18 – fan control
LOG_FILE = "urban_data_log.txt"
READ_INTERVAL = 2.0   # seconds between readings
LOOP_COUNT = 5

# Thresholds
TEMP_THRESHOLD = 30.0   # °C
HUM_THRESHOLD = 70.0    # %

# ---------------------------------------------------------------------------
# Logging setup
# ---------------------------------------------------------------------------
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
)
log = logging.getLogger("urban_monitor")

# ---------------------------------------------------------------------------
# Globals for cleanup
# ---------------------------------------------------------------------------
_sensor = None
_fan = None
_running = True


def _cleanup() -> None:
    """Release GPIO resources."""
    global _sensor, _fan
    if _fan is not None:
        try:
            _fan.close()
        except Exception:
            pass
        _fan = None
    if _sensor is not None:
        try:
            _sensor.exit()
        except Exception:
            pass
        _sensor = None


def _handle_signal(signum, frame) -> None:
    """Graceful shutdown on SIGINT / SIGTERM."""
    global _running
    log.info("Received signal %s – shutting down.", signum)
    _running = False


def _init_sensor() -> object:
    """Initialise the DHT11 sensor; return None on non-hardware platforms."""
    if not _PLATFORM_HARDWARE:
        log.warning("Running on a non-hardware platform – sensor disabled.")
        return None
    try:
        pin = getattr(board, f"D{DHT_PIN}")
        return adafruit_dht.DHT11(pin, use_pulseio=False)
    except Exception as exc:
        log.warning("DHT11 init failed on BCM %d: %s", DHT_PIN, exc)
        return None


def _init_fan() -> object:
    """Initialise the fan GPIO; return None on non-hardware platforms."""
    if not _PLATFORM_HARDWARE:
        log.warning("Running on a non-hardware platform – fan disabled.")
        return None
    try:
        return OutputDevice(FAN_PIN, active_high=True, initial_value=False)
    except Exception as exc:
        log.warning("Fan init failed on BCM %d: %s", FAN_PIN, exc)
        return None


def _read_sensor() -> tuple:
    """Return (temperature, humidity) or (None, None) on failure."""
    if _sensor is None:
        return None, None
    try:
        temp = _sensor.temperature
        hum = _sensor.humidity
        if temp is None or hum is None:
            return None, None
        return float(temp), float(hum)
    except RuntimeError as exc:
        # DHT11 checksum / timing glitches are common – log and continue.
        log.warning("DHT11 read error: %s", exc)
        return None, None
    except Exception as exc:
        log.error("Unexpected sensor error: %s", exc)
        return None, None


def _control_fan(temp: float, hum: float) -> None:
    """Drive the fan based on thresholds; never raises."""
    if _fan is None:
        return
    try:
        if temp > TEMP_THRESHOLD or hum > HUM_THRESHOLD:
            if not _fan.is_active:
                _fan.on()
                log.info("Fan ON  (temp=%.1f°C, hum=%.1f%%)", temp, hum)
            else:
                log.info("Fan ON  (temp=%.1f°C, hum=%.1f%%) – fan already on",
                         temp, hum)
        else:
            if _fan.is_active:
                _fan.off()
                log.info("Fan OFF (temp=%.1f°C, hum=%.1f%%)", temp, hum)
            else:
                log.info("Fan OFF (temp=%.1f°C, hum=%.1f%%) – fan already off",
                         temp, hum)
    except Exception as exc:
        log.error("Fan control error: %s", exc)


def _log_data(temp: float, hum: float) -> None:
    """Append a timestamped reading to the log file."""
    ts = datetime.now().isoformat(timespec="seconds")
    line = f"{ts} - Temperature: {temp:.1f}°C, Humidity: {hum:.1f}%\n"
    try:
        with open(LOG_FILE, "a", encoding="utf-8") as fh:
            fh.write(line)
    except OSError as exc:
        log.error("Failed to write log file: %s", exc)


def main() -> int:
    global _sensor, _fan

    signal.signal(signal.SIGINT, _handle_signal)
    signal.signal(signal.SIGTERM, _handle_signal)

    _sensor = _init_sensor()
    _fan = _init_fan()

    try:
        for i in range(1, LOOP_COUNT + 1):
            if not _running:
                break

            temp, hum = _read_sensor()
            if temp is not None and hum is not None:
                _log_data(temp, hum)
                _control_fan(temp, hum)
                print(f"Reading {i}/{LOOP_COUNT}: "
                      f"Temp={temp:.1f}°C  Hum={hum:.1f}%  "
                      f"Fan={'ON' if _fan and _fan.is_active else 'OFF'}")
            else:
                log.warning("Skipping reading %d/%d due to sensor error.",
                            i, LOOP_COUNT)
                _control_fan(0.0, 0.0)   # keep fan in previous state

            if i < LOOP_COUNT and _running:
                time.sleep(READ_INTERVAL)
    finally:
        _cleanup()

    return 0


if __name__ == "__main__":
    sys.exit(main())

