import time
import logging
import signal
import sys
import smbus2 as smbus

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class DHT20:
    DHT20_I2C_ADDR = 0x61
    STATUS_REG = 0x00
    MEASURE_REG = 0x01
    DATA_REG = 0x02
    STATUS_BUSY_BIT = 0x80
    MAX_MEASUREMENT_ATTEMPTS = 5
    MAX_RETRIES = 5
    MEASUREMENT_DELAY = 0.01
    MIN_INTERVAL = 2.0
    POWER_ON_DELAY = 0.5
    STATUS_POLL_DELAY = 0.08
    STATUS_POLL_MAX_ATTEMPTS = 10

    def __init__(self, i2c_bus=1):
        self.i2c_bus_number = i2c_bus
        self.last_measurement_time = 0.0
        self._bus = None
        self._closed = False

    def begin(self):
        try:
            self._bus = smbus.SMBus(self.i2c_bus_number)
            time.sleep(self.POWER_ON_DELAY)
            return True
        except OSError as e:
            logger.error(f"Failed to initialize I2C bus {self.i2c_bus_number}: {e}")
            self._bus = None
            return False

    def close(self):
        if self._bus is not None and not self._closed:
            try:
                self._bus.close()
            except OSError as e:
                logger.warning(f"Error closing I2C bus: {e}")
            finally:
                self._bus = None
                self._closed = True

    def __enter__(self):
        if not self.begin():
            raise RuntimeError("Failed to initialize I2C bus")
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.close()
        return False

    def _read_register(self, register, length=1):
        if self._bus is None:
            raise RuntimeError("I2C bus not initialized")
        try:
            return self._bus.read_i2c_block_data(self.DHT20_I2C_ADDR, register, length)
        except OSError as e:
            logger.error(f"I2C read error (reg 0x{register:02X}): {e}")
            raise

    def _write_register(self, register, value):
        if self._bus is None:
            raise RuntimeError("I2C bus not initialized")
        try:
            self._bus.write_i2c_block_data(self.DHT20_I2C_ADDR, register, value)
        except OSError as e:
            logger.error(f"I2C write error (reg 0x{register:02X}): {e}")
            raise

    def _check_crc(self, data):
        crc = 0xFF
        for byte in data[:-1]:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ 0x31) & 0xFF
                else:
                    crc = (crc << 1) & 0xFF
        return crc == data[-1]

    def _wait_for_ready(self):
        for _ in range(self.STATUS_POLL_MAX_ATTEMPTS):
            status = self._read_register(self.STATUS_REG, 1)[0]
            if not (status & self.STATUS_BUSY_BIT):
                return True
            time.sleep(self.STATUS_POLL_DELAY)
        return False

    def get_temperature_and_humidity(self):
        if time.time() - self.last_measurement_time < self.MIN_INTERVAL:
            logger.warning("Minimum interval not met; returning cached data.")
            return self.last_temperature, self.last_humidity, False

        for attempt in range(self.MAX_MEASUREMENT_ATTEMPTS):
            if not self._wait_for_ready():
                logger.warning(f"Sensor not ready after {self.STATUS_POLL_MAX_ATTEMPTS} attempts.")
                time.sleep(self.MEASUREMENT_DELAY)
                continue

            try:
                self._write_register(self.MEASURE_REG, [0x32])
            except OSError:
                time.sleep(self.MEASUREMENT_DELAY)
                continue

            time.sleep(0.08)

            for retry in range(self.MAX_RETRIES):
                try:
                    data = self._read_register(self.DATA_REG, 7)
                except OSError:
                    time.sleep(self.MEASUREMENT_DELAY)
                    continue

                if not self._check_crc(data):
                    logger.warning("CRC error detected; retrying.")
                    time.sleep(self.MEASUREMENT_DELAY)
                    continue

                humidity_raw = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) & 0xFFFFF
                temperature_raw = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) & 0xFFFFF

                temperature = (temperature_raw / 5242.88) - 50.0
                humidity = (humidity_raw / 83886.08) * 100.0

                self.last_temperature = temperature
                self.last_humidity = humidity
                self.last_measurement_time = time.time()
                return temperature, humidity, False

            logger.warning(f"Failed to get valid data after {self.MAX_RETRIES} retries.")
            time.sleep(self.MEASUREMENT_DELAY)

        logger.error("Failed to get valid data after all measurement attempts.")
        return None, None, True


def main():
    running = True

    def signal_handler(signum, frame):
        nonlocal running
        running = False

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        with DHT20(i2c_bus=1) as sensor:
            if not sensor.begin():
                logger.error("Failed to initialize DHT20 sensor.")
                return 0

            while running:
                temperature, humidity, error = sensor.get_temperature_and_humidity()
                if error:
                    logger.error("Measurement failed.")
                else:
                    logger.info(f"Temperature: {temperature:.2f} C, Humidity: {humidity:.2f} %")
                time.sleep(2.0)
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())

