    2: {'red': 5, 'green': 6, 'blue': 13},
    3: {'red': 19, 'green': 26, 'blue': 16}
}
PWM_FREQUENCY = 1000
SAFE_TEMP_RANGE = (18, 28)
SAFE_HUMIDITY_RANGE = (30, 80)
CLOUD_ENDPOINT = 'http://example.com/api/data'
UPLOAD_INTERVAL = 60
SENSOR_READ_INTERVAL = 5
MAX_RETRIES = 3
RETRY_DELAY = 2

# --- Logging Setup ---
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s',
    handlers=[
        logging.FileHandler('rgb_led_monitor.log'),
        logging.StreamHandler(sys.stdout)
    ]
)

# --- Global State ---
last_temperature = None
last_humidity = None
running = True

# --- GPIO Setup ---
dht_device = None
leds = {}

try:
    dht_device = adafruit_dht.DHT22(DHT_PIN, use_pulseio=False)
    logging.info("DHT22 sensor initialized on GPIO4.")
except Exception as e:
    logging.error(f"Failed to initialize DHT22 sensor: {e}")
    sys.exit(1)

for led_id, pins in LED_PINS.items():
    leds[led_id] = {}
    for color, pin in pins.items():
        try:
            leds[led_id][color] = PWMLED(pin, frequency=PWM_FREQUENCY)
            leds[led_id][color].value = 0.0
        except Exception as e:
            logging.error(f"Failed to initialize PWMLED on GPIO{pin}: {e}")
            sys.exit(1)

# --- Signal Handler ---
def signal_handler(sig, frame):
    global running
    logging.info("Received interrupt signal, shutting down...")
    running = False

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# --- Sensor Reading ---
def read_dht22():
    global last_temperature, last_humidity
    for attempt in range(1, MAX_RETRIES + 1):
        try:
            temperature = dht_device.temperature
            humidity = dht_device.humidity
            if temperature is not None and humidity is not None:
                last_temperature = temperature
                last_humidity = humidity
                logging.info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                return temperature, humidity
            else:
                logging.warning(f"DHT22 returned None values (attempt {attempt}/{MAX_RETRIES})")
        except RuntimeError as e:
            logging.warning(f"DHT22 read error (attempt {attempt}/{MAX_RETRIES}): {e}")
        except Exception as e:
            logging.error(f"Unexpected DHT22 error (attempt {attempt}/{MAX_RETRIES}): {e}")
        if attempt < MAX_RETRIES:
            time.sleep(RETRY_DELAY)
    logging.error("DHT22 sensor read failed after all retries.")
    return last_temperature, last_humidity

# --- Color Mapping ---
def map_color(temperature):
    if temperature < 15:
        return (0, 0, 255)  # Blue
    elif temperature < 20:
        return (0, 255, 0)  # Green
    elif temperature < 25:
        return (255, 255, 0)  # Yellow
    else:
        return (255, 0, 0)  # Red

def map_brightness(humidity):
    return max(0, min(100, int(humidity)))

