def set_led_color(led_id, color, brightness):
    try:
        leds[led_id][color].value = brightness / 100.0
    except Exception as e:
        logging.error(f"Error setting LED {led_id} {color} to brightness {brightness}: {e}")

def set_leds(temperature, humidity):
    color = map_color(temperature)
    brightness = map_brightness(humidity)
    for led_id in leds:
        set_led_color(led_id, 'red', color[0])
        set_led_color(led_id, 'green', color[1])
        set_led_color(led_id, 'blue', color[2])
    logging.info(f"LEDs set to color {color} with brightness {brightness}")

# --- Cloud Upload ---
def upload_data(temperature, humidity, color, brightness, alert=None):
    payload = {
        'temperature': temperature,
        'humidity': humidity,
        'color': color,
        'brightness': brightness,
        'timestamp': time.time()
    }
    if alert:
        payload['status'] = alert
    try:
        import requests
        response = requests.post(CLOUD_ENDPOINT, json=payload, timeout=10)
        response.raise_for_status()
        logging.info(f"Data uploaded to cloud. Status code: {response.status_code}")
    except requests.exceptions.RequestException as e:
        logging.error(f"Error uploading data to cloud: {e}")

# --- Main Loop ---
def main():
    global running
    last_upload_time = time.time()
    while running:
        temperature, humidity = read_dht22()
        if temperature is not None and humidity is not None:
            set_leds(temperature, humidity)
            alert = None
            if not (SAFE_TEMP_RANGE[0] <= temperature <= SAFE_TEMP_RANGE[1]):
                alert = "Temperature Alert"
            if not (SAFE_HUMIDITY_RANGE[0] <= humidity <= SAFE_HUMIDITY_RANGE[1]):
                alert = "Humidity Alert" if not alert else "Temperature and Humidity Alert"
            if alert:
                logging.warning(f"Alert: {alert}")
            if time.time() - last_upload_time >= UPLOAD_INTERVAL:
                color = map_color(temperature)
                brightness = map_brightness(humidity)
                upload_thread = threading.Thread(
                    target=upload_data,
                    args=(temperature, humidity, color, brightness, alert)
                )
                upload_thread.daemon = True
                upload_thread.start()
                last_upload_time = time.time()
        else:
            logging.warning("Skipping LED update due to invalid sensor data.")
        for _ in range(SENSOR_READ_INTERVAL):
            if not running:
                break
            time.sleep(1)
    cleanup()

def cleanup():
    logging.info("Cleaning up GPIO resources...")
    for led_id in leds:
        for color in leds[led_id]:
            try:
                leds[led_id][color].close()
            except Exception:
                pass
    if dht_device:
        try:
            dht_device.exit()
        except Exception:
            pass
    logging.info("Cleanup complete.")

if __name__ == "__main__":
    main()

