import subprocess
import sys
import time
import signal
import re
from gpiozero import PWMOutputDevice

FAN_PIN = 14
PWM_FREQ = 100.0
POLL_INTERVAL = 5.0
DEFAULT_DUTY = 100.0

fan = None
running = True


def cleanup(signum=None, frame=None):
    global running, fan
    running = False
    if fan is not None:
        try:
            fan.value = 0.0
            fan.close()
        except Exception:
            pass
        fan = None
    if signum is not None:
        sys.exit(0)


def get_cpu_temp():
    try:
        result = subprocess.run(
            ["vcgencmd", "measure_temp"],
            capture_output=True,
            text=True,
            timeout=5,
        )
        if result.returncode != 0:
            raise RuntimeError(f"vcgencmd exited with {result.returncode}")
        match = re.search(r"temp=([0-9.]+)'C", result.stdout)
        if not match:
            raise RuntimeError("temperature value not found in output")
        return float(match.group(1))
    except Exception as exc:
        raise RuntimeError(f"failed to read CPU temperature: {exc}") from exc


def main():
    global fan
    try:
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0.0)
    except Exception as exc:
        print(f"Failed to initialize PWM on GPIO{FAN_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)

    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)

    duty = None
    while running:
        try:
            temp = get_cpu_temp()
            if temp > 70.0:
                duty = 100.0
            elif temp > 60.0:
                duty = 75.0
            elif temp > 50.0:
                duty = 50.0
            else:
                duty = 25.0
            fan.value = duty / 100.0
            print(f"CPU temp: {temp:.1f}C  fan duty: {duty:.1f}%")
        except RuntimeError as exc:
            print(f"Error: {exc}", file=sys.stderr)
            if duty is None:
                duty = DEFAULT_DUTY
            fan.value = duty / 100.0
        except Exception as exc:
            print(f"Unexpected error: {exc}", file=sys.stderr)
            if duty is None:
                duty = DEFAULT_DUTY
            fan.value = duty / 100.0

        time.sleep(POLL_INTERVAL)

    cleanup()


if __name__ == "__main__":
    main()

