import time
import signal
import sys
import subprocess
import logging
from gpiozero import PWMOutputDevice

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5
TEMP_FILE = "/sys/class/thermal/thermal_zone0/temp"

TEMP_STEPS = [
    (70, 100),
    (60, 80),
    (50, 60),
    (40, 40),
    (30, 20),
]

_running = True


def _handle_signal(signum, frame):
    global _running
    logging.info("Received signal %s, shutting down...", signum)
    _running = False


class FanController:
    def __init__(self, pin, pwm_freq, temp_steps, check_interval):
        self.pin = pin
        self.pwm_freq = pwm_freq
        self.temp_steps = temp_steps
        self.check_interval = check_interval
        self._device = None

    def _get_cpu_temp(self):
        try:
            result = subprocess.run(
                ["vcgencmd", "measure_temp"],
                capture_output=True,
                text=True,
                timeout=5,
            )
            if result.returncode != 0:
                raise RuntimeError(f"vcgencmd failed: {result.stderr.strip()}")
            return float(result.stdout.split("=")[1].split("'")[0])
        except Exception as e:
            logging.warning("vcgencmd failed, falling back to sysfs: %s", e)
            try:
                with open(TEMP_FILE, "r") as f:
                    return float(f.read().strip()) / 1000.0
            except Exception as f_e:
                raise RuntimeError(f"Failed to read CPU temperature: {f_e}") from f_e

    def _calculate_duty_cycle(self, temp):
        for threshold, duty in self.temp_steps:
            if temp >= threshold:
                return duty
        return 0

    def run(self):
        global _running
        signal.signal(signal.SIGTERM, _handle_signal)
        signal.signal(signal.SIGINT, _handle_signal)

        try:
            self._device = PWMOutputDevice(self.pin, frequency=self.pwm_freq, initial_value=0)
            logging.info("Fan controller started on GPIO%d at %d Hz.", self.pin, self.pwm_freq)

            while _running:
                try:
                    temp = self._get_cpu_temp()
                    duty = self._calculate_duty_cycle(temp)
                    self._device.value = duty / 100.0
                    logging.info("CPU temp: %.1f°C, Fan speed: %d%%", temp, duty)
                except RuntimeError as e:
                    logging.error("Temperature read error: %s", e)
                except Exception as e:
                    logging.error("Unexpected error: %s", e)

                for _ in range(self.check_interval):
                    if not _running:
                        break
                    time.sleep(1)

        except Exception as e:
            logging.error("Initialization error: %s", e)
        finally:
            if self._device is not None:
                self._device.close()
            logging.info("Fan controller stopped.")


if __name__ == "__main__":
    controller = FanController(FAN_PIN, PWM_FREQ, TEMP_STEPS, CHECK_INTERVAL)
    controller.run()

