import smbus
import time
import signal
import sys

I2C_BUS = 1
I2C_ADDR = 0x74

running = True

def signal_handler(sig, frame):
    global running
    running = False

def crc8(data):
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x80:
                crc = ((crc << 1) ^ 0x31) & 0xFF
            else:
                crc = (crc << 1) & 0xFF
    return crc

def read_sensor_data(bus):
    try:
        bus.write_byte(I2C_ADDR, 0xBA)
        time.sleep(0.02)
        bus.write_byte(I2C_ADDR, 0x3C)
        time.sleep(0.01)
        bus.write_byte(I2C_ADDR, 0x08)
        time.sleep(0.08)
        data = bus.read_i2c_block_data(I2C_ADDR, 0x00, 7)
        if len(data) != 7:
            raise IOError("Incomplete data read")
        if crc8(data[:6]) != data[6]:
            raise IOError("CRC mismatch")
