import signal
import sys
import time
from datetime import datetime

import serial
import serial.tools.list_ports
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
LOG_FILE = '/home/pi/sensor_log.txt'
ALERT_PIN = 17
TEMP_THRESHOLD = 28.0
HUMIDITY_THRESHOLD = 65.0
ALERT_DURATION = 5.0

_running = True
_alert = None
_serial = None


def _signal_handler(signum, frame):
    global _running
    _running = False


def _cleanup():
    global _alert, _serial
    if _alert is not None:
        try:
            _alert.close()
        except Exception:
            pass
        _alert = None
    if _serial is not None:
        try:
            _serial.close()
        except Exception:
            pass
        _serial = None


def _log(msg):
    try:
        with open(LOG_FILE, 'a') as f:
            f.write(msg)
    except OSError as e:
        print(f'Log write error: {e}', file=sys.stderr)


def _parse_line(line):
    if not line:
        return None, None
    parts = line.split(',')
    if len(parts) != 2:
        return None, None
    try:
        temperature = float(parts[0])
        humidity = float(parts[1])
    except ValueError:
        return None, None
    return temperature, humidity


def _check_thresholds(temperature, humidity):
    return temperature > TEMP_THRESHOLD or humidity > HUMIDITY_THRESHOLD


def _trigger_alert():
    if _alert is None:
        return
    try:
        _alert.on()
        time.sleep(ALERT_DURATION)
    except Exception as e:
        print(f'Alert error: {e}', file=sys.stderr)
    finally:
        try:
            _alert.off()
        except Exception:
            pass


def main():
    global _alert, _serial

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    try:
        _alert = OutputDevice(ALERT_PIN, active_high=True, initial_value=False)
    except Exception as e:
        print(f'Failed to init GPIO{ALERT_PIN}: {e}', file=sys.stderr)
        sys.exit(1)

    try:
        _serial = serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUD_RATE,
            timeout=1.0,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
        )
    except serial.SerialException as e:
        print(f'Failed to open {SERIAL_PORT}: {e}', file=sys.stderr)
        _cleanup()
        sys.exit(1)

    print(f'Listening on {SERIAL_PORT} @ {BAUD_RATE} baud. Press Ctrl-C to stop.')

    try:
        while _running:
            try:
                raw = _serial.readline()
            except serial.SerialException as e:
                print(f'Serial read error: {e}', file=sys.stderr)
                time.sleep(1.0)
                continue

            if not raw:
                continue

            try:
                line = raw.decode('ascii', errors='replace').strip()
            except Exception:
                continue

            temperature, humidity = _parse_line(line)
            if temperature is None or humidity is None:
                continue

            timestamp = datetime.now().isoformat(timespec='seconds')
            record = f'{timestamp} - Temperature: {temperature:.2f}C, Humidity: {humidity:.2f}%\n'
            _log(record)

            if _check_thresholds(temperature, humidity):
                _trigger_alert()

    finally:
        _cleanup()
        print('Exited cleanly.')


if __name__ == '__main__':
    main()

