import time
import signal
import sys

try:
    from gpiozero import OutputDevice
    from gpiozero.exc import GPIOZeroError
except ImportError:
    print("Error: gpiozero is not installed. Install with: sudo apt install python3-gpiozero")
    sys.exit(1)

FAN_PIN = 18
TEMP_THRESHOLD = 30.0
NUM_READINGS = 5
DELAY_SECONDS = 2

fan = None
running = True

def signal_handler(signum, frame):
    global running
    running = False

def read_temp():
    return random.randint(20, 40)

def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        fan = OutputDevice(FAN_PIN)
        print(f"Fan control initialized on GPIO{FAN_PIN} (BCM).")
        print("No physical temperature sensor is being used; readings are simulated.")
        print(f"Threshold: {TEMP_THRESHOLD}°C. Press Ctrl+C to exit.\n")

        for i in range(NUM_READINGS):
            if not running:
                break

            temp = read_temp()
            print(f"Reading {i + 1}/{NUM_READINGS} - Simulated Temperature: {temp}°C")

            if temp > TEMP_THRESHOLD:
                fan.on()
                print("  -> Fan ON: temperature exceeds threshold.")
            else:
                fan.off()
                print("  -> Fan OFF: temperature within safe range.")

            if i < NUM_READINGS - 1 and running:
                time.sleep(DELAY_SECONDS)

        if running:
            print("\nTemperature monitoring complete.")
        else:
            print("\nProgram terminated by user.")

    except GPIOZeroError as e:
        print(f"GPIO error: {e}")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        if fan is not None:
            try:
                fan.close()
                print("GPIO cleanup complete.")
            except Exception as e:
                print(f"Error during GPIO cleanup: {e}")

if __name__ == "__main__":
    main()

