import subprocess
import time
import signal
import sys
import logging

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

FAN_PIN = 14
PWM_FREQ = 100
CHECK_INTERVAL = 5
TEMP_CMD = 'vcgencmd measure_temp'

fan = None
running = True

def signal_handler(signum, frame):
    global running
    logging.info(f"Received signal {signum}, shutting down...")
    running = False

def get_temp():
    try:
        result = subprocess.run(
            TEMP_CMD.split(),
            capture_output=True,
            text=True,
            timeout=5,
            check=True
        )
        temp_str = result.stdout.strip()
        return float(temp_str.split('=')[1].split("'")[0])
    except subprocess.CalledProcessError as e:
        logging.error(f"vcgencmd failed: {e.stderr.strip()}")
    except subprocess.TimeoutExpired:
        logging.error("vcgencmd timed out")
    except (IndexError, ValueError) as e:
        logging.error(f"Failed to parse temperature: {e}")
    except FileNotFoundError:
        logging.error("vcgencmd not found on this system")
    return None

def set_fan_speed(speed):
    if fan is not None:
        try:
            fan.duty_cycle = speed
            logging.info(f"Fan speed set to {speed}%")
        except Exception as e:
            logging.error(f"Failed to set fan speed: {e}")
    else:
        logging.info(f"Degraded mode - fan speed would be set to {speed}%")

def cleanup():
    global fan
    if fan is not None:
        try:
            fan.duty_cycle = 0
            fan.close()
            logging.info("Fan PWM stopped and GPIO released.")
        except Exception as e:
            logging.error(f"Error during cleanup: {e}")
        finally:
            fan = None

def main():
    global fan
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        from gpiozero import PWMOutputDevice
        fan = PWMOutputDevice(FAN_PIN, frequency=PWM_FREQ, initial_value=0)
        logging.info(f"PWM initialized on GPIO{FAN_PIN} at {PWM_FREQ} Hz.")
    except Exception as e:
        logging.warning(f"Failed to initialize PWM on GPIO{FAN_PIN}: {e}")
        logging.warning("Continuing in degraded mode (no hardware PWM).")
        fan = None

    last_speed = 0
    try:
        while running:
            temp = get_temp()
            if temp is not None:
                if temp > 70:
                    speed = 100
                elif temp > 60:
                    speed = 75
                elif temp > 50:
                    speed = 50
                else:
                    speed = 0
                if speed != last_speed:
                    set_fan_speed(speed)
                    last_speed = speed
            else:
                logging.warning("Temperature read failed; maintaining last fan speed.")
            for _ in range(CHECK_INTERVAL):
                if not running:
                    break
                time.sleep(1)
    except Exception as e:
        logging.error(f"Unexpected error: {e}")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

