import sys
import time
import signal
import threading
from typing import Optional

try:
    from picamera2 import Picamera2
except ImportError:
    Picamera2 = None

try:
    from libcamera import Transform
except ImportError:
    Transform = None

try:
    from libdog import DOG
except ImportError:
    DOG = None


class DOGController:
    """Command-line interface for the DOG device with robust error handling."""

    HELP_MESSAGES = {
        "help": "Call 'help <command>' to see information about the command.\nCommands:\n\t-display\n\t-help\n\t-start\n\t-stop\n\t-exit\n\t-send\n\t-write",
        "start": "Help for 'start':\nStarts listening to the DOG device and saves data to a file. Usage: start <filename>",
        "display": "Help for 'display':\nDisplays the contents of the log file.",
        "exit": "Help for 'exit':\nCloses this program.",
        "send": "Help for 'send':\nSends data via the DOG device. Usage: send <data>",
        "stop": "Help for 'stop':\nStops listening to the DOG device.",
        "write": "Help for 'write':\nWrites a string directly to the log file. Usage: write <data>",
    }

    def __init__(self) -> None:
        self.is_running = False
        self.is_dog_running = False
        self.dog: Optional[DOG] = None
        self.receive_thread: Optional[threading.Thread] = None
        self._lock = threading.Lock()
        self._stop_event = threading.Event()

    # ------------------------------------------------------------------
    # Signal handling
    # ------------------------------------------------------------------
    def _signal_handler(self, signum: int, frame) -> None:
        print(f"\nSignal {signum} received. Shutting down...")
        self.stop_dog()
        sys.exit(0)

    # ------------------------------------------------------------------
    # DOG lifecycle
    # ------------------------------------------------------------------
    def start_dog(self, filename: str) -> None:
        """Starts the DOG API call and the background receive thread."""
        if self.is_dog_running:
            print("DOG is already running.")
            return

        if DOG is None:
            print("Error: libdog module not available.")
            return

        try:
            self.dog = DOG()
            self.dog.receive()
            self.is_dog_running = True
            self.is_running = True
            self._stop_event.clear()

            self.receive_thread = threading.Thread(
                target=self._receive_loop, daemon=True
            )
            self.receive_thread.start()
            print(f"Started DOG and logging to {filename}")
        except Exception as e:
            print(f"Error starting DOG: {e}")
            self.dog = None

    def _receive_loop(self) -> None:
        """Background loop: poll DOG.receive() every 0.1 s and write to file."""
        if self.dog is None:
            return
        try:
            with open(self.filename, "a") as f:
                while self.is_running and not self._stop_event.is_set():
                    try:
                        data = self.dog.receive()
                        if data is not None:
                            f.write(str(data) + "\n")
                            f.flush()
                    except Exception as e:
                        print(f"Error receiving data: {e}")
                    time.sleep(0.1)
        except Exception as e:
            print(f"Error in receive loop: {e}")
        finally:
            self.is_dog_running = False
            self.is_running = False
            self._stop_event.set()
            print("Stopped receiving data.")

    def stop_dog(self) -> None:
        """Stops the DOG API call and the background thread."""
        self.is_running = False
        self._stop_event.set()

        if self.receive_thread is not None and self.receive_thread.is_alive():
            self.receive_thread.join(timeout=2.0)
            if self.receive_thread.is_alive():
                print("Warning: receive thread did not terminate cleanly.")

        if self.dog is not None:
            try:
                self.dog.stop()
            except Exception as e:
                print(f"Error stopping DOG: {e}")
            finally:
                self.dog = None
                self.is_dog_running = False

    # ------------------------------------------------------------------
    # Command dispatch
    # ------------------------------------------------------------------
    def process_command(self, command: str, args: list) -> None:
        """Dispatches commands to their respective handlers."""
        if not args:
            print("Error: No command given. Try 'help'.")
            return

        cmd = args[0].lower()
        try:
            if cmd == "help":
                self._help(args[1:])
            elif cmd == "start":
                self._start(args[1:])
            elif cmd == "display":
                self._display()
            elif cmd == "exit":
                self._exit()
            elif cmd == "send":
                self._send(args[1:])
            elif cmd == "stop":
                self._stop()
            elif cmd == "write":
                self._write(args[1:])
            else:
                print(f"Unknown command: {cmd}. Try 'help'.")
        except IndexError:
            print("Error: Incomplete command. Try 'help'.")
        except Exception as e:
            print(f"Error processing command: {e}")

    def _help(self, args: list) -> None:
        if not args:
            print(self.HELP_MESSAGES["help"])
        else:
            cmd = args[0].lower()
            if cmd in self.HELP_MESSAGES:
                print(self.HELP_MESSAGES[cmd])
            else:
                print(f"No help found for command: {cmd}")

    def _start(self, args: list) -> None:
        if not args:
            print("Error: No filename provided. Usage: start <filename>")
            return
        self.filename = args[0]
        self.start_dog(self.filename)

    def _display(self) -> None:
        try:
            with open(self.filename, "r") as f:
                print(f.read())
        except FileNotFoundError:
            print(f"Error: File '{self.filename}' not found.")
        except Exception as e:
            print(f"Error displaying file: {e}")

    def _exit(self) -> None:
        self.stop_dog()
        print("Exiting program.")
        sys.exit(0)

    def _send(self, args: list) -> None:
        if not args:
            print("Error: No data provided. Usage: send <data>")
            return
        data_string = " ".join(args)
        if self.dog is not None:
            try:
                self.dog.send(data_string)
                print(f"Sent: {data_string}")
            except Exception as e:
                print(f"Error sending data: {e}")
        else:
            print("Error: DOG not running. Start DOG first.")

    def _stop(self) -> None:
        self.stop_dog()
        print("Stopped DOG.")

    def _write(self, args: list) -> None:
        if not args:
            print("Error: No data provided. Usage: write <data>")
            return
        data_string = " ".join(args)
        try:
            with open(self.filename, "a") as f:
                f.write(data_string + "\n")
                f.flush()
            print(f"Wrote: {data_string} to {self.filename}")
        except Exception as e:
            print(f"Error writing to file: {e}")


def main() -> None:
    controller = DOGController()

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, controller._signal_handler)
    signal.signal(signal.SIGTERM, controller._signal_handler)

    print("DOG Controller Ready. Type 'help' for available commands.")
    try:
        while True:
            try:
                command = input("Enter command: ").strip()
            except EOFError:
                print("\nEOF received. Exiting.")
                break

            if not command:
                continue

            parts = command.split()
            cmd = parts[0].lower()
            if cmd in ("start", "send", "write") and not controller.is_dog_running:
                print("Error: DOG must be started first. Use 'start <filename>'.")
                continue

            controller.process_command(command, parts)
    except Exception as e:
        print(f"Unexpected error in main loop: {e}")
    finally:
        controller.stop_dog()
        print("Program terminated.")


if __name__ == "__main__":
    main()

