# PIR Motion Sensor Counter for Raspberry Pi
# Uses an HC-SR501 PIR motion sensor on GPIO 4 (BCM).
# Wiring: VCC -> 5V, GND -> GND, OUT -> GPIO 4
#
# Dependencies: RPi.GPIO (pre-installed on Raspberry Pi OS)

import RPi.GPIO as GPIO
import time
import sys

# ---------------------------------------------------------------------------
# Configuration
# ---------------------------------------------------------------------------
PIR_PIN = 4          # BCM GPIO pin connected to the sensor OUT terminal
MONITOR_SECONDS = 20  # Total monitoring duration
DEBOUNCE_DELAY = 0.05  # Seconds to wait after a detected event to avoid retriggering

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
motion_count = 0
running = True


def setup_sensor() -> None:
    """Configure the GPIO pin as an input with a pull-down resistor."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(PIR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
    except Exception as exc:
        print(f"Error: failed to initialize GPIO pin {PIR_PIN}: {exc}", file=sys.stderr)
        sys.exit(1)


def detect_motion() -> bool:
    """Return True if motion is currently detected (HIGH)."""
    try:
        return bool(GPIO.input(PIR_PIN))
    except Exception as exc:
        print(f"Warning: GPIO read failed: {exc}", file=sys.stderr)
        return False


def report_state() -> None:
    """Print a friendly message when motion starts or stops."""
    global motion_count
    if detect_motion():
        if motion_count == 0:
            print("Motion detected! Intruder alert!")
        motion_count += 1
    else:
        if motion_count > 0:
            print("Motion stopped.")


def cleanup() -> None:
    """Release GPIO resources safely."""
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main() -> None:
    global running

    setup_sensor()
    print("PIR motion sensor initialized on GPIO 4.")
    print(f"Monitoring for {MONITOR_SECONDS} seconds...")

    try:
        while running and time.time() < (time.time() + MONITOR_SECONDS):
            report_state()
            time.sleep(0.1)  # Poll every 100 ms
    except KeyboardInterrupt:
        print("\nMonitoring interrupted by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup()
        print(f"Total motion events detected: {motion_count}")
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

