from pathlib import Path

import psutil
import tflite_runtime.interpreter as tflite
from gpiozero import LED
from gpiozero.exc import GPIOZeroError
from pyaudio import PyAudio,.paInt16,paNoError

CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensitivity": 0.5,
    "keywords": ["happy", "sad", "angry", "excited"],
    "positive_threshold": 0.7,
    "negative_threshold": 0.3,
    "alert_threshold": 0.8,
    "led_pin": 17,
    "log_level": "INFO",
    "model_path": "model.tflite",
    "heartbeat_interval": 60,
    "config_check_interval": 300,
    "resource_usage_interval": 60,
    "cloud_alert_enabled": False,
    "cloud_endpoint": "http://example.com/alert"
}

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

class ConfigurationError(Exception):
    pass

class AudioCaptureError(Exception):
    pass

class ModelInferenceError(Exception):
    pass

class CloudCommunicationError(Exception):
    pass

def load_config(config_file=CONFIG_FILE):
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        merged = DEFAULT_CONFIG.copy()
        merged.update(config)
        return merged
    except FileNotFoundError:
        logger.warning(f"Config file not found: {config_file}. Using defaults.")
        return DEFAULT_CONFIG.copy()
    except json.JSONDecodeError as e:
        logger.error(f"Invalid JSON in config: {e}. Using defaults.")
        return DEFAULT_CONFIG.copy()

def setup_logging(log_level):
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f'Invalid log level: {log_level}')
    logging.getLogger().setLevel(numeric_level)

def capture_audio(sample_rate, chunk_size):
    try:
