import signal
import sys
import time

import board
import busio
import adafruit_tsl2561
from gpiozero import PWMOutputDevice

# --- Configuration -----------------------------------------------------------
I2C_BUS = 1
TSL2561_ADDRESS = 0x29
LED_GPIO_PIN = 18
PWM_FREQUENCY = 1000
UPDATE_INTERVAL = 1.0
INTEGRATION_TIME = adafruit_tsl2561.INTEGRATIONTIME_402MS
GAIN = adafruit_tsl2561.GAIN_AUTO

# --- Globals for cleanup -----------------------------------------------------
i2c_bus = None
light_sensor = None
led_pwm = None
running = True


def cleanup():
    """Release all hardware resources safely."""
    global i2c_bus, light_sensor, led_pwm
    if led_pwm is not None:
        try:
            led_pwm.close()
        except Exception:
            pass
        led_pwm = None
    if light_sensor is not None:
        try:
            light_sensor.deinit()
        except Exception:
            pass
        light_sensor = None
    if i2c_bus is not None:
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        i2c_bus = None


def signal_handler(signum, frame):
    """Handle SIGINT / SIGTERM for graceful shutdown."""
    global running
    running = False


def initialize_i2c():
    """Initialize the I2C bus on GPIO2 (SDA) / GPIO3 (SCL)."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}", file=sys.stderr)
        return None


def initialize_light_sensor(i2c):
    """Initialize the TSL2561 ambient light sensor."""
    try:
        sensor = adafruit_tsl2561.TSL2561(i2c, address=TSL2561_ADDRESS)
        sensor.integration_time = INTEGRATION_TIME
        sensor.gain = GAIN
        return sensor
    except ValueError as e:
        print(f"TSL2561 not detected at address 0x{TSL2561_ADDRESS:02X}: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error initializing TSL2561: {e}", file=sys.stderr)
        return None


def initialize_led_pwm(pin, frequency):
    """Initialize hardware PWM on the specified GPIO pin."""
    try:
        return PWMOutputDevice(pin=pin, frequency=frequency, initial_value=0.0)
    except Exception as e:
        print(f"Error initializing PWM on GPIO{pin}: {e}", file=sys.stderr)
        return None


def read_light_level(sensor):
    """Read the ambient light level in lux from the TSL2561."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light level: {e}", file=sys.stderr)
        return None


def calculate_brightness(light_level):
    """Map the light level (lux) to a brightness percentage (0-100)."""
    if light_level is None:
        return None
    if light_level <= 0:
        return 0.0
    return min(100.0, (light_level / 1000.0) * 100.0)


def set_led_brightness(pwm, brightness):
    """Set the LED brightness using PWM duty cycle (0.0-1.0)."""
    if pwm is None or brightness is None:
        return
    try:
        pwm.value = brightness / 100.0
    except Exception as e:
        print(f"Error setting LED brightness: {e}", file=sys.stderr)


def display_light_and_brightness(light_level, brightness):
    """Print the light level and brightness percentage."""
    if light_level is not None and brightness is not None:
        print(f"Light Level: {light_level:.2f} lux, Brightness: {brightness:.2f}%")


def main():
    """Main loop: read light, update LED, and report every second."""
    global i2c_bus, light_sensor, led_pwm, running

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        cleanup()
        sys.exit(1)

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        cleanup()
        sys.exit(1)

    led_pwm = initialize_led_pwm(LED_GPIO_PIN, PWM_FREQUENCY)
    if led_pwm is None:
        cleanup()
        sys.exit(1)

    try:
        while running:
            light_level = read_light_level(light_sensor)
            brightness = calculate_brightness(light_level)
            set_led_brightness(led_pwm, brightness)
            display_light_and_brightness(light_level, brightness)
            time.sleep(UPDATE_INTERVAL)
    except Exception as e:
        print(f"Fatal error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

