import RPi.GPIO as GPIO
import time
import sys

# GPIO pins for the left and right TCRT5000 infrared line sensors
# (BCM numbering)
LEFT_SENSOR_PIN = 5
RIGHT_SENSOR_PIN = 6

# Sampling interval (seconds)
SAMPLE_INTERVAL = 0.5

# Number of samples to collect
NUM_SAMPLES = 10


def setup_gpio():
    """Configure GPIO pins for the line sensors.

    Returns True on success, False on failure.
    """
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LEFT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        GPIO.setup(RIGHT_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
        return True
    except Exception as exc:
        print(f"Error: Failed to initialize GPIO: {exc}", file=sys.stderr)
        return False


def read_sensor(pin):
    """Read a single TCRT5000 sensor.

    Returns 0 (black line) or 1 (white surface).  Returns None on error.
    """
    try:
        return GPIO.input(pin)
    except Exception as exc:
        print(f"Error: Failed to read GPIO pin {pin}: {exc}", file=sys.stderr)
        return None


def determine_direction(left_val, right_val):
    """Derive a steering direction from left and right sensor readings.

    0 = black (line), 1 = white (surface).
    """
    if left_val == 0 and right_val == 0:
        return "forward"
    if left_val == 1 and right_val == 1:
        return "search"
    if left_val == 0 and right_val == 1:
        return "turn-right"
    if left_val == 1 and right_val == 0:
        return "turn-left"
    return "unknown"


def cleanup_gpio():
    """Safely release GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception:
        pass


def main():
    """Main loop: sample sensors and print steering direction."""
    if not setup_gpio():
        sys.exit(1)

    try:
        for i in range(NUM_SAMPLES):
            left_val = read_sensor(LEFT_SENSOR_PIN)
            right_val = read_sensor(RIGHT_SENSOR_PIN)

            if left_val is None or right_val is None:
                print(f"Sample {i + 1}: Error reading sensor(s). Skipping.")
                continue

            direction = determine_direction(left_val, right_val)
            print(f"Sample {i + 1}: Left={left_val} Right={right_val} -> {direction}")
            time.sleep(SAMPLE_INTERVAL)

    except KeyboardInterrupt:
        print("\nProgram stopped by user.")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

