import signal
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer

try:
    from gpiozero import LED
    from gpiozero.exc import GPIOZeroError
    _GPIO_AVAILABLE = True
except ImportError:
    _GPIO_AVAILABLE = False

LED_PIN = 17
PORT = 8080

led = None

if _GPIO_AVAILABLE:
    try:
        led = LED(LED_PIN)
    except GPIOZeroError as exc:
        print(f"Warning: could not initialize GPIO {LED_PIN}: {exc}", file=sys.stderr)
        led = None
else:
    print("Warning: gpiozero not installed; LED control disabled.", file=sys.stderr)


class RequestHandler(BaseHTTPRequestHandler):
    def _html(self, body: str) -> bytes:
        return (
            b"<html><head><title>Raspberry Pi LED Control</title></head>"
            b"<body><h1>Raspberry Pi LED Control</h1>"
            f"{body.encode('utf-8')}"
            b"</body></html>"
        )

    def do_GET(self):
        if self.path == "/":
            body = (
                b"<p>Click a link to control the LED:</p>"
                b"<ul>"
                b"<li><a href='/light_on'>Turn LED On</a></li>"
                b"<li><a href='/light_off'>Turn LED Off</a></li>"
                b"</ul>"
            )
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(self._html(body))
        elif self.path == "/light_on":
            if led is not None:
                led.on()
            body = (
                b"<p>LED is now ON</p>"
                b"<p><a href='/'>Back to Control Panel</a></p>"
            )
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(self._html(body))
        elif self.path == "/light_off":
            if led is not None:
                led.off()
            body = (
                b"<p>LED is now OFF</p>"
                b"<p><a href='/'>Back to Control Panel</a></p>"
            )
            self.send_response(200)
            self.send_header("Content-Type", "text/html; charset=utf-8")
            self.end_headers()
            self.wfile.write(self._html(body))
        else:
            self.send_response(404)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.end_headers()
            self.wfile.write(b"404 Not Found")

    def log_message(self, fmt, *args):
        sys.stderr.write("%s - %s\n" % (self.address_string(), fmt % args))


def cleanup(signum=None, frame=None):
    global led
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if signum is not None:
        sys.exit(0)


def main():
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        with HTTPServer(("0.0.0.0", PORT), RequestHandler) as httpd:
            httpd.timeout = 1.0
            print(f"Serving on 0.0.0.0:{PORT}")
            httpd.serve_forever()
    except OSError as exc:
        print(f"Error: could not bind port {PORT}: {exc}", file=sys.stderr)
        sys.exit(1)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

