import time
import json
import signal
import sys
import os
from gpiozero import LED
from gpiozero.exc import GPIOZeroError
from textblob import TextBlob

# Configuration
FEEDBACK_FILE = '/home/pi/feedback/customer_feedback.txt'
LOG_FILE = '/home/pi/logs/sentiment_log.txt'
DATA_FILE = '/home/pi/data/sentiment_data.json'
GREEN_LED_PIN = 17
RED_LED_PIN = 18
POLARITY_THRESHOLD = 0.2
CHECK_INTERVAL = 5

# Global flag for graceful shutdown
running = True

def signal_handler(signum, frame):
    global running
    running = False

def ensure_dir(f):
    d = os.path.dirname(f)
    if d and not os.path.exists(d):
        os.makedirs(d, exist_ok=True)

def log_to_file(message, filepath):
    try:
        ensure_dir(filepath)
        with open(filepath, 'a') as f:
            f.write(message + '\n')
    except IOError as e:
        print(f"Error writing to {filepath}: {e}", file=sys.stderr)

def log_sentiment(feedback, polarity, timestamp):
    log_to_file(f"{timestamp} - Feedback: {feedback}, Polarity: {polarity:.4f}", LOG_FILE)
    data = {"timestamp": timestamp, "feedback": feedback, "polarity": float(polarity)}
    try:
        ensure_dir(DATA_FILE)
        if os.path.exists(DATA_FILE):
            with open(DATA_FILE, 'r') as f:
                try:
                    existing = json.load(f)
                    if isinstance(existing, list):
                        data_list = existing
                    else:
                        data_list = [existing]
                except json.JSONDecodeError:
                    data_list = []
        else:
            data_list = []
        data_list.append(data)
        with open(DATA_FILE, 'w') as f:
            json.dump(data_list, f, indent=2)
    except (IOError, json.JSONDecodeError) as e:
        print(f"Error writing to {DATA_FILE}: {e}", file=sys.stderr)

def analyze_sentiment(feedback):
    try:
        analysis = TextBlob(feedback)
        return analysis.sentiment.polarity
    except Exception as e:
        print(f"Error analyzing sentiment: {e}", file=sys.stderr)
        return 0.0

def main():
    global running
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        green_led = LED(GREEN_LED_PIN)
        red_led = LED(RED_LED_PIN)
    except GPIOZeroError as e:
        print(f"Failed to initialize GPIO: {e}", file=sys.stderr)
        sys.exit(1)

    last_modified = 0
    try:
        while running:
            try:
                stat = os.stat(FEEDBACK_FILE)
                current_modified = stat.st_mtime
            except FileNotFoundError:
                current_modified = 0

            if current_modified > last_modified:
                try:
                    with open(FEEDBACK_FILE, 'r') as f:
                        lines = f.readlines()
                    if lines:
                        feedback = lines[-1].strip()
                        if feedback:
                            polarity = analyze_sentiment(feedback)
                            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                            log_sentiment(feedback, polarity, timestamp)
                            if polarity > POLARITY_THRESHOLD:
                                green_led.on()
                                red_led.off()
                            elif polarity < -POLARITY_THRESHOLD:
                                green_led.off()
                                red_led.on()
                            else:
                                green_led.off()
                                red_led.off()
                except IOError as e:
                    print(f"Error reading {FEEDBACK_FILE}: {e}", file=sys.stderr)
            last_modified = current_modified
            time.sleep(CHECK_INTERVAL)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        green_led.close()
        red_led.close()
        print("GPIO cleaned up. Exiting.")

if __name__ == "__main__":
    main()

