import signal
import threading
import time
import logging
from typing import Optional

try:
    import RPi.GPIO as GPIO
except ImportError:
    logging.error("RPi.GPIO library not found. Please install it: pip install RPi.GPIO")
    raise

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

VALID_OUTPUT_VALUES = (0, 1)
VALID_PIN_NUMBERS = set(range(2, 28))  # BCM GPIO 2-27 are valid on Raspberry Pi

shutdown_requested = threading.Event()


def _validate_pin_number(pin_number: int) -> None:
    if pin_number not in VALID_PIN_NUMBERS:
        raise ValueError(f"Invalid GPIO pin number: {pin_number}. Must be 2-27 for BCM mode.")


def _validate_value(value: int) -> None:
    if value not in VALID_OUTPUT_VALUES:
        raise ValueError(f"Invalid output value: {value}. Must be 0 or 1.")


def _validate_pin_name(pin_name: str) -> None:
    if not isinstance(pin_name, str) or not pin_name.strip():
        raise ValueError("Pin name must be a non-empty string.")


def _gpio_setup(pin_number: int, mode: int) -> None:
    try:
        GPIO.setup(pin_number, mode)
    except Exception as e:
        logging.error(f"Failed to setup GPIO {pin_number} as {mode}: {e}")
        raise


def _gpio_output(pin_number: int, value: int) -> None:
    try:
        GPIO.output(pin_number, value)
    except Exception as e:
        logging.error(f"Failed to output value {value} to GPIO {pin_number}: {e}")
        raise


def _gpio_cleanup(pin_number: int) -> None:
    try:
        GPIO.cleanup(pin_number)
    except Exception as e:
        logging.error(f"Failed to cleanup GPIO {pin_number}: {e}")


class OutputPin:
    def __init__(self, pin_number: int, pin_name: str, initial_value: int = 0) -> None:
        _validate_pin_number(pin_number)
        _validate_value(initial_value)
        _validate_pin_name(pin_name)

        self.pin_number = pin_number
        self.pin_name = pin_name
        self.current_value = initial_value
        self._lock = threading.Lock()

        try:
            GPIO.setmode(GPIO.BCM)
            _gpio_setup(self.pin_number, GPIO.OUT)
            _gpio_output(self.pin_number, self.current_value)
            logging.info(f"Output pin '{self.pin_name}' (GPIO {self.pin_number}) initialized to {self.current_value}")
        except Exception as e:
            logging.error(f"Failed to initialize output pin '{self.pin_name}' (GPIO {self.pin_number}): {e}")
            raise

    def set_value(self, value: int) -> None:
        _validate_value(value)
        with self._lock:
            if value != self.current_value:
                _gpio_output(self.pin_number, value)
                self.current_value = value
                logging.debug(f"Pin '{self.pin_name}' (GPIO {self.pin_number}) set to {value}")

    def get_value(self) -> int:
        with self._lock:
            return self.current_value

    def shutdown(self) -> None:
        with self._lock:
            try:
                _gpio_setup(self.pin_number, GPIO.IN)
                logging.info(f"Pin '{self.pin_name}' (GPIO {self.pin_number}) shutdown, set to input mode")
            except Exception as e:
                logging.error(f"Failed to shutdown pin '{self.pin_name}' (GPIO {self.pin_number}): {e}")

    def __repr__(self) -> str:
        return f"OutputPin(pin_number={self.pin_number}, pin_name='{self.pin_name}', current_value={self.current_value})"


class TriggerPin(OutputPin):
    def __init__(self, pin_number: int, pin_name: str, pulse_high: bool = True) -> None:
        super().__init__(pin_number, pin_name, initial_value=0)
        self.pulse_high = pulse_high
        self._trigger_lock = threading.Lock()

    def trigger(self, pulse_length: float = 0.0001) -> None:
        with self._trigger_lock:
            with self._lock:
                if self.pulse_high:
                    _gpio_output(self.pin_number, 1)
                    time.sleep(pulse_length)
                    _gpio_output(self.pin_number, 0)
                else:
                    _gpio_output(self.pin_number, 0)
