import time
import signal
import logging
import threading
import zmq

try:
    import RPi.GPIO as GPIO
    _GPIO_AVAILABLE = True
except ImportError:
    _GPIO_AVAILABLE = False

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


class PIDHandler:
    """
    Manages a PWM or digital error output and a ZeroMQ watchdog for a PID loop.

    Attributes:
        error_pin (int): Physical pin number for the error output (BOARD).
        pwm (bool): True if PWM is enabled, False for digital output.
        pwm_frequency (int): PWM frequency in Hz.
        global_err_state (bool): Current error state.
        last_msg (float): Timestamp of the last message received by the watchdog.
        logger (logging.Logger): Logger instance.
        context (zmq.Context): ZeroMQ context.
        subscriber_socket (zmq.Socket): ZeroMQ subscriber socket.
        stop_event (threading.Event): Event to signal shutdown.
        _initialized (bool): True if GPIO was successfully initialized.
    """

    def __init__(self, error_pin, pwm=True, pwm_frequency=1000, watchdog_timeout=20):
        """
        Initializes the PIDHandler.

        Args:
            error_pin (int): Physical pin number for the error output (BOARD).
            pwm (bool): True for PWM, False for digital output.
            pwm_frequency (int): PWM frequency in Hz.
            watchdog_timeout (int): Watchdog timeout in seconds.
        """
        self.error_pin = error_pin
        self.pwm = pwm
        self.pwm_frequency = pwm_frequency
        self.global_err_state = False
        self.last_msg = time.time()
        self.logger = logging.getLogger(__name__)
        self._initialized = False

        # GPIO setup
        if _GPIO_AVAILABLE:
            try:
                GPIO.setmode(GPIO.BOARD)
                GPIO.setwarnings(False)
                if self.pwm:
                    GPIO.setup(self.error_pin, GPIO.OUT)
                    self.pwm_instance = GPIO.PWM(self.error_pin, self.pwm_frequency)
                    self.pwm_instance.start(0.0)
                else:
                    GPIO.setup(self.error_pin, GPIO.OUT)
                    GPIO.output(self.error_pin, GPIO.LOW)
                self._initialized = True
                self.logger.info("GPIO initialized successfully (BOARD, pin %d, PWM=%s).", self.error_pin, self.pwm)
            except Exception as e:
                self.logger.error("Failed to initialize GPIO: %s", e)
                self._initialized = False
        else:
            self.logger.warning("RPi.GPIO not available; running in simulation mode.")
            self._initialized = False

        # ZeroMQ setup
        self.context = zmq.Context.instance()
        self.subscriber_socket = self.context.socket(zmq.SUB)
        self.subscriber_socket.setsockopt(zmq.SUBSCRIBE, b"")
        self.subscriber_socket.setsockopt(zmq.RCVTIMEO, 1000)  # 1 second timeout for non-blocking receive

    def connect(self, address):
        """Connects the subscriber socket to the given address."""
        try:
            self.subscriber_socket.connect(address)
            self.logger.info("Connected to ZeroMQ address: %s", address)
        except zmq.ZMQError as e:
            self.logger.error("Failed to connect to ZeroMQ address %s: %s", address, e)

    def add_subscription(self, topic, callback):
        """Adds a subscription to the given topic with the provided callback."""
        try:
            self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, topic)
            self.logger.info("Subscribed to topic: %s", topic)
        except zmq.ZMQError as e:
            self.logger.error("Failed to subscribe to topic %s: %s", topic, e)

    def set_error_output(self, state):
        """Sets the error output to the given state (True/False)."""
        if not self._initialized:
            self.logger.warning("GPIO not initialized; cannot set error output.")
            return
        try:
            if self.pwm:
                duty = 100.0 if state else 0.0
                self.pwm_instance.ChangeDutyCycle(duty)
            else:
                GPIO.output(self.error_pin, GPIO.HIGH if state else GPIO.LOW)
            self.global_err_state = state
            self.logger.debug("Error output set to: %s", state)
        except Exception as e:
            self.logger.error("Failed to set error output: %s", e)

    def update_error_output(self):
        """Updates the error output based on the current global_err_state."""
        self.set_error_output(self.global_err_state)

    def handle_message(self):
        """Handles incoming messages from the subscriber socket."""
        try:
            # Non-blocking receive with 1-second timeout
            msg = self.subscriber_socket.recv(flags=zmq.NOBLOCK)
            if msg is not None:
                self.last_msg = time.time()
                self.logger.debug("Received message: %s", msg)
                # Process subscription callbacks here
        except zmq.Again:
            # No message received within timeout
            if time.time() - self.last_msg > 20:
                self.logger.warning("Watchdog timeout! Setting error output to True.")
                self.set_error_output(True)
        except zmq.ZMQError as e:
            self.logger.error("Error receiving message: %s", e)
        except Exception as e:
            self.logger.error("Unexpected error in handle_message: %s", e)

    def cleanup(self):
        """Cleans up GPIO and ZeroMQ resources."""
        self.logger.info("Cleaning up resources...")
        if self._initialized:
            try:
                if self.pwm:
                    self.pwm_instance.stop()
                else:
                    GPIO.output(self.error_pin, GPIO.LOW)
                GPIO.cleanup()
                self._initialized = False
                self.logger.info("GPIO cleaned up.")
            except Exception as e:
                self.logger.error("Error during GPIO cleanup: %s", e)
        if self.subscriber_socket:
            try:
                self.subscriber_socket.close()
            except Exception as e:
                self.logger.error("Error closing subscriber socket: %s", e)
        if self.context:
            try:
                self.context.term()
            except Exception as e:
                self.logger.error("Error terminating ZeroMQ context: %s", e)


def main():
    """Main function to demonstrate the PIDHandler."""
    handler = PIDHandler(error_pin=10, pwm=False, pwm_frequency=1000, watchdog_timeout=20)

    def signal_handler(signum, frame):
        handler.logger.info("Signal %s received, shutting down...", signum)
        handler.stop_event.set()

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    handler.connect("tcp://localhost:5555")

    try:
        while not handler.stop_event.is_set():
            handler.handle_message()
            time.sleep(0.1)
    except Exception as e:
        handler.logger.error("Unexpected error in main loop: %s", e)
    finally:
        handler.cleanup()


if __name__ == "__main__":
    main()

