import time
import board
import busio
import adafruit_fingerprint


def main():
    # Initialize I2C bus on GPIO 3 (SCL) / GPIO 2 (SDA)
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Fatal: failed to initialize I2C bus: {e}")
        return

    # Initialize fingerprint sensor
    try:
        fingerprint_sensor = adafruit_fingerprint.Adafruit_Fingerprint(i2c_bus)
    except Exception as e:
        print(f"Fatal: fingerprint sensor not detected on I2C: {e}")
        i2c_bus.deinit()
        return

    # Attempt to read a template from the sensor to confirm it is responsive
    try:
        _ = fingerprint_sensor.read_templates()
    except Exception as e:
        print(f"Fatal: fingerprint sensor unresponsive: {e}")
        i2c_bus.deinit()
        return

    print("Fingerprint authentication system initialized. Press Ctrl+C to exit.")

    try:
        while True:
            try:
                # Wait for a finger to be placed on the sensor
                while True:
                    try:
                        ret = fingerprint_sensor.get_image()
                    except ValueError as e:
                        # I2C bus locked; retry after a short delay
                        print(f"I2C bus locked: {e}. Retrying...")
                        time.sleep(1)
                        continue
                    except RuntimeError as e:
                        # Sensor absent or bus error; retry after a short delay
                        print(f"Sensor error: {e}. Retrying...")
                        time.sleep(1)
                        continue

                    if ret == adafruit_fingerprint.OK:
                        break
                    elif ret == adafruit_fingerprint.NOFINGER:
                        time.sleep(0.1)
                        continue
                    else:
                        print(f"get_image() returned unexpected status: {ret}")
                        time.sleep(1)
                        continue

                # Convert the captured image to a template
                try:
                    if fingerprint_sensor.image_2_tz(1) != adafruit_fingerprint.OK:
                        print("Error converting image to template.")
                        time.sleep(1)
                        continue
                except (ValueError, RuntimeError) as e:
                    print(f"Error converting image: {e}")
                    time.sleep(1)
                    continue

                # Search the fingerprint database
                try:
                    if fingerprint_sensor.finger_search() != adafruit_fingerprint.OK:
                        print("Access Denied")
                        time.sleep(1)
                        continue
                except (ValueError, RuntimeError) as e:
                    print(f"Error searching database: {e}")
                    time.sleep(1)
                    continue

                # Access granted: print matched ID and confidence
                print(
                    f"Access Granted - ID: {fingerprint_sensor.finger_id}, "
                    f"Confidence: {fingerprint_sensor.confidence}"
                )
                time.sleep(1)

            except KeyboardInterrupt:
                print("\nExiting program.")
                break

    finally:
        # Clean up resources on every exit path
        try:
            i2c_bus.deinit()
        except Exception:
            pass
        print("Program finished.")


if __name__ == "__main__":
    main()

