import sys
import signal
import time

try:
    import RPi.GPIO as GPIO
except (ImportError, RuntimeError):
    print("RPi.GPIO is not available or the script is not running on a Raspberry Pi.", file=sys.stderr)
    sys.exit(1)

FAN_PIN = 12
PWM_FREQ = 25000

fan_pwm = None
running = True


def cleanup():
    global fan_pwm
    if fan_pwm is not None:
        try:
            fan_pwm.stop()
        except Exception:
            pass
        fan_pwm = None
    try:
        GPIO.cleanup()
    except Exception:
        pass


def handle_signal(signum, frame):
    global running
    running = False


signal.signal(signal.SIGTERM, handle_signal)

GPIO.setmode(GPIO.BCM)
GPIO.setwarnings(False)
GPIO.setup(FAN_PIN, GPIO.OUT)

try:
    try:
        fan_pwm = GPIO.PWM(FAN_PIN, PWM_FREQ)
        fan_pwm.start(0)
    except Exception as e:
        print(f"Hardware PWM unavailable on GPIO{FAN_PIN} ({e}); falling back to software PWM.", file=sys.stderr)
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)
        GPIO.setup(FAN_PIN, GPIO.OUT)
        GPIO.output(FAN_PIN, GPIO.LOW)
        fan_pwm = None

    while running:
        try:
            raw = input("Fan Speed (0-100, or 'q' to quit): ")
        except EOFError:
            break

        if raw.strip().lower() == "q":
            break

        try:
            speed = float(raw)
        except ValueError:
            print("Invalid input. Please enter a number between 0 and 100, or 'q' to quit.")
            continue

        if not (0 <= speed <= 100):
            print("Invalid speed. Please enter a value between 0 and 100.")
            continue

        if fan_pwm is not None:
            try:
                fan_pwm.ChangeDutyCycle(speed)
            except Exception as e:
                print(f"Failed to update PWM duty cycle: {e}", file=sys.stderr)
        else:
            GPIO.output(FAN_PIN, GPIO.HIGH if speed > 0 else GPIO.LOW)

except KeyboardInterrupt:
    print("\nExiting...")
finally:
    cleanup()

