import signal
import sys
import socket
import threading
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

LED_PIN = 18
HOST = "0.0.0.0"
PORT = 8000

led = None
server = None
shutdown_event = threading.Event()


def set_led(state):
    global led
    if led is not None:
        if state:
            led.on()
        else:
            led.off()


class LEDRequestHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            if self.path == "/led/on":
                set_led(True)
                body = "LED is ON"
            elif self.path == "/led/off":
                set_led(False)
                body = "LED is OFF"
            else:
                body = "Not Found"
                self.send_response(404)
                self.send_header("Content-Type", "text/plain")
                self.end_headers()
                self.wfile.write(body.encode())
                return

            self.send_response(200)
            self.send_header("Content-Type", "text/plain")
            self.end_headers()
            self.wfile.write(body.encode())
        except Exception as e:
            print(f"Error handling request: {e}", file=sys.stderr)
            try:
                self.send_response(500)
                self.send_header("Content-Type", "text/plain")
                self.end_headers()
                self.wfile.write(b"Internal Server Error")
            except Exception:
                pass

    def log_message(self, fmt, *args):
        pass


def signal_handler(signum, frame):
    print(f"Received signal {signum}, shutting down...", file=sys.stderr)
    shutdown_event.set()


def cleanup():
    global led, server
    if led is not None:
        try:
            led.close()
        except Exception:
            pass
        led = None
    if server is not None:
        try:
            server.shutdown()
        except Exception:
            pass
        server = None


def main():
    global led, server

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        from gpiozero import LED
        led = LED(LED_PIN)
    except Exception as e:
        print(f"Failed to initialize LED on GPIO{LED_PIN}: {e}", file=sys.stderr)
        sys.exit(1)

    try:
        server = ThreadingHTTPServer((HOST, PORT), LEDRequestHandler)
    except OSError as e:
        print(f"Failed to bind socket on {HOST}:{PORT}: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    print(f"Listening on {HOST}:{PORT}", file=sys.stderr)

    try:
        while not shutdown_event.is_set():
            server.handle_request()
    except Exception as e:
        print(f"Unexpected error in main loop: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

