import signal
import sys
import time

import smbus2

I2C_BUS = 1
I2C_ADDR = 0x23
MEASURE_CMD = 0x10
READ_CMD = 0x11
MEASURE_DELAY = 0.18  # datasheet: max 180 ms for high-res mode
LOOP_DELAY = 1.0

_running = True


def _handle_sigint(signum, frame):
    global _running
    _running = False


def _init_bus():
    try:
        return smbus2.SMBus(I2C_BUS)
    except FileNotFoundError:
        print(f"Error: I2C bus {I2C_BUS} not found. Enable I2C with 'sudo raspi-config'.")
        return None
    except PermissionError:
        print("Error: permission denied opening I2C bus. Run as root or add user to the 'i2c' group.")
        return None
    except OSError as e:
        print(f"Error: cannot open I2C bus {I2C_BUS}: {e}")
        return None


def _init_sensor(bus):
    try:
        bus.write_byte(I2C_ADDR, MEASURE_CMD)
        time.sleep(MEASURE_DELAY)
        return True
    except OSError as e:
        print(f"Error: no device at 0x{I2C_ADDR:02X} on bus {I2C_BUS}: {e}")
        return False


def _read_lux(bus):
    try:
        data = bus.read_i2c_block_data(I2C_ADDR, READ_CMD, 2)
        raw = (data[0] << 8) | data[1]
        return raw / 1.2
    except OSError as e:
        print(f"Warning: I2C read error: {e}")
        return None


def main():
    signal.signal(signal.SIGINT, _handle_sigint)

    bus = _init_bus()
    if bus is None:
        sys.exit(1)

    if not _init_sensor(bus):
        try:
            bus.close()
        except OSError:
            pass
        sys.exit(1)

    print("BH1750 light sensor initialized. Press Ctrl+C to stop.")

    try:
        while _running:
            lux = _read_lux(bus)
            if lux is not None:
                print(f"Ambient Light: {lux:.2f} lux")
            time.sleep(LOOP_DELAY)
    finally:
        try:
            bus.close()
        except OSError:
            pass
        print("\nProgram terminated. I2C bus closed.")


if __name__ == "__main__":
    main()

