#!/usr/bin/env python3
"""Rainbow HAT 3-bit binary counter with touchpad-driven toggling.

Touchpads A (GPIO5), B (GPIO6), and C (GPIO12) toggle bits 4, 2, and 1
respectively.  The 14-segment display shows the decimal value 0-7,
the discrete LEDs reflect the three bit states, the APA102 strip
lights a single pixel at index equal to the value (red=touch A, green=touch B,
blue=touch C) or dim white at index 0 or all white at index 7, and a 0.5 s
tone + onboard LEDs fire on each press.
"""

import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except ImportError:
    print("RPi.GPIO not available; running in degraded mode.", file=sys.stderr)
    GPIO = None

try:
    from rainbowhat import display as rh_display, led as rh_led, apa102 as rh_apa102, touch as rh_touch, buzzer as rh_buzzer, lights as rh_lights
except ImportError:
    print("Rainbow HAT libraries not available; running in degraded mode.", file=sys.stderr)
    rh_display = rh_led = rh_apa102 = rh_touch = rh_buzzer = rh_lights = None

# ---------------------------------------------------------------------------
# Pin map (BCM numbering)
# ---------------------------------------------------------------------------
TOUCH_PINS = {  # touchpad -> BCM GPIO
    "a": 5,
    "b": 6,
    "c": 12,
}
BIT_VALUES = {"a": 4, "b": 2, "c": 1}  # MSB first

DATA_PIN = 10
CLOCK_PIN = 11
BUZZER_PIN = 13
GREEN_LED_PIN = 7
BLUE_LED_PIN = 8

# ---------------------------------------------------------------------------
# Globals
# ---------------------------------------------------------------------------
bit_states = 0
_running = True


def _safe_display_clear():
    if rh_display is not None:
        try:
            rh_display.clear()
            rh_display.show()
        except Exception as exc:
            print(f"Display clear error: {exc}", file=sys.stderr)


def _safe_led_clear():
    if rh_led is not None:
        try:
            rh_led.clear()
            rh_led.show()
        except Exception as exc:
            print(f"LED clear error: {exc}", file=sys.stderr)


def _safe_apa102_clear():
    if rh_apa102 is not None:
        try:
            rh_apa102.clear_strip()
        except Exception as exc:
            print(f"APA102 clear error: {exc}", file=sys.stderr)


def _safe_buzzer_off():
    if rh_buzzer is not None:
        try:
            rh_buzzer.stop()
        except Exception as exc:
            print(f"Buzzer stop error: {exc}", file=sys.stderr)
    if rh_lights is not None:
        try:
            rh_lights.rgb(0, 0, 0)
        except Exception as exc:
            print(f"Light stop error: {exc}", file=sys.stderr)


def _safe_cleanup():
    _safe_display_clear()
    _safe_led_clear()
    _safe_apa102_clear()
    _safe_buzzer_off()


def _signal_handler(signum, frame):
    global _running
    _running = False


def _set_apa102(value):
    """Drive the APA102 strip: dim white at 0, all white at 7, single colored pixel otherwise."""
    if rh_apa102 is None:
        return
    try:
        rh_apa102.clear_strip()
        if value == 0:
            rh_apa102.set_pixel(0, 0x20, 0x20, 0x20)
        elif value == 7:
            rh_apa102.set_pixel(0, 0xFF, 0xFF, 0xFF)
        else:
            red = 0xFF if bit_states & BIT_VALUES["a"] else 0x00
            green = 0xFF if bit_states & BIT_VALUES["b"] else 0x00
            blue = 0xFF if bit_states & BIT_VALUES["c"] else 0x00
            rh_apa102.set_pixel(value, red, green, blue)
        rh_apa102.show_strip()
    except Exception as exc:
        print(f"APA102 write error: {exc}", file=sys.stderr)


def _handle_touch(channel):
    """Toggle the bit corresponding to the pressed touchpad and update all outputs."""
    global bit_states
    try:
