_running = True


def _safe_display_clear():
    if rh_display is not None:
        try:
            rh_display.clear()
            rh_display.show()
        except Exception as exc:
            print(f"Display clear error: {exc}", file=sys.stderr)


def _safe_led_clear():
    if rh_led is not None:
        try:
            rh_led.clear()
            rh_led.show()
        except Exception as exc:
            print(f"LED clear error: {exc}", file=sys.stderr)


def _safe_apa102_clear():
    if rh_apa102 is not None:
        try:
