                        1 if bit_states & BIT_VALUES["b"] else 0,
                        1 if bit_states & BIT_VALUES["c"] else 0,
                    )
                except Exception as exc:
                    print(f"Light RGB error: {exc}", file=sys.stderr)

    except Exception as exc:
        print(f"Touch handler error: {exc}", file=sys.stderr)


def _setup_gpio():
