        except Exception as exc:
            print(f"Touch setup error on pin {pin}: {exc}", file=sys.stderr)


def _cleanup_gpio():
    if GPIO is not None:
        try:
            GPIO.cleanup()
        except Exception:
            pass


def main():
    global _running

    _setup_gpio()
    _setup_touch()

    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    print("Rainbow HAT binary counter running. Press Ctrl+C to exit.")

