def _signal_handler(signum, frame):
    global _running
    logging.info(f"Signal {signum} received, shutting down...")
    _running = False


class ChassisController:
    def __init__(self, left_forward_pin, left_backward_pin, right_forward_pin, right_backward_pin,
                 enable_a_pin, enable_b_pin):
        self.left_motor = None
        self.right_motor = None
        self.chassis = None
        self.enable_a = None
        self.enable_b = None
        try:
            self.left_motor = DigitalOutputDevice(left_forward_pin)
            self.left_backward = DigitalOutputDevice(left_backward_pin)
            self.right_motor = DigitalOutputDevice(right_forward_pin)
            self.right_backward = DigitalOutputDevice(right_backward_pin)
            self.enable_a = DigitalOutputDevice(enable_a_pin)
            self.enable_b = DigitalOutputDevice(enable_b_pin)
            self.enable_a.on()
            self.enable_b.on()
            self.chassis = chasis.Chassis(self.left_motor, self.left_backward, self.right_motor, self.right_backward)
            logging.info("Chassis controller initialized successfully.")
        except Exception as e:
            logging.error(f"Error initializing chassis controller: {e}")
            self.cleanup()
            raise

    def drive_forward(self, speed_fraction):
        try:
            self.chassis.forward(speed_fraction)
            logging.info(f"Driving forward at speed {speed_fraction}")
        except Exception as e:
            logging.error(f"Error driving forward: {e}")
            self.stop_all()

    def turn_left(self, speed_fraction):
        try:
            self.chassis.left(speed_fraction)
            logging.info(f"Turning left at speed {speed_fraction}")
        except Exception as e:
            logging.error(f"Error turning left: {e}")
            self.stop_all()

    def stop_all(self):
        try:
            self.chassis.stop()
            logging.info("All motors stopped.")
        except Exception as e:
            logging.error(f"Error stopping motors: {e}")

    def cleanup(self):
        try:
            self.stop_all()
        except Exception:
            pass
        for dev in (self.left_motor, self.left_backward, self.right_motor, self.right_backward,
                    self.enable_a, self.enable_b):
