    elif tilt_angle < -TILT_THRESHOLD:
        controller.drive_forward(speed_fraction)
    else:
        controller.stop_all()


def main():
    global _running
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    controller = None
    try:
        controller = ChassisController(LEFT_MOTOR_FORWARD_PIN, LEFT_MOTOR_BACKWARD_PIN,
                                       RIGHT_MOTOR_FORWARD_PIN, RIGHT_MOTOR_BACKWARD_PIN,
                                       ENABLE_A_PIN, ENABLE_B_PIN)
        tilt_angles = [25, -25, 0, 30, -15, 40, -30, 10]
