import random
import time
import signal
import sys
from gpiozero import LED
from gpiozero.exc import GPIOZeroError, GPIODeviceError

# Constants
LED_PIN = 18
NUM_READINGS = 5
DELAY_SECONDS = 2
FAILURE_PROBABILITY = 0.1
LED_THRESHOLD = 50

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def read_water_quality():
    """Simulates reading water quality data (0-100 percentage)."""
    if random.random() < FAILURE_PROBABILITY:
        return None
    return random.randint(0, 100)


def control_led(led, water_quality):
    """Controls the LED based on water quality percentage."""
    if water_quality < LED_THRESHOLD:
        led.on()
        print(f"Water quality: {water_quality}% - LED ON (Low Quality)")
    else:
        led.off()
        print(f"Water quality: {water_quality}% - LED OFF (Normal Quality)")


def main():
    """Main function to simulate water quality monitoring."""
    global _running

    # Register signal handlers for clean shutdown
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    led = None
    try:
        # Initialize LED with error handling
        try:
            led = LED(LED_PIN, initial_value=False)
        except (GPIOZeroError, GPIODeviceError) as e:
            print(f"Error: Failed to initialize GPIO pin {LED_PIN}: {e}")
            sys.exit(1)
        except Exception as e:
            print(f"Unexpected error during GPIO setup: {e}")
            sys.exit(1)

        readings_taken = 0
        while _running and readings_taken < NUM_READINGS:
            water_quality = read_water_quality()

            if water_quality is None:
                print("Error: Sensor read failed. Retrying...")
                water_quality = read_water_quality()
                if water_quality is None:
                    print("Error: Sensor read failed after retry. Skipping reading.")
                else:
                    print(f"Sensor read recovered. Water quality: {water_quality}%")
            else:
                print(f"Water quality: {water_quality}%")

            if water_quality is not None:
                control_led(led, water_quality)
                readings_taken += 1

            if readings_taken < NUM_READINGS and _running:
                time.sleep(DELAY_SECONDS)

        if not _running:
            print("\nShutdown requested. Exiting gracefully.")
        else:
            print("Water quality monitoring completed.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean resource release on all exit paths
        if led is not None:
            try:
                led.close()
                print("GPIO cleanup completed.")
            except Exception as e:
                print(f"Error during GPIO cleanup: {e}")


if __name__ == "__main__":
    main()

