import signal
import sys
import time
import threading
from typing import Optional, Tuple

try:
    import serial
    from serial import SerialException
except ImportError:
    serial = None
    SerialException = Exception

# Configuration
LISTEN_IP = "127.0.0.1"
LISTEN_PORT = 9099
GPS_PORT = "/dev/serial0" if serial else "/dev/ttyAMA0"
GPS_BAUDRATE = 9600
GPS_TIMEOUT = 2.0

# Global state
gps_lock = threading.Lock()
gps_data = {"lat": None, "lon": None}
gps_running = False
uart: Optional[serial.Serial] = None
server_socket: Optional[socket.socket] = None
shutdown_flag = threading.Event()


def read_gps_position() -> Tuple[Optional[float], Optional[float]]:
    """Read GPS coordinates from the UART. Returns (lat, lon) or (None, None)."""
    global gps_data
    if not gps_running:
        return None, None
    if not gps_data["lat"] and not gps_data["lon"]:
        return None, None
    return gps_data["lat"], gps_data["lon"]


def handle_command(command: str) -> str:
    """Process a command received from a client."""
    global gps_running
    if command == "start":
        gps_running = True
        return "Tracking started"
    elif command == "stop":
        gps_running = False
        return "Tracking stopped"
    elif command == "report":
        lat, lon = read_gps_position()
        if lat is None or lon is None:
            return json.dumps({"error": "No GPS data available"})
        return json.dumps({"lat": lat, "lon": lon})
    else:
        return "Invalid command"


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    print(f"\nReceived signal {signum}, shutting down...", file=sys.stderr)
    shutdown_flag.set()


def cleanup():
    """Release all resources."""
    global uart, server_socket
    if server_socket is not None:
        try:
            server_socket.close()
        except Exception:
            pass
        server_socket = None
    if uart is not None:
        try:
            uart.close()
        except Exception:
            pass
        uart = None


def main():
    global uart, server_socket

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize UART for GPS (optional)
    if serial is not None:
        try:
            uart = serial.Serial(GPS_PORT, GPS_BAUDRATE, timeout=GPS_TIMEOUT)
            print(f"GPS UART initialized on {GPS_PORT}", file=sys.stderr)
        except SerialException as e:
            print(f"Warning: Could not open GPS UART: {e}", file=sys.stderr)
            uart = None
    else:
        print("Warning: pyserial not installed; GPS disabled.", file=sys.stderr)

    # Initialize server socket
    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server_socket.bind((LISTEN_IP, LISTEN_PORT))
        server_socket.listen(1)
        server_socket.settimeout(1.0)
        print(f"Server listening on {LISTEN_IP}:{LISTEN_PORT}", file=sys.stderr)
    except socket.error as e:
        print(f"Socket error: {e}", file=sys.stderr)
        cleanup()
        sys.exit(1)

    try:
        while not shutdown_flag.is_set():
            try:
                client_sock, client_addr = server_socket.accept()
                print(f"Connection from {client_addr}", file=sys.stderr)
            except socket.timeout:
                continue
            except socket.error as e:
                if not shutdown_flag.is_set():
                    print(f"Accept error: {e}", file=sys.stderr)
                continue

            try:
                data = client_sock.recv(1024).decode("utf-8").strip()
                if not data:
                    client_sock.sendall(b"Invalid command\n")
                    continue

                print(f"Received: {data}", file=sys.stderr)
                response = handle_command(data)
                client_sock.sendall((response + "\n").encode("utf-8"))
            except socket.error as e:
                print(f"Socket error during communication: {e}", file=sys.stderr)
            except Exception as e:
                print(f"Error processing command: {e}", file=sys.stderr)
                try:
                    client_sock.sendall(b"Internal server error\n")
                except Exception:
                    pass
            finally:
                client_sock.close()

    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        cleanup()


if __name__ == "__main__":
    main()

