import signal
import sys
import time

try:
    import RPi.GPIO as GPIO
except RuntimeError:
    print("Error: RPi.GPIO requires root privileges or is not available on this platform.", file=sys.stderr)
    sys.exit(1)
except ImportError:
    print("Error: RPi.GPIO is not installed. Install with: pip install RPi.GPIO", file=sys.stderr)
    sys.exit(1)

# GPIO pin definitions (BCM numbering)
LED_1_PIN = 18
LED_2_PIN = 23

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT (Ctrl+C) for graceful shutdown."""
    global _running
    _running = False


def setup_gpio():
    """Initialize GPIO pins for the two LEDs."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setwarnings(False)
    for pin in (LED_1_PIN, LED_2_PIN):
        try:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
        except Exception as e:
            raise RuntimeError(f"Failed to initialize GPIO{pin}: {e}") from e


def set_leds(state):
    """Set the state (on/off) of both LEDs simultaneously."""
    for pin in (LED_1_PIN, LED_2_PIN):
        try:
            GPIO.output(pin, GPIO.HIGH if state else GPIO.LOW)
        except Exception as e:
            raise RuntimeError(f"Failed to set GPIO{pin} to {'HIGH' if state else 'LOW'}: {e}") from e


def toggle_leds(duration=1.0, cycles=5):
    """Toggle both LEDs on and off for the specified duration and number of cycles."""
    global _running
    for i in range(cycles):
        if not _running:
            break
        set_leds(True)
        time.sleep(duration)
        if not _running:
            break
        set_leds(False)
        time.sleep(duration)


def cleanup_gpio():
    """Clean up GPIO resources safely."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Warning: GPIO cleanup encountered an error: {e}", file=sys.stderr)


def main():
    """Main entry point: setup, toggle LEDs, and ensure cleanup."""
    global _running
    _running = True

    signal.signal(signal.SIGINT, _signal_handler)

    try:
        setup_gpio()
        print("LED toggle sequence started (5 cycles, 1s on / 1s off).")
        toggle_leds(duration=1.0, cycles=5)
        print("LED toggle sequence completed.")
    except RuntimeError as e:
        print(f"Runtime error: {e}", file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
        sys.exit(1)
    finally:
        cleanup_gpio()


if __name__ == "__main__":
    main()

