SIPHON_STEPS = 10
DELAY = 0.002

# Global state
_running = True


def setup_gpio():
    """Initialize GPIO pins for both motors."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in MOTOR1_PINS + MOTOR2_PINS:
            GPIO.setup(pin, GPIO.OUT, initial=GPIO.LOW)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)


def set_motor_pins(motor_number, step):
    """Set the four motor pins according to the step pattern."""
    if motor_number == 1:
        pins = MOTOR1_PINS
    elif motor_number == 2:
        pins = MOTOR2_PINS
    else:
        raise ValueError("Invalid motor number. Must be 1 or 2.")
    for pin, val in zip(pins, step):
        GPIO.output(pin, val)


def move_motor(motor_number, steps, direction):
    """Move a stepper motor by a given number of steps.

    direction: 'forward' or 'backward'.
    """
    if direction not in ('forward', 'backward'):
        raise ValueError("direction must be 'forward' or 'backward'")
    sequence = STEP_SEQUENCE if direction == 'forward' else STEP_SEQUENCE[::-1]
    for _ in range(steps):
        for step in sequence:
            set_motor_pins(motor_number, step)
            time.sleep(DELAY)


def adjust_bed(motor_number, angle_degrees):
    """Adjust the bed by a given angle (degrees) using Motor1 or Motor2.

    angle_degrees: 1-30 degrees.
    """
    if motor_number not in (1, 2):
        raise ValueError("Invalid motor number. Must be 1 or 2.")
    if not 1 <= angle_degrees <= 30:
        raise ValueError("Angle must be between 1 and 30 degrees.")
    steps = int(angle_degrees * STEPS_PER_DEGREE)
    move_motor(motor_number, steps, 'forward')
    # Backlash compensation
    move_motor(motor_number, BACKLASH_STEPS, 'backward')


def dispense_medication(motor_number, dose_ml):
    """Dispense a given dose (ml) using Motor1 or Motor2.

    dose_ml: 1-10 ml.
    """
    if motor_number not in (1, 2):
        raise ValueError("Invalid motor number. Must be 1 or 2.")
    if not 1 <= dose_ml <= 10:
        raise ValueError("Dose must be between 1 and 10 ml.")
    steps = int(dose_ml * STEPS_PER_ML)
    move_motor(motor_number, steps, 'forward')
    # Prevent siphoning
    move_motor(motor_number, SIPHON_STEPS, 'backward')


def read_heart_rate():
    """Simulate reading heart rate (60-100 bpm)."""
    return random.randint(60, 100)


def read_spo2():
    """Simulate reading SpO2 (95-99 %)."""
    return random.randint(95, 99)


def run_schedule(head_angle, foot_angle, dose_A, dose_B, interval_seconds):
    """Run the bed adjustment and medication dispensing schedule once."""
    global _running
    if not _running:
        return
    try:
        adjust_bed(1, head_angle)
        adjust_bed(2, foot_angle)
        dispense_medication(1, dose_A)
        dispense_medication(2, dose_B)
        heart_rate = read_heart_rate()
        spo2 = read_spo2()
        print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2}%")
    except ValueError as e:
        print(f"Invalid input: {e}")
    except Exception as e:
        print(f"Error during run_schedule: {e}")


def cleanup():
    """Clean up GPIO resources."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"GPIO cleanup error: {e}")


def signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for graceful shutdown."""
    global _running
    _running = False


def main():
    """Main entry point."""
    import signal
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    setup_gpio()
    try:
        while _running:
            run_schedule(15, 10, 5, 3, 120)
            if _running:
                time.sleep(1)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup()
        print("GPIO cleaned up. Exiting.")


if __name__ == "__main__":
    main()

