    except (GPIOZeroError, GPIODeviceError) as e:
        print(f"Error initializing GPIO: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error initializing GPIO: {e}", file=sys.stderr)
        return None


def lock_door(lock):
    if lock is None:
        return
    try:
        lock.off()
        print("Door locked.")
    except Exception as e:
        print(f"Error locking door: {e}", file=sys.stderr)


def unlock_door(lock):
    if lock is None:
        return
    try:
        lock.on()
        print("Door unlocked.")
    except Exception as e:
        print(f"Error unlocking door: {e}", file=sys.stderr)


