                time.sleep(UNLOCK_DURATION)
                lock_door(_lock)
            time.sleep(LOOP_DELAY)
    except Exception as e:
        print(f"Runtime error: {e}", file=sys.stderr)
    finally:
        lock_door(_lock)
        if _lock is not None:
            _lock.close()
        print("GPIO cleanup completed. Exiting.")


if __name__ == "__main__":
    main()

