import sys

RELAY_PIN = 17
SUNRISE_TIME = datetime.time(7, 0, 0)
SUNSET_TIME = datetime.time(19, 0, 0)


def setup_gpio():
    """Initialize GPIO and set the relay pin as an output, HIGH (de-energized)."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(RELAY_PIN, GPIO.OUT, initial=GPIO.HIGH)
    except RuntimeError as exc:
        print(f"Error: GPIO setup failed - {exc}", file=sys.stderr)
        sys.exit(1)


def set_door_state(open_door):
    """Energize the relay (LOW) to open the door, de-energize (HIGH) to close it."""
    GPIO.output(RELAY_PIN, GPIO.LOW if open_door else GPIO.HIGH)
    print(f"Door {'OPENED' if open_door else 'CLOSED'}")


def main():
    setup_gpio()
    print("Coop door controller started. Press Ctrl+C to exit.")

    try:
        while True:
            now = datetime.datetime.now().time()
            open_door = SUNRISE_TIME <= now <= SUNSET_TIME

            if open_door:
                set_door_state(True)
            elif not open_door:
                set_door_state(False)

            time.sleep(60)

    except KeyboardInterrupt:
        print("\nExiting program (KeyboardInterrupt).")
    except Exception as exc:
        print(f"Unexpected error: {exc}", file=sys.stderr)
    finally:
        GPIO.cleanup()
        print("GPIO cleanup completed.")


if __name__ == "__main__":
    main()

