    def cleanup(self):
        """Releases all GPIO resources."""
        if self._initialized:
            try:
                self.stop_all_motors()
            except Exception:
                pass
            try:
                GPIO.cleanup()
                logging.info("GPIO cleanup completed.")
            except Exception as e:
                logging.error(f"Error during GPIO cleanup: {e}")
            finally:
                self._initialized = False

    def _shift_out(self, value):
        """Shifts out a byte to the 74HC595 shift register."""
        for i in range(8):
            GPIO.output(self.clock_pin, GPIO.LOW)
            GPIO.output(self.data_pin, GPIO.HIGH if (value >> i) & 0x01 else GPIO.LOW)
            GPIO.output(self.clock_pin, GPIO.HIGH)

    def set_dir(self, motor_num, value):
        """Sets the direction register of the shift register for the specified motor."""
        if not 1 <= motor_num <= 2:
            raise ValueError("Motor number must be 1 or 2.")
        if not 0 <= value <= 255:
            raise ValueError("Direction value must be between 0 and 255.")

        try:
            GPIO.output(self.latch_pin, GPIO.LOW)
            self._shift_out(value)
            GPIO.output(self.latch_pin, GPIO.HIGH)
        except Exception as e:
            logging.error(f"Error setting direction for motor {motor_num}: {e}")
            raise

    def get_pwm_pin(self, motor_num):
        """Returns the PWM pin for the specified motor."""
        if motor_num == 1:
            return self.pwm1_pin
        elif motor_num == 2:
            return self.pwm2_pin
        else:
            raise ValueError("Motor number must be 1 or 2.")

    def add_motor(self, motor_num, directions):
        """Adds a motor to the shield."""
        if not 1 <= motor_num <= 2:
            raise ValueError("Motor number must be 1 or 2.")
        if self.motors[motor_num - 1] is not None:
            raise RuntimeError(f"Motor {motor_num} has already been added.")

        self.motors[motor_num - 1] = Motor(motor_num, directions, self)
        return self.motors[motor_num - 1]

    def stop_all_motors(self):
        """Stops all motors."""
        for motor in self.motors:
            if motor is not None:
                try:
                    motor.stop()
                except Exception as e:
                    logging.error(f"Error stopping motor: {e}")


def signal_handler(sig, frame):
    """Handles SIGINT/SIGTERM for graceful shutdown."""
    logging.info("Signal received, stopping motors and cleaning up...")
    if 'shield' in globals() and shield is not None:
        shield.cleanup()
    sys.exit(0)


if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    shield = None
    try:
        with MotorShield(
            latch_pin=11,
            clock_pin=9,
            data_pin=10,
            pwm1_pin=13,
            pwm2_pin=12
        ) as shield:
            motor_1 = shield.add_motor(1, [0b00000010, 0b00000001, 0b00000000])
            motor_2 = shield.add_motor(2, [0b00001000, 0b00000100, 0b00000000])

            motor_1.start(0)  # CW
            motor_1.change_duty_cycle(75)
            motor_2.start(1)  # CCW
            motor_2.change_duty_cycle(50)

            time.sleep(5)

            motor_1.change_duty_cycle(25)

            time.sleep(5)

            shield.stop_all_motors()
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if shield is not None:
            shield.cleanup()

