import driver


class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


class Motor:
    """
    Controls a DC motor via a driver library.pi instance on a Raspberry Pi.

    The driver library is expected to expose set_pwm_frequency and
    set_pwm_duty_cycle, returning 0 on success and a non-zero error code
    on failure.  The duty-cycle value is an integer in [0, 255].
    """

    def __init__(self, driver_instance, pin):
        """
        Initialise the motor.

        Args:
            driver_instance:  Connected driver library.pi instance.
            pin:              BCM pin number connected to the driver PWM input.
        """
        if driver_instance is None:
            raise MotorError("driver_instance must not be None")
        try:
            self._driver = driver_instance
            self._pin = pin
            self._driver.set_pin_mode(self._pin, driver.OUTPUT)
            self.set_frequency(1000)
            self.stop()
        except Exception as exc:
            raise MotorError(f"Failed to initialise motor on pin {pin}: {exc}") from exc

    def set_frequency(self, freq):
        """Set the PWM frequency in Hz."""
        try:
            result = self._driver.set_pwm_frequency(self._pin, freq)
            if result != 0:
                raise MotorError(
                    f"set_pwm_frequency failed on pin {self._pin} "
                    f"(error code {result})"
                )
        except Exception as exc:
            raise MotorError(f"set_pwm_frequency failed: {exc}") from exc

    def set_duty_cycle(self, duty):
        """
        Set the duty cycle (0-255).

        Raises:
            MotorError: If the value is out of range or the driver call fails.
        """
        if not isinstance(duty, (int, float)):
            raise MotorError("duty must be numeric")
        if not 0 <= duty <= 255:
            raise MotorError("duty must be between 0 and 255")
        try:
            result = self._driver.set_pwm_duty_cycle(self._pin, int(duty))
            if result != 0:
                raise MotorError(
                    f"set_pwm_duty_cycle failed on pin {self._pin} "
                    f"(error code {result})"
                )
        except Exception as exc:
            raise MotorError(f"set_pwm_duty_cycle failed: {exc}") from exc

    def stop(self):
        """Stop the motor by setting the duty cycle to 0."""
        self.set_duty_cycle(0)

    def close(self):
        """Explicitly stop the motor and release resources."""
        try:
            self.stop()
        except Exception:
            pass

    def __del__(self):
        """Destructor: stop the motor on object destruction."""
        try:
            self.stop()
        except Exception:
            pass

