import time
import logging
import signal
import sys

try:
    import RPi.GPIO as GPIO
    from gpio_servo import Servo
except ImportError as exc:
    print(f"Missing required library: {exc.name}", file=sys.stderr)
    print("Install with: pip install RPi.GPIO gpio_servo", file=sys.stderr)
    sys.exit(1)

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s",
)

SERVO_GPIO_PIN = 18
PWM_FREQUENCY = 50
STEP_DELAY = 0.5


class ServoController:
    """Controls a servo motor connected to a Raspberry Pi GPIO pin."""

    def __init__(self, gpio_pin, pwm_frequency):
        self.gpio_pin = gpio_pin
        self.pwm_frequency = pwm_frequency
        self.servo = None
        self._initialized = False

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pin, GPIO.OUT)
            self.servo = Servo(self.gpio_pin, freq=self.pwm_frequency)
            self._initialized = True
            logging.info(
                "Servo controller initialized on GPIO %d at %d Hz.",
                self.gpio_pin,
                self.pwm_frequency,
            )
        except Exception as e:
            logging.error("Failed to initialize servo controller: %s", e)
            self.cleanup()
            raise

    def _angle_to_duty_cycle(self, angle):
        """Converts an angle (0-180) to a duty cycle percentage."""
        if not 0 <= angle <= 180:
            raise ValueError(f"Angle must be between 0 and 180, got {angle}")
        return 2.5 + (angle / 180.0) * 10.0

    def move_to(self, angle):
        """Moves the servo to the specified angle."""
        if not self._initialized:
            raise RuntimeError("Servo controller not initialized.")
        if not 0 <= angle <= 180:
            raise ValueError("Angle must be between 0 and 180 degrees.")

        try:
            duty = self._angle_to_duty_cycle(angle)
            self.servo.set_duty(duty)
            logging.info("Servo moved to %d degrees (duty=%.2f%%)", angle, duty)
        except Exception as e:
            logging.error("Failed to move servo to %d degrees: %s", angle, e)
            raise

    def stop(self):
        """Stops the servo motor."""
        if self._initialized:
            try:
                self.servo.set_duty(0)
                logging.info("Servo stopped (duty=0%).")
            except Exception as e:
                logging.error("Failed to stop servo: %s", e)
        else:
            logging.warning("Servo controller not initialized; cannot stop.")

    def cleanup(self):
        """Releases GPIO resources and stops the servo."""
        if self._initialized:
            try:
                self.stop()
            except Exception:
                pass
            self._initialized = False
        try:
            GPIO.cleanup()
            logging.info("GPIO cleanup completed.")
        except Exception as e:
            logging.error("Error during GPIO cleanup: %s", e)


def run_servo_sweep(controller, angles):
    """Executes a sequence of servo movements."""
    for angle in angles:
        controller.move_to(angle)
        time.sleep(STEP_DELAY)


def main():
    servo_controller = None
    try:
        servo_controller = ServoController(SERVO_GPIO_PIN, PWM_FREQUENCY)

        sweep_sequence = [0, 45, 90, 135, 180]
        logging.info("Starting servo sweep: %s", sweep_sequence)

        run_servo_sweep(servo_controller, sweep_sequence)
        run_servo_sweep(servo_controller, sweep_sequence[::-1])

        logging.info("Servo sweep completed successfully.")

    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error("An unexpected error occurred: %s", e)
    finally:
        if servo_controller is not None:
            servo_controller.cleanup()


if __name__ == "__main__":
    main()

