import logging
import signal
import struct
import time
from typing import Any, Dict, List, Optional, Tuple

import serial
import serial.tools.list_ports

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

# Constants for Modbus function codes
FC_READ_HOLDING_REGISTERS = 0x03
FC_WRITE_SINGLE_REGISTER = 0x06
FC_WRITE_MULTIPLE_REGISTERS = 0x10
FC_REPORT_SLAVE_ID = 0x11

# Constants for register map
REGISTERS = {
    "Status": {"R/W": "R", "Register": "0000", "functioncode": FC_READ_HOLDING_REGISTERS},
    "Position": {"R/W": "R", "Register": "0001", "functioncode": FC_READ_HOLDING_REGISTERS},
    "Speed": {"R/W": "R", "Register": "0002", "functioncode": FC_READ_HOLDING_REGISTERS},
    "Torque": {"R/W": "R", "Register": "0003", "functioncode": FC_READ_HOLDING_REGISTERS},
    "Temperature": {"R/W": "R", "Register": "0004", "functioncode": FC_READ_HOLDING_REGISTERS},
    "Error": {"R/W": "R", "Register": "0005", "functioncode": FC_READ_HOLDING_REGISTERS},
    "Setpoint": {"R/W": "W", "Register": "0006", "functioncode": FC_WRITE_SINGLE_REGISTER},
    "Gain": {"R/W": "W", "Register": "0007", "functioncode": FC_WRITE_SINGLE_REGISTER},
    "Bias": {"R/W": "W", "Register": "0008", "functioncode": FC_WRITE_SINGLE_REGISTER},
    "Mode": {"R/W": "W", "Register": "0009", "functioncode": FC_WRITE_SINGLE_REGISTER},
    "MaxSpeed": {"R/W": "W", "Register": "0010", "functioncode": FC_WRITE_SINGLE_REGISTER},
    "MaxTorque": {"R/W": "W", "Register": "0011", "functioncode": FC_WRITE_SINGLE_REGISTER},
    "MinPosition": {"R/W": "W", "Register": "0012", "functioncode": FC_WRITE_MULTIPLE_REGISTERS},
    "MaxPosition": {"R/W": "W", "Register": "0013", "functioncode": FC_WRITE_MULTIPLE_REGISTERS},
}

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum: int, frame: Any) -> None:
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False
    logging.info("Shutdown signal received. Cleaning up...")


class ModbusRtuError(Exception):
    """Base class for Modbus RTU exceptions."""
    pass


class ModbusIOException(ModbusRtuError):
    """Raised when an I/O error occurs during communication."""
    pass


class ModbusCRCError(ModbusRtuError):
    """Raised when a CRC error is detected."""
    pass


class ModbusInvalidResponseError(ModbusRtuError):
    """Raised when the Modbus response is invalid."""
    pass


def calculate_crc(data: bytes) -> int:
    """Calculate Modbus RTU CRC-16."""
    crc = 0xFFFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            if crc & 0x0001:
                crc = (crc >> 1) ^ 0xA001
            else:
                crc >>= 1
    return crc & 0xFFFF


def verify_crc(data: bytes, received_crc: int) -> None:
    """Verify CRC of received data."""
    calculated_crc = calculate_crc(data)
    if calculated_crc != received_crc:
        raise ModbusCRCError(
            f"CRC mismatch: calculated=0x{calculated_crc:04X}, received=0x{received_crc:04X}"
        )


def build_request(
    slave_id: int,
    function_code: int,
    register_address: int,
    quantity: int = 1,
    value: int = 0,
) -> bytes:
    """Build a Modbus RTU request frame."""
    if function_code in (FC_WRITE_SINGLE_REGISTER, FC_WRITE_MULTIPLE_REGISTERS):
        # Single register: 2 bytes, Multi register: 2 + 2*quantity bytes
        payload_length = 2 + 2 * quantity
        data = struct.pack('>BBHH', slave_id, function_code, register_address, value)
    elif function_code == FC_READ_HOLDING_REGISTERS:
        data = struct.pack('>BBHH', slave_id, function_code, register_address, quantity)
        payload_length = 4
    else:
        raise ModbusRtuError(f"Unsupported function code: {function_code}")

    crc = calculate_crc(data)
    return data + struct.pack('<H', crc)


def parse_response(
    slave_id: int,
    response: bytes,
) -> Tuple[int, int, int, int]:
    """Parse a Modbus RTU response frame."""
    if len(response) < 5:
        raise ModbusInvalidResponseError(f"Response too short: {len(response)} bytes")

    received_slave_id = response[0]
    function_code = response[1]

    if received_slave_id != slave_id:
        raise ModbusInvalidResponseError(
            f"Slave ID mismatch: expected {slave_id}, got {received_slave_id}"
        )

    if function_code & 0x80:
        error_code = response[2] if len(response) > 2 else 0
        raise ModbusInvalidResponseError(
            f"Modbus exception: function code=0x{function_code:02X}, error code=0x{error_code:02X}"
        )

    if function_code == FC_READ_HOLDING_REGISTERS:
        if len(response) < 5:
            raise ModbusInvalidResponseError("Read response too short")
        byte_count = response[2]
        if len(response) < 5 + (byte_count // 2):
            raise ModbusInvalidResponseError("Read response truncated")
        # response[3:5] is the CRC field
        data = response[5:-2]
        if len(data) % 2 != 0:
            raise ModbusInvalidResponseError("Read response data length is not even")
        registers = []
        for i in range(0, len(data), 2):
            registers.append(struct.unpack('>H', data[i:i+2])[0])
        return function_code, byte_count, 0, registers
    elif function_code in (FC_WRITE_SINGLE_REGISTER, FC_WRITE_MULTIPLE_REGISTERS):
        if len(response) < 8:
            raise ModbusInvalidResponseError("Write response too short")
        # response[3:5] is the CRC field
        register_address = struct.unpack('>H', response[3:5])[0]
        value = struct.unpack('>H', response[5:7])[0]
        return function_code, register_address, value, None
    else:
        raise ModbusInvalidResponseError(f"Unsupported function code: 0x{function_code:02X}")


def _open_serial_port(
    port: str = '/dev/serial0',
    baudrate: int = 115200,
    timeout: float = 1.0,
) -> Optional[serial.Serial]:
    """Open a serial port with error handling."""
    try:
        ser = serial.Serial(
            port=port,
            baudrate=baudrate,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=timeout,
            write_timeout=timeout,
        )
        logging.info(f"Opened serial port {port} at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        logging.warning(f"Could not open serial port {port}: {e}")
        return None
    except Exception as e:
        logging.warning(f"Unexpected error opening {port}: {e}")
        return None


def _close_serial_port(ser: Optional[serial.Serial]) -> None:
    """Safely close a serial port."""
    if ser is not None and ser.is_open:
        try:
            ser.close()
            logging.info("Serial port closed.")
        except Exception as e:
            logging.warning(f"Error closing serial port: {e}")


def _send_and_receive(
    ser: Optional[serial.Serial],
    request: bytes,
) -> Optional[bytes]:
    """Send a request and receive a response with error handling."""
    if ser is None or not ser.is_open:
        logging.warning("Serial port is not open. Cannot send request.")
        return None

    try:
        ser.reset_input_buffer()
        ser.reset_output_buffer()
        ser.write(request)
        ser.flush()
        response = ser.read(len(request))
        if len(response) < len(request):
            logging.warning(
                f"Incomplete response: expected {len(request)} bytes, got {len(response)}"
            )
            return None
        return response
    except serial.SerialTimeoutException as e:
        logging.warning(f"Write timeout on serial port: {e}")
        return None
    except serial.SerialException as e:
        logging.warning(f"Serial I/O error: {e}")
        return None
    except Exception as e:
        logging.warning(f"Unexpected error during communication: {e}")
        return None


class ServoMotorController:
    """
    A class to interact with a Modbus RTU servo motor controller over UART.

    Provides methods for reading and writing to holding registers,
    as well as handling potential errors and timeouts.
    """

    def __init__(
        self,
        port: str = '/dev/serial0',
        baudrate: int = 115200,
        timeout: float = 1.0,
        slave_id: int = 1,
    ):
