            function_code=FC_READ_HOLDING_REGISTERS,
        )
        if response is None:
            return None

        try:
            _, _, _, registers = parse_response(self.slave_id, response)
            return registers
        except ModbusInvalidResponseError as e:
            logging.warning(f"Invalid response: {e}")
            return None

    def write_register(
        self,
