from typing import Optional

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

class GSMModule:
    def __init__(self, port: str = '/dev/serial0', baudrate: int = 115200, timeout: float = 2.0, power_pin: Optional[int] = 4):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self._serial: Optional[serial.Serial] = None
        self._power_pin = power_pin
        self._closed = False

        try:
            import RPi.GPIO as GPIO
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self._power_pin, GPIO.OUT, initial=GPIO.LOW)
            self._gpio = GPIO
        except ImportError:
            logging.warning("RPi.GPIO not available; power control disabled.")
            self._gpio = None

        self._initialize_serial()
        self._power_on_module()
        self._wait_for_network()
        self._verify_module()

    def _initialize_serial(self) -> None:
        try:
            self._serial = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                timeout=self.timeout
            )
            logging.info(f"Serial port {self.port} opened at {self.baudrate} baud.")
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            raise

    def _power_on_module(self) -> None:
        if self._gpio is None:
            logging.warning("Power control unavailable; assuming module is already powered.")
