import signal
import sys
import json
from http.server import BaseHTTPRequestHandler, HTTPServer
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

RELAY_PIN = 23
SERVER_ADDRESS = ('0.0.0.0', 5000)

relay = None

def cleanup(signum=None, frame=None):
    global relay
    if relay is not None:
        try:
            relay.close()
        except Exception:
            pass
        relay = None
    if signum is not None:
        sys.exit(0)

def handle_relay_command(state):
    if state == 'on':
        relay.on()
    elif state == 'off':
        relay.off()
    else:
        return False
    return True

class RelayHandler(BaseHTTPRequestHandler):
    def do_POST(self):
        if self.path != '/relay':
            self.send_response(404)
            self.end_headers()
            return
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length == 0:
            self.send_error(400, 'Invalid request: empty body')
            return
        try:
            body = self.rfile.read(content_length).decode('utf-8')
            data = json.loads(body)
        except (json.JSONDecodeError, UnicodeDecodeError) as e:
            self.send_error(400, f'Invalid request: {e}')
            return
        if not isinstance(data, dict):
            self.send_error(400, 'Invalid request: payload must be a JSON object')
            return
        state = data.get('state')
        if state not in ('on', 'off'):
            self.send_error(400, 'Invalid request: state must be "on" or "off"')
            return
        if not handle_relay_command(state):
            self.send_error(400, 'Invalid request: state must be "on" or "off"')
            return
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.end_headers()
        self.wfile.write(json.dumps({'status': 'Relay state changed'}).encode('utf-8'))

def main():
    global relay
    signal.signal(signal.SIGINT, cleanup)
    signal.signal(signal.SIGTERM, cleanup)
    try:
        relay = OutputDevice(RELAY_PIN)
    except GPIOZeroError as e:
        print(f'Failed to initialize GPIO{RELAY_PIN}: {e}', file=sys.stderr)
        sys.exit(1)
    except Exception as e:
        print(f'Unexpected error initializing GPIO: {e}', file=sys.stderr)
        sys.exit(1)
    try:
        with HTTPServer(SERVER_ADDRESS, RelayHandler) as httpd:
            print(f'Server listening on {SERVER_ADDRESS[0]}:{SERVER_ADDRESS[1]}')
            httpd.serve_forever()
    except OSError as e:
        print(f'Network error: {e}', file=sys.stderr)
    finally:
        cleanup()

if __name__ == '__main__':
    main()

