import time
import signal
import sys
from typing import Optional

try:
    from adafruit_servokit import ServoKit
except ImportError:
    ServoKit = None

# Constants for servo control
SERVO_CHANNEL = 0
GRAB_ANGLE = 90
RELEASE_ANGLE = 150
STEP_SIZE = 5
STEP_DELAY = 0.04

# Global flag for graceful shutdown
_running = True


def _signal_handler(signum, frame):
    """Handle SIGINT/SIGTERM for clean shutdown."""
    global _running
    _running = False


def initialize_servo_kit() -> Optional["ServoKit"]:
    """Initializes the ServoKit object on I2C bus 1.

    Returns:
        ServoKit: The initialized ServoKit object, or None if unavailable.
    """
    if ServoKit is None:
        print("Error: adafruit_servokit library not installed.")
        return None
    try:
        kit = ServoKit(channels=16, i2c=None, address=0x40)
        return kit
    except (OSError, ValueError) as e:
        print(f"Error initializing ServoKit: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error initializing ServoKit: {e}")
        return None


def move_servo(kit: "ServoKit", servo_channel: int, target_angle: int) -> bool:
    """Moves a servo to a target angle in 5-degree steps.

    Args:
        kit: The initialized ServoKit object.
        servo_channel: The channel of the servo to move (0-15).
        target_angle: The target angle (0-180).

    Returns:
        True if the movement was successful, False otherwise.
    """
    if not 0 <= servo_channel <= 15:
        print(f"Error: Invalid servo channel {servo_channel}. Must be 0-15.")
        return False
    if not 0 <= target_angle <= 180:
        print(f"Error: Invalid target angle {target_angle}. Must be 0-180.")
        return False

    try:
        current_angle = kit.servo[servo_channel].angle
        if current_angle is None:
            current_angle = 0
    except (OSError, ValueError) as e:
        print(f"Error reading current angle on channel {servo_channel}: {e}")
        return False

    try:
        if current_angle < target_angle:
            angle_range = range(int(current_angle), target_angle + 1, STEP_SIZE)
        else:
            angle_range = range(int(current_angle), target_angle - 1, -STEP_SIZE)

        for angle in angle_range:
            if not _running:
                print("Movement interrupted by shutdown signal.")
                return False
            kit.servo[servo_channel].angle = angle
            time.sleep(STEP_DELAY)

        kit.servo[servo_channel].angle = target_angle
        return True
    except (OSError, ValueError) as e:
        print(f"Error moving servo on channel {servo_channel}: {e}")
        return False
    except Exception as e:
        print(f"Unexpected error moving servo: {e}")
        return False


def grab_object(kit: "ServoKit") -> bool:
    """Grabs an object by moving the servo to the grab angle."""
    print("Grabbing object...")
    return move_servo(kit, SERVO_CHANNEL, GRAB_ANGLE)


def release_object(kit: "ServoKit") -> bool:
    """Releases an object by moving the servo to the release angle."""
    print("Releasing object...")
    return move_servo(kit, SERVO_CHANNEL, RELEASE_ANGLE)


def main() -> None:
    """Main function to demonstrate servo control."""
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    kit = initialize_servo_kit()
    if kit is None:
        print("Failed to initialize ServoKit. Exiting.")
        sys.exit(1)

    try:
        if grab_object(kit):
            if release_object(kit):
                print("Object grabbed and released successfully.")
            else:
                print("Failed to release object.")
        else:
            print("Failed to grab object.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        print("Program finished.")


if __name__ == "__main__":
    main()

