import RPi.GPIO as GPIO

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
ALARM_PIN = 18
RADIATION_THRESHOLD = 50.0

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def initialize_serial(port, baud, timeout):
    try:
        ser = serial.Serial(port, baud, timeout=timeout)
        ser.reset_input_buffer()
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port {port}: {e}", file=sys.stderr)
        return None

def read_radiation_level(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        return float(line)
    except ValueError:
        print(f"Warning: non-numeric data received: {line!r}", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial read error: {e}", file=sys.stderr)
        return None

def set_alarm_state(pin, state):
    GPIO.output(pin, state)

def cleanup(ser):
    if ser and ser.is_open:
        ser.close()
    GPIO.cleanup()

def main():
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)

    GPIO.setmode(GPIO.BCM)
    GPIO.setup(ALARM_PIN, GPIO.OUT, initial=GPIO.LOW)

    ser = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if ser is None:
        GPIO.cleanup()
        sys.exit(1)

