import serial
import time
import signal
import sys
import logging
from gpiozero import OutputDevice

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
SERIAL_TIMEOUT = 1
ALARM_PIN = 18
ALARM_THRESHOLD = 50.0
READ_INTERVAL = 1

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

_running = True

def _signal_handler(signum, frame):
    global _running
    _running = False

def open_serial_port(port, baudrate, timeout):
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        logging.info(f"Opened serial port {port} at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Error opening serial port {port}: {e}")
        return None

def read_radiation_level(ser):
    try:
        raw = ser.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        try:
            return float(line)
        except ValueError:
            logging.warning(f"Non-numeric data received: {line!r}")
            return None
    except serial.SerialException as e:
        logging.error(f"Error reading from serial port: {e}")
        return None

def set_alarm(alarm, level, threshold):
    if level > threshold:
        if not alarm.is_active:
            alarm.on()
            logging.warning(f"ALARM: Radiation level {level:.2f} µSv/h exceeds threshold {threshold:.1f} µSv/h.")
    else:
