import serial
import signal
import sys
import logging
from dataclasses import dataclass
from typing import Optional, Tuple

logging.basicConfig(
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)


@dataclass
class GPS_readings:
    latitude: float
    longitude: float
    altitude: float
    satellites: int


class GPSReader:
    """
    Reads and parses NMEA GPGGA sentences from a serial GPS module on a
    Raspberry Pi.  Designed to be used in a context manager so that
    disconnect() is always called on exit.
    """

    def __init__(self, port: str = '/dev/serial0',
                 baudrate: int = 9600, timeout: float = 1.0):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.uart: Optional[serial.Serial] = None

    def connect(self) -> bool:
        """Open the serial port.  Returns True on success, False on failure."""
        try:
            self.uart = serial.Serial(
                port=self.port,
                baudrate=self.baudrate,
                bytesize=serial.EIGHTBITS,
                parity=serial.PARITY_NONE,
                stopbits=serial.STOPBITS_ONE,
                timeout=self.timeout,
            )
            logging.info(f"Connected to GPS on {self.port} "
                         f"@ {self.baudrate} baud (8N1).")
            return True
        except serial.SerialException as exc:
            logging.error(f"Failed to open {self.port}: {exc}")
            self.uart = None
            return False
        except OSError as exc:
            logging.error(f"OS error opening {self.port}: {exc}")
            self.uart = None
            return False

    def disconnect(self) -> None:
        """Close the serial port if open.  Idempotent; never raises."""
        if self.uart is not None:
            try:
                if self.uart.is_open:
                    self.uart.close()
                    logging.info("GPS serial port closed.")
            except Exception as exc:
                logging.error(f"Error closing serial port: {exc}")
            finally:
                self.uart = None

    def __enter__(self):
        self.connect()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.disconnect()
        return False

    @staticmethod
    def _verify_checksum(sentence: str) -> bool:
        """Validate NMEA checksum: *<CS> must match XOR of payload chars."""
        if not sentence.startswith('$') or '*' not in sentence:
            return False
        payload, _, csum_str = sentence[1:].partition('*')
        try:
            expected = int(csum_str.strip(), 16)
        except ValueError:
            return False
        computed = 0
        for ch in payload:
            computed ^= ord(ch)
        return computed == expected

    def read_gps_data(self) -> Optional[GPS_readings]:
        """
        Read one line, parse GPGGA, and return a GPS_readings dataclass.
        Returns None on timeout, checksum failure, parse error, or invalid
        talker ID (not GG).
        """
        if self.uart is None or not self.uart.is_open:
            logging.error("Serial port not open; cannot read.")
            return None

        try:
            raw = self.uart.readline()
        except serial.SerialException as exc:
            logging.error(f"Serial read error: {exc}")
            return None
        except OSError as exc:
            logging.error(f"OS read error: {exc}")
            return None

        if not raw:
            return None  # timeout

        try:
            sentence = raw.decode('ascii', errors='replace').strip()
        except Exception as exc:
            logging.error(f"Decode error: {exc}")
            return None

        if not sentence:
            return None

        if not sentence.startswith('$GPGGA'):
            return None  # not a GPGGA sentence

        if not self._verify_checksum(sentence):
            logging.warning(f"Checksum mismatch on: {sentence}")
            return None

        try:
            fields = sentence.split(',')
        except Exception as exc:
            logging.error(f"Split error: {exc}")
            return None

        if len(fields) < 15:
            logging.warning(f"Short GPGGA sentence (len {len(fields)}): {sentence}")
            return None

        talker = fields[0]
        if talker != '$GPGGA':
            logging.warning(f"Unexpected talker ID: {talker}")
            return None

        try:
            fix_quality = int(fields[6])
        except ValueError:
            logging.warning("Invalid fix quality field.")
            return None

        if fix_quality == 0:
            logging.info("No GPS fix available.")
            return None

        try:
            latitude = self._nmea_to_decimal(fields[2], fields[3])
            longitude = self._nmea_to_decimal(fields[4], fields[5])
        except (ValueError, IndexError) as exc:
            logging.error(f"Latitude/longitude parse error: {exc}")
            return None

        try:
            altitude = float(fields[9])
        except ValueError:
            logging.error("Invalid altitude field.")
            return None

        try:
            satellites = int(fields[7])
        except ValueError:
            logging.error("Invalid satellite count field.")
            return None

        return GPS_readings(
            latitude=latitude,
            longitude=longitude,
            altitude=altitude,
            satellites=satellites,
        )

    @staticmethod
    def _nmea_to_decimal(value: str, direction: str) -> float:
        """
