import serial
import time
import signal
import sys
from datetime import datetime

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1
LOG_FILE = 'health_readings_log.txt'

running = True
serial_connection = None

def signal_handler(signum, frame):
    global running
    running = False

def initialize_serial(port, baud, timeout):
    try:
        return serial.Serial(port, baud, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}", file=sys.stderr)
        return None

def read_pulse_oximeter_data(serial_port):
    try:
        raw = serial_port.readline()
        if not raw:
            return None
        line = raw.decode('ascii', errors='replace').strip()
        if not line:
            return None
        parts = line.split(',')
        if len(parts) != 2:
            return None
        heart_rate, spo2 = int(parts[0]), int(parts[1])
        return heart_rate, spo2
    except ValueError:
        print("Error: Invalid data format received from pulse oximeter.", file=sys.stderr)
        return None
    except serial.SerialException as e:
        print(f"Serial communication error: {e}", file=sys.stderr)
        return None

def log_data(timestamp, heart_rate, spo2, log_file):
    try:
        with open(log_file, 'a') as f:
            f.write(f"{timestamp}, {heart_rate}, {spo2}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    global serial_connection
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        sys.exit(1)
    try:
        while running:
            data = read_pulse_oximeter_data(serial_connection)
            if data is not None:
                heart_rate, spo2 = data
                timestamp = datetime.now().isoformat()
                print(f"{timestamp}, Heart Rate: {heart_rate} bpm, SpO2: {spo2}%")
                log_data(timestamp, heart_rate, spo2, LOG_FILE)
            time.sleep(0.1)
    except Exception as e:
        print(f"Unexpected error: {e}", file=sys.stderr)
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

