import signal
import threading
import time
from http import HTTPStatus
from typing import Any, Dict, List, Optional

from flask import Flask, Response, jsonify, request

try:
    import serial
    from serial import SerialException
except ImportError:  # pragma: no cover
    serial = None  # type: ignore
    SerialException = Exception  # type: ignore

app = Flask(__name__)

# ---------------------------------------------------------------------------
# In-memory data store
# ---------------------------------------------------------------------------
data_store_lock = threading.Lock()
data_store: List[Dict[str, Any]] = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]


def get_data_store() -> List[Dict[str, Any]]:
    """Return a copy of the in-memory data store."""
    with data_store_lock:
        return list(data_store)


def add_item(item: Dict[str, Any]) -> Optional[int]:
    """Add a validated item to the data store and return its new id, or None."""
    if not isinstance(item, dict):
        return None
    name = item.get("name")
    if not isinstance(name, str) or not name.strip():
        return None
    done = bool(item.get("done", False))
    with data_store_lock:
        new_id = (data_store[-1]["id"] + 1) if data_store else 1
        data_store.append({"id": new_id, "name": name.strip(), "done": done})
    return new_id


def get_item(item_id: int) -> Optional[Dict[str, Any]]:
    """Return the item with the given id, or None."""
    with data_store_lock:
        return next((it for it in data_store if it["id"] == item_id), None)


def update_item(item_id: int, updates: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Update an existing item and return the updated dict, or None."""
    with data_store_lock:
        item = next((it for it in data_store if it["id"] == item_id), None)
        if item is None:
            return None
        if "name" in updates:
            name = updates.get("name")
            if isinstance(name, str) and name.strip():
                item["name"] = name.strip()
        if "done" in updates:
            item["done"] = bool(updates.get("done", False))
        return item


# ---------------------------------------------------------------------------
# UART helpers
# ---------------------------------------------------------------------------
_uart_lock = threading.Lock()
_uart: Optional["serial.Serial"] = None


def open_uart(port: str = "/dev/ttyUSB0", baudrate: int = 9600, timeout: float = 1.0) -> Optional["serial.Serial"]:
    """Open (or re-open) the UART port; return the Serial object or None."""
    global _uart
    if _uart is not None and _uart.is_open:
        return _uart
    with _uart_lock:
        if _uart is not None and _uart.is_open:
            return _uart
        if serial is None:
            print("serial module unavailable; cannot open UART.")
            return None
        try:
            _uart = serial.Serial(port, baudrate=baudrate, bytesize=8, parity="N", stopbits=1, timeout=timeout)
            print(f"UART opened: {port} @ {baudrate} baud")
            return _uart
        except SerialException as exc:
            print(f"Error opening UART {port}: {exc}")
            _uart = None
            return None


def close_uart() -> None:
    """Close the UART port if it is open."""
    global _uart
    with _uart_lock:
        if _uart is not None and _uart.is_open:
            try:
                _uart.close()
            except SerialException as exc:
                print(f"Error closing UART: {exc}")
        _uart = None


# ---------------------------------------------------------------------------
# Web service endpoints
# ---------------------------------------------------------------------------
@app.route("/data", methods=["GET"])
def get_all_data() -> Response:
    """Return all items as JSON."""
    return jsonify(get_data_store())


@app.route("/data/<int:item_id>", methods=["GET"])
def get_specific_data(item_id: int) -> Response:
    """Return a single item by id."""
    item = get_item(item_id)
    if item is not None:
        return jsonify(item)
    return Response("Item not found", status=HTTPStatus.NOT_FOUND, mimetype="text/plain")


@app.route("/data", methods=["POST"])
def add_data() -> Response:
    """Create a new item from the JSON request body."""
    try:
        new_item = request.get_json(silent=True)
        if not isinstance(new_item, dict):
            return Response("Invalid input: expected JSON object", status=HTTPStatus.BAD_REQUEST, mimetype="text/plain")
        name = new_item.get("name")
        if not isinstance(name, str) or not name.strip():
            return Response("Invalid input: name is required and must be a non-empty string", status=HTTPStatus.BAD_REQUEST, mimetype="text/plain")
