import signal
import threading
import time
from http import HTTPStatus
from typing import Any, Dict, List, Optional

from flask import Flask, Response, jsonify, request

try:
    import serial
    from serial import SerialException
except ImportError:  # pragma: no cover
    serial = None  # type: ignore
    SerialException = Exception  # type: ignore

app = Flask(__name__)

# ---------------------------------------------------------------------------
# In-memory data store
# ---------------------------------------------------------------------------
data_store_lock = threading.Lock()
data_store: List[Dict[str, Any]] = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False},
]


def get_data_store() -> List[Dict[str, Any]]:
    """Return a copy of the in-memory data store."""
    with data_store_lock:
        return list(data_store)


def add_item(item: Dict[str, Any]) -> Optional[int]:
    """Add a validated item to the data store and return its new id, or None."""
    if not isinstance(item, dict):
        return None
    name = item.get("name")
    if not isinstance(name, str) or not name.strip():
        return None
    done = bool(item.get("done", False))
    with data_store_lock:
        new_id = (data_store[-1]["id"] + 1) if data_store else 1
        data_store.append({"id": new_id, "name": name.strip(), "done": done})
    return new_id


def get_item(item_id: int) -> Optional[Dict[str, Any]]:
    """Return the item with the given id, or None."""
    with data_store_lock:
        return next((it for it in data_store if it["id"] == item_id), None)


def update_item(item_id: int, updates: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Update an existing item and return the updated dict, or None."""
    with data_store_lock:
        item = next((it for it in data_store if it["id"] == item_id), None)
        if item is None:
            return None
        if "name" in updates:
            name = updates.get("name")
            if isinstance(name, str) and name.strip():
                item["name"] = name.strip()
        if "done" in updates:
            item["done"] = bool(updates.get("done", False))
        return item


