    """Open (or re-open) the UART port; return the Serial object or None."""
    global _uart
    if _uart is not None and _uart.is_open:
        return _uart
    with _uart_lock:
        if _uart is not None and _uart.is_open:
            return _uart
        if serial is None:
            print("serial module unavailable; cannot open UART.")
            return None
        try:
            _uart = serial.Serial(port, baudrate=baudrate, bytesize=8, parity="N", stopbits=1, timeout=timeout)
            print(f"UART opened: {port} @ {baudrate} baud")
            return _uart
        except SerialException as exc:
            print(f"Error opening UART {port}: {exc}")
            _uart = None
            return None


