import json
import signal
import sys
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any, Dict, List, Optional

import serial

SERIAL_PORT = "/dev/ttyUSB0"
BAUDRATE = 9600
SERIAL_TIMEOUT = 1.0
SERIAL_POST_READ_DELAY = 0.1

DATA: List[Dict[str, Any]] = [
    {"id": 1, "name": "Apple", "done": False},
    {"id": 2, "name": "Orange", "done": False},
]

_running = True


def _signal_handler(signum: int, frame: Any) -> None:
    global _running
    _running = False


def get_serial_connection() -> Optional[serial.Serial]:
    try:
        return serial.Serial(
            port=SERIAL_PORT,
            baudrate=BAUDRATE,
            bytesize=serial.EIGHTBITS,
            parity=serial.PARITY_NONE,
            stopbits=serial.STOPBITS_ONE,
            timeout=SERIAL_TIMEOUT,
        )
    except serial.SerialException as exc:
        print(f"Error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error opening serial port {SERIAL_PORT}: {exc}", file=sys.stderr)
        return None


def send_command_and_read_response(
    command: str, conn: serial.Serial
) -> Optional[str]:
    try:
        conn.write(command.encode("ascii"))
        time.sleep(SERIAL_POST_READ_DELAY)
        response = conn.read(1024)
        if not response:
            print("Serial read returned empty response.", file=sys.stderr)
            return None
        return response.decode("ascii", errors="replace")
    except serial.SerialException as exc:
        print(f"Serial communication error: {exc}", file=sys.stderr)
        return None
    except OSError as exc:
        print(f"OS error during serial I/O: {exc}", file=sys.stderr)
        return None


class RequestHandler(BaseHTTPRequestHandler):
    def _send_json(self, data: Any, status: int = 200) -> None:
        payload = json.dumps(data).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        self.end_headers()
        try:
            self.wfile.write(payload)
        except BrokenPipeError:
            pass

    def _send_html(self, content: str, status: int = 200) -> None:
        body = (
            "<html><head><title>SCPI Response</title></head>"
            f"<body><h1>SCPI Response</h1><p>{content}</p></body></html>"
        ).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "text/html")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        try:
            self.wfile.write(body)
        except BrokenPipeError:
            pass

    def _send_error(self, message: str, status: int = 500) -> None:
        self._send_html(f"<strong>Error:</strong> {message}", status)

    def do_GET(self) -> None:
        if self.path == "/version":
            conn = get_serial_connection()
            if conn is None:
                self._send_error("Failed to open serial port.", 503)
                return
            try:
                response = send_command_and_read_response("*IDN?\n", conn)
                if response is None:
                    self._send_error("No response from device.", 503)
                    return
                self._send_html(response.replace("\n", "<br>"))
            finally:
                conn.close()
        elif self.path == "/getdata":
            self._send_json(DATA)
        elif self.path.startswith("/getset/"):
            try:
                item_id = int(self.path.split("/")[2])
            except (ValueError, IndexError):
                self._send_error("Invalid item ID.", 400)
                return
            item = next((it for it in DATA if it["id"] == item_id), None)
            if item is None:
                self._send_error(f"Item with id {item_id} not found.", 404)
                return
            self._send_json(item)
        else:
            self._send_error("Not found.", 404)

    def do_POST(self) -> None:
        if self.path == "/postjson":
            content_type = self.headers.get("Content-Type", "")
            if "application/json" in content_type:
                length = self.headers.get("Content-Length", "0")
                try:
                    raw = self.rfile.read(int(length))
                except (ValueError, OSError) as exc:
                    self._send_error(f"Read error: {exc}", 400)
                    return
                try:
                    data = json.loads(raw.decode("utf-8"))
                except json.JSONDecodeError as exc:
                    self._send_error(f"Invalid JSON: {exc}", 400)
                    return
            elif "application/x-www-form-urlencoded" in content_type:
                length = self.headers.get("Content-Length", "0")
                try:
                    raw = self.rfile.read(int(length))
                except (ValueError, OSError) as exc:
                    self._send_error(f"Read error: {exc}", 400)
                    return
                data = self._parse_form_data(raw.decode("utf-8"))
            else:
                self._send_error("Unsupported Content-Type.", 400)
                return
            try:
                new_id = DATA[-1]["id"] + 1 if DATA else 1
            except IndexError:
                new_id = 1
            data["id"] = new_id
            data.setdefault("name", "")
            data.setdefault("done", False)
            data["done"] = self._normalize_done(data["done"])
            DATA.append(data)
            self._send_json(DATA, 201)
        else:
            self._send_error("Not found.", 404)

    @staticmethod
    def _normalize_done(value: Any) -> bool:
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.strip().lower() in ("true", "1", "yes")
        return bool(value)

    @staticmethod
    def _parse_form_data(data: str) -> Dict[str, Any]:
        params: Dict[str, Any] = {}
        pairs = data.split("&")
        for pair in pairs:
            if "=" in pair:
                key, _, val = pair.partition("=")
                params[key.strip()] = val.strip()
        params["done"] = params.get("done", False)
        return params


def main() -> None:
    signal.signal(signal.SIGINT, _signal_handler)
    signal.signal(signal.SIGTERM, _signal_handler)
    server = ThreadingHTTPServer(("0.0.0.0", 8080), RequestHandler)
    print("Serving at http://0.0.0.0:8080")
    try:
        while _running:
            server.handle_request()
    except OSError as exc:
        print(f"Server error: {exc}", file=sys.stderr)
    finally:
        server.server_close()


if __name__ == "__main__":
    main()

