import serial
import time
import sys

BLUETOOTH_PORT = "/dev/rfcomm4"
BAUD_RATE = 38400
TRANSMIT_DELAY = 0.1


def send_command(api, command):
    """Send a prefixed command string over the Bluetooth serial connection."""
    payload = f"X{command}\n"
    api.write(payload.encode("utf-8"))
    api.flush()
    time.sleep(TRANSMIT_DELAY)


def main():
    api = None
    try:
        api = serial.Serial(BLUETOOTH_PORT, BAUD_RATE, timeout=1)
        print(f"Connected to {BLUETOOTH_PORT} at {BAUD_RATE} baud.")

        while True:
            try:
                user_command = input("Enter command (or 'exit' to quit): ")
            except EOFError:
                print("\nEOF received, exiting.")
                break

            if user_command.lower() == "exit":
                print("Exiting program.")
                break

            try:
                send_command(api, user_command)
                print(f"Sent: {user_command}")
            except serial.SerialException as e:
                raise RuntimeError(f"Failed to send command: {e}") from e

    except serial.SerialException as e:
        print(f"Error: Could not connect to Bluetooth device at {BLUETOOTH_PORT}: {e}", file=sys.stderr)
        sys.exit(1)
    except KeyboardInterrupt:
        print("\nProgram interrupted by user.")
    finally:
        if api is not None and api.is_open:
            api.close()
            print("Bluetooth connection closed.")


if __name__ == "__main__":
    main()

